-- Añade el examen AI-201 (Salesforce Certified Agentforce Specialist) con 500 preguntas en español e inglés.
-- Reparto por dominio: D1 175, D2 100, D3 100, D4 100, D5 25.
-- Requisito: haber ejecutado antes 20261123_ccdvf_ingles.sql (columna questions.i18n).
-- Ejecutar en Supabase: SQL Editor > New query > pegar > Run.
-- Si el examen ya existe no hace nada, así que se puede ejecutar varias veces sin borrar
-- el progreso de nadie. Para reemplazar sus preguntas usa Administración > Importar.
do $do$
begin
  if exists (select 1 from public.exams where slug = 'salesforce-agentforce-specialist') then
    raise notice 'El examen salesforce-agentforce-specialist ya existe: no se ha modificado.';
  else
    perform public.import_exam_unchecked($exam${"slug":"salesforce-agentforce-specialist","name":"Salesforce Certified Agentforce Specialist","vendor":"Salesforce","code":"AI-201","language":"es","description":"Preguntas de práctica escritas a partir de la guía oficial del examen de Salesforce. La guía no indica la duración; se usan 105 minutos como en el resto de exámenes de Salesforce. No son preguntas del examen real.","exam":{"questions":60,"minutes":105,"passing":"73%","mini":{"questions":20,"minutes":35}},"domains":[{"code":"D1","name":"AI Agents","weight":35,"docs":[{"title":"Agentforce Specialist cert prep (Trailhead)","url":"https://trailhead.salesforce.com/content/learn/modules/cert-prep-agentforce-specialist"},{"title":"Agent Builder basics","url":"https://trailhead.salesforce.com/content/learn/modules/agent-builder-basics"}]},{"code":"D2","name":"Prompt Engineering","weight":20,"docs":[{"title":"Review prompt engineering (cert prep)","url":"https://trailhead.salesforce.com/content/learn/modules/cert-prep-agentforce-specialist/review-prompt-engineering"}]},{"code":"D3","name":"Data Cloud for Agentforce","weight":20,"docs":[{"title":"Review Data Cloud for Agentforce (cert prep)","url":"https://trailhead.salesforce.com/content/learn/modules/cert-prep-agentforce-specialist/review-data-cloud-for-agentforce"},{"title":"Review Agentforce and Data Cloud","url":"https://trailhead.salesforce.com/content/learn/modules/cert-prep-agentforce-specialist/review-agentforce-and-data-cloud"}]},{"code":"D4","name":"Deployment Lifecycle","weight":20,"docs":[{"title":"Agentforce agent testing (Trailhead)","url":"https://trailhead.salesforce.com/content/learn/modules/agentforce-agent-testing"},{"title":"Agent testing tools and considerations","url":"https://trailhead.salesforce.com/content/learn/modules/agentforce-testing-tools-and-strategies/explore-agent-testing-tools-and-considerations"}]},{"code":"D5","name":"Multi-Agent Interoperability","weight":5,"docs":[{"title":"Agent API Developer Guide","url":"https://developer.salesforce.com/docs/ai/agentforce/guide/agent-api.html"},{"title":"Build custom AI agents with Agent API","url":"https://trailhead.salesforce.com/content/learn/modules/agent-api-quick-look/build-custom-ai-agents-with-agent-api"}]}],"questions":[{"domain":"D1","source":"bank","stem":"¿Qué componente de Agentforce interpreta la petición del usuario, elige el tema y decide qué acciones ejecutar?","options":["El motor de razonamiento (Atlas Reasoning Engine)","La capa de confianza, que elige la acción más segura según los permisos","El conjunto de permisos del usuario del agente asignado en la configuración","El canal de mensajería que recibe la conversación del cliente"],"correct":[0],"explanation":"El motor de razonamiento clasifica la intención, selecciona tema y planifica acciones.","i18n":{"en":{"stem":"Which Agentforce component interprets the user's request, picks the topic and decides which actions to run?","options":["The reasoning engine (Atlas Reasoning Engine)","The trust layer, which picks the safest action by permissions","The agent user's permission set assigned in setup","The messaging channel receiving the customer's conversation"],"explanation":"The reasoning engine classifies intent, selects a topic and plans actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué tres elementos definen principalmente un tema (topic) de un agente?","options":["Un objeto de Salesforce, un diseño de página y un perfil de usuario asociado","Un modelo de lenguaje, una temperatura y un límite de tokens fijo","Descripción de clasificación, ámbito e instrucciones, más sus acciones","Un canal, una cola de Omni-Channel y un horario comercial"],"correct":[2],"explanation":"Los topics tienen classification description, scope, instructions y actions.","i18n":{"en":{"stem":"Which elements mainly define an agent topic?","options":["A Salesforce object, a page layout and an associated user profile","A language model, a temperature and a fixed token limit","Classification description, scope and instructions, plus its actions","A channel, an Omni-Channel queue and business hours"],"explanation":"Topics have a classification description, scope, instructions and actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué campo del tema usa el motor de razonamiento para decidir si una petición pertenece a ese tema?","options":["La descripción de clasificación","Las instrucciones detalladas de cada acción incluida en el tema","El orden en que aparece el tema en el constructor","El nombre de la API del tema, que debe coincidir con la intención"],"correct":[0],"explanation":"La classification description indica qué tipo de peticiones cubre.","i18n":{"en":{"stem":"Which topic field does the reasoning engine use to decide whether a request belongs to it?","options":["The classification description","The detailed instructions of each action in the topic","The order the topic appears in the builder","The topic API name, which must match the intent"],"explanation":"The classification description says what requests it covers."}}},{"domain":"D1","source":"bank","stem":"¿Qué debe describir el ámbito (scope) de un tema?","options":["La lista de usuarios internos que pueden editar el tema en producción","El idioma y el tono que debe usar el agente en todos los temas","Los objetos de Salesforce cuyos registros se borran al cerrar la conversación","El trabajo que el agente puede hacer en ese tema y sus límites"],"correct":[3],"explanation":"Scope define el puesto y las tareas del agente en ese tema.","i18n":{"en":{"stem":"What should a topic's scope describe?","options":["The internal users who can edit the topic in production","The language and tone the agent should use in all topics","The objects whose records are deleted when the chat ends","The job the agent can do in that topic and its limits"],"explanation":"Scope defines the agent's job and tasks in that topic."}}},{"domain":"D1","source":"bank","stem":"Un agente de servicio responde sobre devoluciones pero también se pone a hablar de política. ¿Qué mejora más el comportamiento?","options":["Instrucciones de tema que limiten lo que no debe tratar","Subir la temperatura del modelo para que sea más creativo al contestar","Añadir más acciones de flujo al tema de devoluciones","Quitar la descripción de clasificación del tema"],"correct":[0],"explanation":"Las instrucciones y el ámbito actúan como barreras; los temas estándar de fuera de ámbito ayudan.","i18n":{"en":{"stem":"A service agent answers about returns but also chats about politics. What improves behavior most?","options":["Topic instructions limiting what it must not handle","Raising model temperature so it's more creative","Adding more flow actions to the returns topic","Removing the topic's classification description"],"explanation":"Instructions and scope act as guardrails; standard off-topic topics help."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipos de recursos pueden configurarse como acciones de agente? (Elige 2)","options":["Reglas de validación de los objetos que usa el agente","Flujos autolanzados","Métodos Apex invocables","Informes matriciales con fórmulas de resumen","Diseños de página compactos para la app móvil"],"correct":[1,2],"explanation":"Acciones: flujos, Apex invocable, plantillas de prompt, acciones estándar y APIs (p. ej. MuleSoft/External Services).","i18n":{"en":{"stem":"Which resource types can be configured as agent actions? (Choose 2)","options":["Validation rules on objects the agent uses","Autolaunched flows","Invocable Apex methods","Matrix reports with summary formulas","Compact layouts for the mobile app"],"explanation":"Actions: flows, invocable Apex, prompt templates, standard actions and APIs (e.g. MuleSoft/External Services)."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de flujo se puede usar como acción de agente?","options":["Flujo de orquestación con etapas manuales","Flujo de pantalla con varias pantallas de entrada para el cliente","Autolanzado (sin pantallas)","Flujo desencadenado por registro before-save"],"correct":[2],"explanation":"Las acciones de agente usan flujos autolanzados con variables de entrada y salida.","i18n":{"en":{"stem":"Which flow type can be used as an agent action?","options":["An orchestration flow with manual stages","A screen flow with several customer input screens","Autolaunched (no screens)","A before-save record-triggered flow"],"explanation":"Agent actions use autolaunched flows with input and output variables."}}},{"domain":"D1","source":"bank","stem":"¿Qué hay que hacer en un flujo para que el agente le pase un dato como el número de pedido?","options":["Guardar el número en un campo personalizado del usuario del agente","Crear una pantalla en el flujo con un campo de texto para el número","Definirlo como constante dentro del flujo","Marcar la variable como disponible para entrada"],"correct":[3],"explanation":"Las variables Available for input/output se exponen como entradas y salidas de la acción.","i18n":{"en":{"stem":"What must be done in a flow so the agent can pass in a value like the order number?","options":["Store the number in a custom field on the agent user","Add a screen with a text field for the number","Define it as a constant in the flow","Mark the variable available for input"],"explanation":"Available for input/output variables become the action's inputs and outputs."}}},{"domain":"D1","source":"bank","stem":"¿Para qué sirven las instrucciones de una acción y de sus entradas?","options":["Mostrar un mensaje de error al usuario si la acción falla en producción","Explicar al motor cuándo usarla y qué valor dar a cada entrada","Traducir la salida de la acción a otros idiomas","Asignar permisos de objeto a la acción automáticamente"],"correct":[1],"explanation":"El razonamiento depende de descripciones claras de la acción y de sus parámetros.","i18n":{"en":{"stem":"What are action and input instructions for?","options":["Showing the user an error if the action fails in production","Telling the engine when to use it and what value each input takes","Translating the action's output into other languages","Automatically granting object permissions to the action"],"explanation":"Reasoning depends on clear descriptions of the action and its parameters."}}},{"domain":"D1","source":"bank","stem":"Una acción devuelve datos que el agente no debe mostrar literalmente al usuario. ¿Qué ajuste de salida se revisa?","options":["La temperatura del modelo de la plantilla de prompt","El nombre del tema que contiene la acción","El tipo de dato de la variable de entrada del flujo","Si la salida se muestra en la conversación"],"correct":[3],"explanation":"Las salidas pueden marcarse para mostrarse o no al usuario (Show in conversation).","i18n":{"en":{"stem":"An action returns data the agent shouldn't show verbatim. Which output setting is checked?","options":["The model temperature of the prompt template","The name of the topic containing the action","The data type of the flow's input variable","Whether the output is shown in the conversation"],"explanation":"Outputs can be set to show or not to the user (Show in conversation)."}}},{"domain":"D1","source":"bank","stem":"¿Qué opción de acción obliga al agente a pedir confirmación antes de ejecutar una acción que cambia datos?","options":["Marcar la salida como visible en la conversación","Requerir confirmación del usuario","Asignar la acción a un tema de solo lectura","Añadir un filtro de tema basado en variables"],"correct":[1],"explanation":"Require user confirmation es recomendable en acciones con efectos.","i18n":{"en":{"stem":"Which action option makes the agent ask for confirmation before running a data-changing action?","options":["Mark the output visible in the conversation","Require user confirmation","Assign the action to a read-only topic","Add a variable-based topic filter"],"explanation":"Require user confirmation is recommended for actions with side effects."}}},{"domain":"D1","source":"bank","stem":"¿Con qué usuario y permisos se ejecutan las acciones de un agente de servicio que atiende a clientes anónimos?","options":["El administrador que activó el agente","El usuario del agente y sus conjuntos de permisos","El propietario del caso que se crea durante la conversación","El usuario invitado del sitio con permisos de administrador del sistema"],"correct":[1],"explanation":"Los agentes de servicio corren como un agent user con permisos mínimos.","i18n":{"en":{"stem":"Which user and permissions do a service agent's actions run with for anonymous customers?","options":["The admin who activated the agent","The agent user and its permission sets","The owner of the case created during the chat","The site guest user with system admin permissions"],"explanation":"Service agents run as an agent user with least privilege."}}},{"domain":"D1","source":"bank","stem":"Un agente de servicio falla al ejecutar un flujo que lee pedidos. Funciona en la vista previa del administrador. ¿Qué se revisa primero?","options":["Que la temperatura del modelo sea cero","Que el usuario del agente tenga acceso al flujo y al objeto","Que el administrador tenga el perfil de administrador del sistema activo","Que el tema tenga menos de cinco acciones"],"correct":[1],"explanation":"Los permisos del agent user (objeto, campos, flujo, Apex) suelen causar fallos en producción.","i18n":{"en":{"stem":"A service agent fails running a flow that reads orders. It works in the admin preview. What's checked first?","options":["That model temperature is zero","That the agent user has access to the flow and object","That the admin's system admin profile is active","That the topic has fewer than five actions"],"explanation":"The agent user's permissions (object, fields, flow, Apex) often cause production failures."}}},{"domain":"D1","source":"bank","stem":"¿Qué diferencia principal hay entre un agente de empleados y un agente de servicio?","options":["El de servicio solo puede usar acciones estándar y nunca flujos ni Apex","El de empleados actúa con los permisos del usuario interno que lo usa","No hay diferencias de seguridad entre ambos","El de empleados no puede leer datos de Salesforce"],"correct":[1],"explanation":"Los agentes de empleados (asistente) respetan el acceso del usuario; los de servicio usan un agent user.","i18n":{"en":{"stem":"What's the main difference between an employee agent and a service agent?","options":["The service agent can only use standard actions, never flows or Apex","The employee agent acts with the internal user's permissions","There's no security difference","The employee agent can't read Salesforce data"],"explanation":"Employee agents (assistant) honor user access; service agents use an agent user."}}},{"domain":"D1","source":"bank","stem":"¿Qué temas estándar suele incluir un agente para manejar peticiones fuera de su alcance o poco claras? (Elige 2)","options":["Tema de cambio de contraseña del administrador","Pregunta ambigua (Ambiguous Question)","Tema de borrado masivo de registros del cliente","Tema de configuración de reglas de colaboración","Fuera de tema (Off Topic)"],"correct":[1,4],"explanation":"Off Topic y Ambiguous Question ayudan a responder con límites y pedir aclaraciones.","i18n":{"en":{"stem":"Which standard topics does an agent often include for out-of-scope or unclear requests? (Choose 2)","options":["Admin password change topic","Ambiguous Question","Mass customer record deletion topic","Sharing rule configuration topic","Off Topic"],"explanation":"Off Topic and Ambiguous Question help answer within limits and ask for clarification."}}},{"domain":"D1","source":"bank","stem":"El cliente pide hablar con una persona. ¿Qué permite al agente de servicio pasar la conversación a un humano?","options":["Una regla de escalado de casos basada en horario comercial","Cerrar la sesión y pedir al cliente que llame por teléfono","El tema de escalado con un flujo de Omni-Channel de salida","Un proceso de aprobación sobre el caso"],"correct":[2],"explanation":"Escalation transfiere a una cola mediante Omni-Channel (outbound flow).","i18n":{"en":{"stem":"The customer asks for a person. What lets the service agent hand off to a human?","options":["A case escalation rule based on business hours","Ending the session and asking the customer to call","The escalation topic with an outbound Omni-Channel flow","An approval process on the case"],"explanation":"Escalation transfers to a queue via Omni-Channel (outbound flow)."}}},{"domain":"D1","source":"bank","stem":"¿Dónde se prueba la conversación con un agente viendo el razonamiento, el tema elegido y las acciones ejecutadas?","options":["En el panel de vista previa de Agentforce Builder","En el registro de depuración de Apex","En la consola de servicio con un caso de prueba real de un cliente","En el Setup Audit Trail"],"correct":[0],"explanation":"La vista previa muestra el plan del motor y permite iterar.","i18n":{"en":{"stem":"Where do you test a conversation with an agent while seeing reasoning, chosen topic and actions?","options":["In Agentforce Builder's preview panel","In the Apex debug log","In the service console with a real customer test case","In Setup Audit Trail"],"explanation":"The preview shows the engine's plan and allows iteration."}}},{"domain":"D1","source":"bank","stem":"¿Qué consideración tiene la vista previa del agente respecto a los datos?","options":["Las acciones pueden ejecutarse de verdad y cambiar datos","Que solo funciona con agentes desactivados en producción","Que siempre usa datos ficticios generados y nunca toca registros","Que no muestra respuestas, solo el plan"],"correct":[0],"explanation":"Las acciones en la vista previa son reales; conviene probar en sandbox.","i18n":{"en":{"stem":"What's a data consideration about the agent preview?","options":["Actions may really run and change data","It only works with deactivated agents in production","It always uses generated fake data and never touches records","It shows no responses, only the plan"],"explanation":"Preview actions are real; test in a sandbox."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Agent Script en el nuevo Agentforce Builder?","options":["El nombre del canal de chat para sitios web","Un lenguaje de consulta para buscar registros en Data Cloud sin SOQL","Un lenguaje para combinar instrucciones y lógica determinista en el agente","Un formato de exportación de conversaciones a CSV"],"correct":[2],"explanation":"Agent Script permite definir flujo determinista (condiciones, variables) junto al razonamiento del LLM.","i18n":{"en":{"stem":"What is Agent Script in the new Agentforce Builder?","options":["The name of the website chat channel","A query language for finding Data Cloud records without SOQL","A language combining instructions and deterministic logic in the agent","A conversation export format to CSV"],"explanation":"Agent Script lets you define deterministic flow (conditions, variables) alongside LLM reasoning."}}},{"domain":"D1","source":"bank","stem":"Un paso del proceso debe ejecutarse siempre en el mismo orden, sin depender de lo que decida el modelo. ¿Qué enfoque es mejor?","options":["Añadir el paso como un tema separado sin acciones","Lógica determinista (Agent Script, filtros o un flujo)","Instrucciones más largas pidiendo al modelo que no se salte pasos","Subir la temperatura del modelo"],"correct":[1],"explanation":"Lo que debe ser predecible se modela con lógica determinista, no solo con instrucciones.","i18n":{"en":{"stem":"A process step must always run in the same order, regardless of the model. Which approach is better?","options":["Adding the step as a separate topic with no actions","Deterministic logic (Agent Script, filters or a flow)","Longer instructions asking the model not to skip steps","Raising model temperature"],"explanation":"Things that must be predictable are modeled deterministically, not just with instructions."}}},{"domain":"D1","source":"bank","stem":"¿Para qué sirven las variables de un agente?","options":["Guardar las credenciales de APIs externas de forma segura","Configurar el idioma de la interfaz del constructor","Definir el número máximo de conversaciones por día","Guardar datos durante la sesión para usarlos en acciones y condiciones"],"correct":[3],"explanation":"Las variables (contexto o personalizadas) almacenan estado y alimentan filtros y acciones.","i18n":{"en":{"stem":"What are agent variables for?","options":["Securely storing external API credentials","Setting the builder UI language","Defining the max conversations per day","Holding session data for use in actions and conditions"],"explanation":"Variables (context or custom) hold state and feed filters and actions."}}},{"domain":"D1","source":"bank","stem":"Un tema solo debe estar disponible si el cliente se ha verificado. ¿Qué se usa?","options":["Un filtro basado en una variable de verificación","Un diseño de página condicional","Un perfil distinto para clientes verificados","Una instrucción pidiendo al modelo que no use el tema sin verificar"],"correct":[0],"explanation":"Los filtros con variables controlan de forma determinista qué temas o acciones están disponibles.","i18n":{"en":{"stem":"A topic should only be available once the customer is verified. What's used?","options":["A filter based on a verification variable","A conditional page layout","A separate profile for verified customers","An instruction asking the model not to use it unverified"],"explanation":"Variable-based filters deterministically control available topics or actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué variables de contexto obtiene un agente de servicio desde la sesión de mensajería? (Elige 2)","options":["El historial de compras de todos los clientes","Datos de la sesión de mensajería, como el usuario final","El salario del agente humano asignado","El canal o identificador de la conversación","La contraseña del cliente en el sitio web"],"correct":[1,3],"explanation":"Las context variables vienen de la sesión (MessagingSession, usuario final, canal).","i18n":{"en":{"stem":"Which context variables does a service agent get from the messaging session? (Choose 2)","options":["Every customer's purchase history","Messaging session data such as the end user","The assigned human agent's salary","The channel or conversation identifier","The customer's website password"],"explanation":"Context variables come from the session (MessagingSession, end user, channel)."}}},{"domain":"D1","source":"bank","stem":"¿Qué acción estándar permite a un agente responder con artículos de Knowledge?","options":["Resumir el registro de la cuenta","Crear un caso nuevo por cada pregunta del cliente","Responder preguntas con Knowledge (Answer Questions with Knowledge)","Enviar un correo con todos los artículos publicados"],"correct":[2],"explanation":"La acción usa RAG sobre Knowledge (vía Agentforce Data Library).","i18n":{"en":{"stem":"Which standard action lets an agent answer using Knowledge articles?","options":["Summarize the account record","Create a new case for every customer question","Answer Questions with Knowledge","Email all published articles"],"explanation":"The action uses RAG over Knowledge (via Agentforce Data Library)."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Agentforce Data Library (ADL)?","options":["Un repositorio de agentes preconfigurados para descargar","Una forma sencilla de dar contenido (Knowledge o archivos) al agente para RAG","Un objeto que guarda las conversaciones para auditoría","Un paquete de AppExchange para migrar datos"],"correct":[1],"explanation":"ADL crea en Data Cloud la ingesta, índice de búsqueda y retriever para anclar respuestas.","i18n":{"en":{"stem":"What is Agentforce Data Library (ADL)?","options":["A repository of preconfigured agents to download","An easy way to give the agent content (Knowledge or files) for RAG","An object storing conversations for audit","An AppExchange package for migrating data"],"explanation":"ADL sets up Data Cloud ingestion, search index and retriever to ground answers."}}},{"domain":"D1","source":"bank","stem":"Un agente inventa políticas de devolución que no existen. ¿Qué medida es la más eficaz?","options":["Cambiar el nombre del tema de devoluciones","Pedir al cliente que valore cada respuesta con un pulgar","Aumentar la longitud máxima de las respuestas","Anclar las respuestas en contenido oficial mediante RAG"],"correct":[3],"explanation":"El grounding con fuentes de la empresa reduce alucinaciones.","i18n":{"en":{"stem":"An agent invents return policies that don't exist. What's the most effective measure?","options":["Rename the returns topic","Ask customers to thumb-rate each answer","Increase max response length","Ground answers in official content via RAG"],"explanation":"Grounding in company sources reduces hallucinations."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos plantillas de agente preconstruidas ofrece Agentforce? (Elige 2)","options":["Agente de copia de seguridad de metadatos","Agente de servicio (Service Agent)","Agente de borrado de usuarios inactivos","Agente de desarrollo de ventas (Sales Development)","Agente de administración de reglas de colaboración"],"correct":[1,3],"explanation":"Hay plantillas como Service Agent, Sales Development Representative, Sales Coach o Agentforce para empleados.","i18n":{"en":{"stem":"Which two prebuilt agent templates does Agentforce offer? (Choose 2)","options":["Metadata backup agent","Service Agent","Inactive user deletion agent","Sales Development","Sharing rule admin agent"],"explanation":"Templates include Service Agent, Sales Development Representative, Sales Coach and Agentforce for employees."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace el agente de desarrollo de ventas (SDR)?","options":["Contacta y nutre leads de forma autónoma y agenda reuniones","Asigna territorios","Cierra oportunidades y genera contratos firmados sin intervención","Calcula comisiones de los comerciales"],"correct":[0],"explanation":"El agente SDR responde a leads, resuelve dudas y reserva reuniones.","i18n":{"en":{"stem":"What does the Sales Development (SDR) agent do?","options":["Autonomously engages and nurtures leads and books meetings","Assigns territories","Closes opportunities and generates signed contracts unaided","Calculates rep commissions"],"explanation":"The SDR agent replies to leads, answers questions and books meetings."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace el agente Sales Coach?","options":["Envía correos masivos de marketing a todos los contactos","Asigna leads a comerciales según su rendimiento","Genera informes de previsión","Permite a los comerciales practicar conversaciones con juego de roles"],"correct":[3],"explanation":"Sales Coach simula al comprador y da feedback.","i18n":{"en":{"stem":"What does the Sales Coach agent do?","options":["Sends mass marketing emails to all contacts","Assigns leads by rep performance","Generates forecast reports","Lets reps practice conversations via role-play"],"explanation":"Sales Coach simulates the buyer and gives feedback."}}},{"domain":"D1","source":"bank","stem":"¿En qué canales puede desplegarse un agente de servicio? (Elige 2)","options":["El registro de depuración de Apex","Las plantillas de correo Classic","El Setup de la organización para administradores","Mensajería para web y apps (Messaging for In-App and Web)","Sitios de Experience Cloud"],"correct":[3,4],"explanation":"También WhatsApp, SMS y otros canales vía Messaging y Omni-Channel.","i18n":{"en":{"stem":"Which channels can a service agent be deployed to? (Choose 2)","options":["The Apex debug log","Classic email templates","The org's Setup for admins","Messaging for In-App and Web","Experience Cloud sites"],"explanation":"Also WhatsApp, SMS and others via Messaging and Omni-Channel."}}},{"domain":"D1","source":"bank","stem":"¿Qué se necesita para enrutar conversaciones de mensajería al agente de servicio?","options":["Una cola de casos sin miembros","Una regla de escalado","Una regla de asignación de leads con el agente como propietario","Un flujo de Omni-Channel que dirija la sesión al agente"],"correct":[3],"explanation":"El canal usa un Omni-Channel flow con la acción Route Work hacia el agente.","i18n":{"en":{"stem":"What's needed to route messaging conversations to the service agent?","options":["A memberless case queue","An escalation rule","A lead assignment rule with the agent as owner","An Omni-Channel flow routing the session to the agent"],"explanation":"The channel uses an Omni-Channel flow with Route Work to the agent."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Agentforce (asistente para empleados, antes Einstein Copilot)?","options":["Un tipo de sandbox con datos de IA","Un servicio de traducción de la interfaz de Salesforce a varios idiomas","Un objeto de auditoría","Un agente conversacional en Lightning que ayuda a usuarios internos"],"correct":[3],"explanation":"El asistente de empleados trabaja en el contexto del registro y del usuario.","i18n":{"en":{"stem":"What is the Agentforce employee assistant (formerly Einstein Copilot)?","options":["A sandbox type with AI data","A service translating the Salesforce UI into several languages","An audit object","A conversational agent in Lightning helping internal users"],"explanation":"The employee assistant works in the record and user context."}}},{"domain":"D1","source":"bank","stem":"¿Qué acciones estándar incluye habitualmente el asistente de empleados? (Elige 2)","options":["Cambiar el OWD de los objetos","Consultar registros","Desactivar usuarios de la organización","Instalar paquetes de AppExchange","Resumir registro"],"correct":[1,4],"explanation":"Acciones estándar como Summarize Record, Query Records, Draft or Revise Email, Identify Record.","i18n":{"en":{"stem":"Which standard actions does the employee assistant usually include? (Choose 2)","options":["Change object OWDs","Query Records","Deactivate org users","Install AppExchange packages","Summarize Record"],"explanation":"Standard actions like Summarize Record, Query Records, Draft or Revise Email, Identify Record."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica una buena descripción de acción?","options":["El nombre del desarrollador que la creó y la fecha de creación","Los permisos de objeto que necesita","Qué hace, cuándo usarla y qué devuelve","El canal en el que se mostrará"],"correct":[2],"explanation":"El motor se basa en la descripción para elegir la acción adecuada.","i18n":{"en":{"stem":"What does a good action description state?","options":["The developer's name and creation date","The object permissions it needs","What it does, when to use it and what it returns","The channel where it will display"],"explanation":"The engine relies on the description to choose the right action."}}},{"domain":"D1","source":"bank","stem":"Un agente usa una acción de cancelar pedido cuando el cliente solo pregunta por el estado. ¿Qué se corrige?","options":["La zona horaria del usuario del agente","Las instrucciones y descripciones de ambas acciones para diferenciarlas","El tipo de dato de la variable de salida de la acción de estado","El número de temas del agente, reduciéndolo a uno"],"correct":[1],"explanation":"Descripciones claras y distintas evitan que el motor confunda acciones.","i18n":{"en":{"stem":"An agent uses a cancel-order action when the customer only asks for status. What's fixed?","options":["The agent user's time zone","Both actions' instructions and descriptions to tell them apart","The data type of the status action's output variable","The agent's topic count, cutting it to one"],"explanation":"Clear, distinct descriptions keep the engine from confusing actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce sobre el número de acciones por tema?","options":["Usar solo una acción por agente","Mantener un conjunto manejable y relacionado de acciones","Poner todas las acciones de la organización en cada tema por si acaso","No hay recomendaciones"],"correct":[1],"explanation":"Demasiadas acciones por tema dificultan la selección; se recomienda agrupar por trabajo.","i18n":{"en":{"stem":"What does Salesforce recommend about actions per topic?","options":["Use only one action per agent","Keep a manageable, related set of actions","Put every org action in each topic just in case","No recommendation"],"explanation":"Too many actions per topic hinder selection; group by job."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre cuando un usuario pide algo que encaja con dos temas?","options":["El motor elige el tema más adecuado según las descripciones","El agente se bloquea","Se escala siempre a un humano","El agente ejecuta todas las acciones de ambos temas a la vez"],"correct":[0],"explanation":"Si hay ambigüedad, descripciones solapadas generan errores; conviene separar bien los temas.","i18n":{"en":{"stem":"What happens when a user asks something fitting two topics?","options":["The engine picks the best topic from the descriptions","The agent freezes","It always escalates to a human","The agent runs every action of both topics at once"],"explanation":"Ambiguity from overlapping descriptions causes errors; separate topics clearly."}}},{"domain":"D1","source":"bank","stem":"¿Qué herramienta muestra, tras desplegar el agente, qué temas se usan más y dónde falla?","options":["Schema Builder","El historial de inicios de sesión del usuario del agente","Data Loader con exportación de casos","Analíticas de Agentforce y análisis de frases (utterance analysis)"],"correct":[3],"explanation":"Las analíticas muestran uso, resolución, escalados y temas no cubiertos.","i18n":{"en":{"stem":"Which tool shows, after deploying the agent, which topics are used most and where it fails?","options":["Schema Builder","The agent user's login history","Data Loader exporting cases","Agentforce analytics and utterance analysis"],"explanation":"Analytics show usage, resolution, escalations and uncovered topics."}}},{"domain":"D1","source":"bank","stem":"¿Qué es el tiempo de ejecución del agente (agent runtime) en relación con los límites?","options":["El agente tiene tiempo ilimitado por acción","El agente ignora los límites de gobernador por ser IA","Ninguna relación","Las acciones respetan límites de plataforma como los de gobernador"],"correct":[3],"explanation":"Las acciones Apex y flujos siguen sujetos a límites y tiempos de espera.","i18n":{"en":{"stem":"How does agent runtime relate to limits?","options":["The agent has unlimited time per action","The agent ignores governor limits because it's AI","No relation","Actions respect platform limits such as governor limits"],"explanation":"Apex and flow actions remain subject to limits and timeouts."}}},{"domain":"D1","source":"bank","stem":"Un flujo de acción debe devolver una lista de pedidos al agente. ¿Cómo se define la salida?","options":["Una pantalla con una tabla de datos para el cliente","Variable de colección disponible para salida","Un campo de texto largo en la cuenta","Un correo con los pedidos adjuntos"],"correct":[1],"explanation":"Las colecciones de salida pueden devolver varios registros.","i18n":{"en":{"stem":"An action flow must return a list of orders to the agent. How is the output defined?","options":["A screen with a data table for the customer","A collection variable available for output","A long text field on the account","An email with the orders attached"],"explanation":"Output collections can return multiple records."}}},{"domain":"D1","source":"bank","stem":"¿Qué se recomienda para que un agente verifique la identidad de un cliente antes de dar datos de su cuenta?","options":["Mostrar los datos y pedir confirmación después","Una acción de verificación y guardar el resultado en una variable","No hace falta verificar","Pedir al modelo que confíe en el nombre que dé el cliente"],"correct":[1],"explanation":"La verificación (p. ej. código por email) con variable y filtros protege los temas sensibles.","i18n":{"en":{"stem":"What's recommended so an agent verifies a customer's identity before giving account data?","options":["Showing data then asking for confirmation","A verification action storing the result in a variable","No verification needed","Asking the model to trust the name the customer gives"],"explanation":"Verification (e.g. email code) with a variable and filters protects sensitive topics."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos ayudan a que un agente no revele datos de otros clientes? (Elige 2)","options":["Permisos mínimos del usuario del agente","Desactivar la capa de confianza","Acciones que filtren por el cliente verificado","Dar View All Data al usuario del agente","Instrucciones largas sin controles de datos ni permisos"],"correct":[0,2],"explanation":"La seguridad se aplica con permisos y lógica de acciones, no solo con instrucciones.","i18n":{"en":{"stem":"Which two elements help keep an agent from revealing other customers' data? (Choose 2)","options":["Least-privilege agent user permissions","Disabling the trust layer","Actions filtering by the verified customer","Giving the agent user View All Data","Long instructions with no data or permission controls"],"explanation":"Security is enforced via permissions and action logic, not just instructions."}}},{"domain":"D1","source":"bank","stem":"¿Qué es la Einstein Trust Layer en el contexto de los agentes?","options":["Un conjunto de controles de seguridad entre los datos y el LLM","Un canal de mensajería","Un tipo de tema estándar","Un modelo de lenguaje propio entrenado con los datos del cliente"],"correct":[0],"explanation":"Incluye anclaje seguro, enmascaramiento, zero data retention, detección de toxicidad y auditoría.","i18n":{"en":{"stem":"What is the Einstein Trust Layer in the agent context?","options":["A set of security controls between data and the LLM","A messaging channel","A standard topic type","A proprietary LLM trained on customer data"],"explanation":"It includes secure grounding, masking, zero data retention, toxicity detection and audit."}}},{"domain":"D1","source":"bank","stem":"¿Qué garantiza la retención cero de datos (zero data retention) con los proveedores de LLM?","options":["Que el proveedor no guarda ni entrena con los prompts y respuestas","Que Salesforce borra todos los registros tras cada conversación","Que el agente no recuerda nada dentro de la misma sesión","Que no se registra auditoría"],"correct":[0],"explanation":"Los acuerdos con proveedores impiden retener o entrenar con los datos.","i18n":{"en":{"stem":"What does zero data retention with LLM providers guarantee?","options":["The provider doesn't store or train on prompts and responses","Salesforce deletes all records after each chat","The agent remembers nothing within the same session","No audit is logged"],"explanation":"Provider agreements prevent retaining or training on the data."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente responde de forma autónoma a eventos (por ejemplo, un nuevo lead) sin que nadie inicie un chat?","options":["Un agente autónomo desencadenado por un flujo o evento","Un tema estándar de escalado","Una plantilla de prompt de campo","Un agente de empleados que espera a que el usuario escriba"],"correct":[0],"explanation":"Los agentes pueden invocarse desde flujos, Apex o la Agent API sin interfaz de chat.","i18n":{"en":{"stem":"Which agent type responds autonomously to events (e.g. a new lead) without anyone starting a chat?","options":["An autonomous agent triggered by a flow or event","A standard escalation topic","A field prompt template","An employee agent waiting for the user to type"],"explanation":"Agents can be invoked from flows, Apex or the Agent API without a chat UI."}}},{"domain":"D1","source":"bank","stem":"¿Qué permite la acción de flujo para invocar un agente (AI agent action) dentro de Flow?","options":["Convertir un flujo en un tema estándar","Activar el agente en producción","Borrar conversaciones","Llamar a un agente desde un flujo y usar su respuesta"],"correct":[3],"explanation":"Flow puede invocar agentes para procesos autónomos.","i18n":{"en":{"stem":"What does the flow action to invoke an agent allow?","options":["Turning a flow into a standard topic","Activating the agent in production","Deleting conversations","Calling an agent from a flow and using its response"],"explanation":"Flow can invoke agents for autonomous processes."}}},{"domain":"D1","source":"bank","stem":"Un agente tiene que saludar al cliente por su nombre si está autenticado en el sitio. ¿De dónde lo obtiene?","options":["De un campo del usuario del agente","De las variables de contexto de la sesión","Preguntándolo siempre al cliente aunque ya se conozca","De Setup Audit Trail"],"correct":[1],"explanation":"Las context variables pueden traer el contacto o usuario autenticado.","i18n":{"en":{"stem":"An agent must greet the customer by name if authenticated on the site. Where does it get it?","options":["From a field on the agent user","From session context variables","By always asking even if already known","From Setup Audit Trail"],"explanation":"Context variables can carry the authenticated contact or user."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos permisos o configuraciones son necesarios para crear agentes? (Elige 2)","options":["Activar Einstein generativo y Agentforce en Setup","Permisos de gestión de agentes para el administrador","Desactivar la autenticación multifactor de la organización","Desactivar los flujos activos","Cambiar todos los OWD a públicos"],"correct":[0,1],"explanation":"Hay que habilitar Einstein/Agentforce y asignar permisos de gestión (p. ej. Manage AI Agents).","i18n":{"en":{"stem":"Which two settings or permissions are required to create agents? (Choose 2)","options":["Enable generative Einstein and Agentforce in Setup","Agent management permissions for the admin","Disable org MFA","Deactivate active flows","Change all OWDs to public"],"explanation":"Enable Einstein/Agentforce and assign management permissions (e.g. Manage AI Agents)."}}},{"domain":"D1","source":"bank","stem":"¿Qué pasa con la memoria de la conversación del agente dentro de una sesión?","options":["El agente guarda la conversación como caso automáticamente","El agente usa el historial reciente de la conversación como contexto","El agente comparte el historial con otros clientes","El agente olvida cada mensaje anterior en cuanto responde"],"correct":[1],"explanation":"El motor considera mensajes previos y variables de la sesión.","i18n":{"en":{"stem":"What about the agent's conversation memory within a session?","options":["The agent automatically saves the chat as a case","The agent uses recent conversation history as context","The agent shares history with other customers","The agent forgets each prior message as soon as it replies"],"explanation":"The engine considers prior messages and session variables."}}},{"domain":"D1","source":"bank","stem":"¿Qué acción estándar crea o identifica registros a partir de la conversación en el asistente de empleados?","options":["Identificar registro por nombre (Identify Record by Name)","Exportar registros a CSV","Convertir lead en oportunidad sin confirmar","Cambiar el propietario de todos los registros"],"correct":[0],"explanation":"Identify Record by Name busca el registro al que se refiere el usuario.","i18n":{"en":{"stem":"Which standard action identifies records from the conversation in the employee assistant?","options":["Identify Record by Name","Export records to CSV","Convert lead to opportunity without confirming","Change the owner of all records"],"explanation":"Identify Record by Name finds the record the user refers to."}}},{"domain":"D1","source":"bank","stem":"¿Qué factor reduce la latencia de las respuestas de un agente?","options":["Acciones eficientes y un número razonable de temas y acciones","Añadir más temas con descripciones similares","Desactivar el almacenamiento en caché del navegador","Instrucciones muy largas en cada tema"],"correct":[0],"explanation":"Menos ambigüedad y acciones rápidas mejoran el tiempo de respuesta.","i18n":{"en":{"stem":"Which factor reduces an agent's response latency?","options":["Efficient actions and a reasonable number of topics and actions","Adding more topics with similar descriptions","Disabling browser caching","Very long instructions per topic"],"explanation":"Less ambiguity and fast actions improve response time."}}},{"domain":"D1","source":"bank","stem":"¿Qué conviene poner en las instrucciones de un tema y qué no?","options":["Toda la lógica de negocio crítica, en lugar de usar acciones o filtros","Credenciales de las APIs que usan las acciones","Solo el nombre del tema repetido varias veces","Comportamiento y criterios; no lógica que deba ser exacta"],"correct":[3],"explanation":"Lo crítico y determinista va en acciones, filtros o Agent Script; las instrucciones guían.","i18n":{"en":{"stem":"What belongs in topic instructions and what doesn't?","options":["All critical business logic, instead of actions or filters","Credentials for the actions' APIs","Only the topic name repeated several times","Behavior and criteria; not logic that must be exact"],"explanation":"Critical, deterministic logic goes in actions, filters or Agent Script; instructions guide."}}},{"domain":"D1","source":"bank","stem":"¿Cuál es un buen ejemplo de instrucción de tema?","options":["\"Nunca uses ninguna acción en ningún caso\"","\"Si el pedido tiene más de 30 días, explica que no admite devolución\"","\"Sé muy bueno y responde siempre todo lo que te pregunten sobre cualquier cosa\"","\"Responde en mayúsculas\""],"correct":[1],"explanation":"Instrucciones concretas y accionables funcionan mejor que generalidades.","i18n":{"en":{"stem":"Which is a good topic instruction example?","options":["\"Never use any action in any case\"","\"If the order is over 30 days old, explain it can't be returned\"","\"Be very good and always answer anything anyone asks you about anything\"","\"Reply in capitals\""],"explanation":"Concrete, actionable instructions work better than generalities."}}},{"domain":"D1","source":"bank","stem":"¿Qué se recomienda al redactar las instrucciones para evitar conflictos?","options":["Escribir en varios idiomas a la vez","Evitar instrucciones contradictorias entre temas y acciones","Incluir excepciones que contradigan la regla principal sin explicarlas","Repetir la misma instrucción con palabras distintas en cada tema"],"correct":[1],"explanation":"Instrucciones coherentes evitan comportamientos impredecibles.","i18n":{"en":{"stem":"What's recommended when writing instructions to avoid conflicts?","options":["Write in several languages at once","Avoid contradictory instructions across topics and actions","Include unexplained exceptions contradicting the main rule","Repeat the same instruction in different words per topic"],"explanation":"Consistent instructions avoid unpredictable behavior."}}},{"domain":"D1","source":"bank","stem":"¿Qué información del agente se define a nivel global y afecta a todos los temas?","options":["Las entradas específicas de cada acción de flujo","El tipo de dato de cada filtro","La descripción, el rol y el tono del agente","Las variables de salida de las plantillas de prompt"],"correct":[2],"explanation":"El agente tiene descripción, rol, empresa y configuración de lenguaje/tono.","i18n":{"en":{"stem":"Which agent-level information is defined globally and affects all topics?","options":["Each flow action's specific inputs and their data types","Each filter's data type","The agent's description, role and tone","Prompt template output variables"],"explanation":"The agent has description, role, company and language/tone settings."}}},{"domain":"D1","source":"bank","stem":"¿Qué ajuste de idioma admite un agente?","options":["El idioma lo fija el perfil del administrador","Solo inglés, sin posibilidad de cambiarlo en ninguna edición","Idioma principal y, según configuración, idiomas adicionales","El idioma de cada cliente se adivina sin configurar nada"],"correct":[2],"explanation":"Los agentes permiten configurar idioma por defecto y adicionales.","i18n":{"en":{"stem":"Which language setting does an agent support?","options":["The admin profile sets the language","English only, with no way to change it in any edition","A primary language and, if configured, additional languages","Each customer's language is guessed with no setup"],"explanation":"Agents let you set a default and additional languages."}}},{"domain":"D1","source":"bank","stem":"¿Qué limitación tienen las acciones de un agente de servicio que llaman a Apex?","options":["Que Apex nunca puede usarse en agentes de servicio externos","El usuario del agente necesita acceso a la clase Apex","Ninguna","Que la clase debe ser global y sin pruebas"],"correct":[1],"explanation":"El acceso a clases Apex se da con permission sets al agent user.","i18n":{"en":{"stem":"What limitation applies to service agent actions calling Apex?","options":["Apex can never be used in external service agents","The agent user needs access to the Apex class","None","The class must be global with no tests"],"explanation":"Apex class access is granted to the agent user via permission sets."}}},{"domain":"D1","source":"bank","stem":"¿Qué anotación necesita un método Apex para usarse como acción de agente?","options":["@InvocableMethod","@future","@TestVisible","@AuraEnabled únicamente, sin otras anotaciones"],"correct":[0],"explanation":"Las acciones Apex se basan en métodos invocables (con @InvocableVariable para parámetros).","i18n":{"en":{"stem":"Which annotation does an Apex method need to be used as an agent action?","options":["@InvocableMethod","@future","@TestVisible","@AuraEnabled only, no other annotation"],"explanation":"Apex actions are based on invocable methods (with @InvocableVariable for parameters)."}}},{"domain":"D1","source":"bank","stem":"¿Qué permite usar una plantilla de prompt como acción de agente?","options":["Ejecutar actualizaciones de registros sin comprobar permisos","Crear temas automáticamente","Cambiar el modelo del motor de razonamiento","Generar texto con datos anclados dentro de la conversación"],"correct":[3],"explanation":"Las prompt templates (Flex) pueden ser acciones que generan respuestas ancladas.","i18n":{"en":{"stem":"What does using a prompt template as an agent action allow?","options":["Running record updates without checking any permissions","Creating topics automatically","Changing the reasoning engine's model","Generating grounded text within the conversation"],"explanation":"Prompt templates (Flex) can be actions generating grounded responses."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos fuentes externas puede llamar un agente mediante acciones de API? (Elige 2)","options":["Contraseñas de usuarios","Correos personales de los clientes","Hojas de cálculo locales del equipo del administrador","APIs registradas con External Services","APIs expuestas con MuleSoft"],"correct":[3,4],"explanation":"MuleSoft y External Services (OpenAPI) exponen APIs como acciones.","i18n":{"en":{"stem":"Which two external sources can an agent call via API actions? (Choose 2)","options":["User passwords","Customers' personal email","Local spreadsheets on the admin's computer","APIs registered with External Services","APIs exposed with MuleSoft"],"explanation":"MuleSoft and External Services (OpenAPI) expose APIs as actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce sobre crear agentes con el asistente de creación?","options":["Crear todos los temas a mano sin usar plantillas","Activarlo en producción nada más generarlo","Evitar revisar los temas generados","Partir de una plantilla o descripción y luego refinar temas y acciones"],"correct":[3],"explanation":"La IA puede generar temas iniciales que hay que revisar y probar.","i18n":{"en":{"stem":"What does Salesforce recommend when creating agents with the creation assistant?","options":["Build every topic by hand without templates","Activate in production right after generating","Avoid reviewing generated topics","Start from a template or description, then refine topics and actions"],"explanation":"AI can draft initial topics that must be reviewed and tested."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica la sección de plan o razonamiento en la vista previa cuando una acción falla?","options":["El paso que falló y su entrada o error","Los usuarios conectados","El historial de versiones del agente","El coste en tokens de toda la conversación"],"correct":[0],"explanation":"Ayuda a depurar entradas incorrectas o permisos.","i18n":{"en":{"stem":"What does the plan/reasoning view show in preview when an action fails?","options":["The failing step and its input or error","Users online","The agent's version history","The token cost of the whole conversation"],"explanation":"It helps debug wrong inputs or permissions."}}},{"domain":"D1","source":"bank","stem":"Un agente pide al cliente datos que ya tiene en el contexto. ¿Qué se ajusta?","options":["Mapear las variables de contexto a las entradas de la acción","Añadir más temas con preguntas obligatorias para el cliente","Subir la temperatura","Borrar las instrucciones"],"correct":[0],"explanation":"Conectar variables a entradas evita preguntas innecesarias.","i18n":{"en":{"stem":"An agent asks the customer for data it already has in context. What's adjusted?","options":["Map context variables to action inputs","Add more topics with questions for the customer","Raise temperature","Delete instructions"],"explanation":"Linking variables to inputs avoids needless questions."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja tiene separar un proceso grande en varios temas?","options":["Que no hace falta probar","Que el agente ejecuta todos los temas a la vez más rápido","Mejor clasificación y menos acciones por tema","Que se evitan los permisos"],"correct":[2],"explanation":"Temas bien delimitados facilitan la elección correcta.","i18n":{"en":{"stem":"What's the benefit of splitting a large process into several topics?","options":["No testing needed","The agent runs all topics at once and finishes faster","Better classification and fewer actions per topic","Permissions are avoided"],"explanation":"Well-bounded topics make correct selection easier."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de acción permite mostrar al usuario un componente interactivo (por ejemplo, una tarjeta) en la conversación?","options":["Una acción con salida renderizada mediante un componente Lightning","Un diseño de página compacto","Una regla de validación con mensaje","Un informe enriquecido"],"correct":[0],"explanation":"Las salidas pueden usar componentes (Lightning types) para una presentación rica.","i18n":{"en":{"stem":"Which action type can show the user an interactive component (e.g. a card) in the conversation?","options":["An action whose output renders via a Lightning component","A compact page layout","A validation rule with a message","A rich report"],"explanation":"Outputs can use components (Lightning types) for rich presentation."}}},{"domain":"D1","source":"bank","stem":"Un agente de empleados debe actualizar el importe de una oportunidad. ¿Qué acción estándar lo permite con confirmación?","options":["Resumir registro, que también guarda cambios","Consultar registros","Actualizar registro (Update Record)","Borrar registro"],"correct":[2],"explanation":"Las acciones de actualización suelen pedir confirmación y respetan permisos del usuario.","i18n":{"en":{"stem":"An employee agent must update an opportunity's amount. Which standard action does it with confirmation?","options":["Summarize Record, which also saves changes","Query Records","Update Record","Delete Record"],"explanation":"Update actions usually ask for confirmation and honor user permissions."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre si el usuario del asistente de empleados no tiene permiso para editar el registro?","options":["Se crea un caso","El agente cambia el propietario","El agente lo edita igualmente con permisos de sistema","La acción falla por permisos"],"correct":[3],"explanation":"El asistente actúa con los permisos del usuario.","i18n":{"en":{"stem":"What happens if the employee assistant user lacks edit permission on the record?","options":["A case is created","The agent changes owner","The agent edits it anyway with system permissions","The action fails on permissions"],"explanation":"The assistant acts with the user's permissions."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos prácticas mejoran la calidad de un agente antes de activarlo? (Elige 2)","options":["Darle View All Data","Revisar casos límite y peticiones maliciosas","Quitar los temas estándar de seguridad","Probar con frases reales y variadas","Activarlo directamente para todos los clientes"],"correct":[1,3],"explanation":"Probar variedad, límites e intentos de manipulación.","i18n":{"en":{"stem":"Which two practices improve agent quality before activation? (Choose 2)","options":["Give it View All Data","Review edge cases and malicious requests","Remove standard safety topics","Test with real, varied utterances","Activate it directly for all customers at once"],"explanation":"Test variety, limits and manipulation attempts."}}},{"domain":"D1","source":"bank","stem":"¿Qué es la inyección de prompt en el contexto de un agente?","options":["Una acción de flujo","Insertar un registro de prompt en Data Cloud","Un tipo de tema","Un intento del usuario de cambiar las instrucciones del agente"],"correct":[3],"explanation":"Los usuarios pueden intentar que el agente ignore sus reglas; la Trust Layer y el diseño lo mitigan.","i18n":{"en":{"stem":"What is prompt injection in an agent context?","options":["A flow action","Inserting a prompt record into Data Cloud","A topic type","A user's attempt to override the agent's instructions"],"explanation":"Users may try to make the agent ignore its rules; the Trust Layer and design mitigate it."}}},{"domain":"D1","source":"bank","stem":"¿Qué mitiga mejor que un cliente obtenga datos de otro mediante inyección de prompt?","options":["Usar temperatura alta","Controles en las acciones y permisos, no solo instrucciones","Ocultar el nombre del agente","Pedir educadamente al modelo que no lo haga"],"correct":[1],"explanation":"La seguridad real reside en permisos, filtros y acciones que validan.","i18n":{"en":{"stem":"What best mitigates a customer getting another's data via prompt injection?","options":["High temperature","Controls in actions and permissions, not just instructions","Hiding the agent's name","Politely asking the model not to"],"explanation":"Real security lives in permissions, filters and validating actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué guarda la auditoría de IA de una conversación de agente?","options":["Nada","Prompts, respuestas y detalles de la Trust Layer","Las contraseñas de los clientes","Solo el número de mensajes intercambiados"],"correct":[1],"explanation":"Los datos de auditoría se almacenan en Data Cloud para revisión.","i18n":{"en":{"stem":"What does AI audit store for an agent conversation?","options":["Nothing","Prompts, responses and Trust Layer details","Customer passwords","Only the message count"],"explanation":"Audit data is stored in Data Cloud for review."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente se recomienda para que los comerciales consulten y actualicen CRM conversando en Slack o Lightning?","options":["Sales Coach","Agente de servicio con usuario invitado","Agente de empleados","Agente SDR autónomo"],"correct":[2],"explanation":"Los employee agents ayudan a usuarios internos en Lightning, Slack y móvil.","i18n":{"en":{"stem":"Which agent type suits reps querying and updating CRM via chat in Slack or Lightning?","options":["Sales Coach","Service agent with guest user","Employee agent","Autonomous SDR agent"],"explanation":"Employee agents help internal users in Lightning, Slack and mobile."}}},{"domain":"D1","source":"bank","stem":"¿Qué recurso aporta una salida estructurada más fiable de una acción de flujo al agente?","options":["Un texto libre muy largo con todos los datos juntos","Variables de salida con tipos claros","Un archivo adjunto","Un correo electrónico"],"correct":[1],"explanation":"Salidas tipadas facilitan al motor usar los datos.","i18n":{"en":{"stem":"What gives the agent more reliable structured output from a flow action?","options":["A very long free text with all data together","Clearly typed output variables","An attachment","An email"],"explanation":"Typed outputs make data easier for the engine to use."}}},{"domain":"D1","source":"bank","stem":"Un tema necesita ejecutar siempre la acción de verificación antes de cualquier otra. ¿Qué es lo más fiable?","options":["Escribir \"primero verifica\" en mayúsculas en la descripción","Ordenar las acciones alfabéticamente","Imponerlo con lógica determinista o filtros de acciones","Añadir la acción dos veces"],"correct":[2],"explanation":"El orden obligatorio se garantiza con lógica, no con la redacción.","i18n":{"en":{"stem":"A topic must always run verification before any other action. What's most reliable?","options":["Write \"verify first\" in capitals in the topic description","Sort actions alphabetically","Enforce it with deterministic logic or action filters","Add the action twice"],"explanation":"Mandatory order is guaranteed by logic, not wording."}}},{"domain":"D1","source":"bank","stem":"¿Qué es un agente en el sentido de la arquitectura de Agentforce frente a un chatbot tradicional?","options":["Solo responde preguntas frecuentes","Razona sobre la intención y elige acciones, en vez de seguir un árbol fijo","No puede ejecutar acciones","Sigue siempre un árbol de diálogo fijo definido a mano paso a paso"],"correct":[1],"explanation":"Los agentes combinan LLM, razonamiento y acciones; los bots clásicos usaban diálogos fijos.","i18n":{"en":{"stem":"What is an agent in Agentforce architecture versus a traditional chatbot?","options":["It only answers FAQs","It reasons about intent and picks actions instead of following a fixed tree","It can't execute actions","It always follows a fixed hand-built dialog tree"],"explanation":"Agents combine LLM, reasoning and actions; classic bots used fixed dialogs."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos riesgos hay que gestionar al dar a un agente acciones que escriben datos? (Elige 2)","options":["Que el canal de mensajería cambie de color","Abuso por usuarios malintencionados","Que el tema cambie de nombre","Cambios no deseados por mala interpretación","Que el agente se quede sin tokens de lectura"],"correct":[1,3],"explanation":"Confirmaciones, permisos mínimos y validaciones mitigan estos riesgos.","i18n":{"en":{"stem":"Which two risks must be managed when giving an agent data-writing actions? (Choose 2)","options":["The messaging channel changing color","Abuse by malicious users","The topic being renamed","Unwanted changes from misinterpretation","The agent running out of read tokens mid-session"],"explanation":"Confirmations, least privilege and validations mitigate these risks."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica la tasa de escalado alta de un agente de servicio?","options":["Que el agente funciona perfectamente","Que muchas conversaciones no se resuelven sin un humano","Que los clientes no usan el chat","Que hay demasiados agentes humanos"],"correct":[1],"explanation":"Analizar escalados ayuda a añadir temas, acciones o conocimiento.","i18n":{"en":{"stem":"What does a high escalation rate for a service agent indicate?","options":["The agent works perfectly","Many conversations aren't resolved without a human","Customers don't use chat","There are too many human agents"],"explanation":"Analyzing escalations helps add topics, actions or knowledge."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace el análisis de frases (utterance analysis) de Agentforce?","options":["Asigna temas a agentes humanos","Traduce las frases de los clientes a otros idiomas","Borra las conversaciones antiguas","Agrupa lo que preguntan los usuarios y detecta huecos"],"correct":[3],"explanation":"Muestra intenciones frecuentes, temas usados y peticiones no cubiertas.","i18n":{"en":{"stem":"What does Agentforce utterance analysis do?","options":["Assigns topics to human agents","Translates customer utterances","Deletes old conversations","Clusters what users ask and spots gaps"],"explanation":"It shows frequent intents, used topics and uncovered requests."}}},{"domain":"D1","source":"bank","stem":"¿Qué consideración de licencias o consumo tiene Agentforce?","options":["Se paga por número de temas creados","Es gratuito e ilimitado en todas las ediciones","El uso consume créditos o conversaciones según el modelo contratado","Se paga por número de perfiles"],"correct":[2],"explanation":"El consumo (Flex Credits, conversaciones) depende del contrato.","i18n":{"en":{"stem":"What licensing/consumption consideration does Agentforce have?","options":["It's billed per topic created","It's free and unlimited in all editions","Usage consumes credits or conversations per the contracted model","It's billed per profile"],"explanation":"Consumption (Flex Credits, conversations) depends on the contract."}}},{"domain":"D1","source":"bank","stem":"Un agente debe responder solo con información del catálogo de productos subido como PDF. ¿Qué configuración encaja?","options":["Crear un campo de texto largo en el producto","Un informe de productos","Copiar el PDF entero en las instrucciones del tema","Una Data Library con esos archivos y una acción de respuesta"],"correct":[3],"explanation":"ADL indexa archivos para recuperación (RAG).","i18n":{"en":{"stem":"An agent must answer only from the product catalog uploaded as PDFs. Which setup fits?","options":["A long text field on product","A product report","Pasting the whole PDF into the topic instructions","A Data Library with those files and an answer action"],"explanation":"ADL indexes files for retrieval (RAG)."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos influyen en qué acción elige el motor dentro de un tema? (Elige 2)","options":["El orden de creación del usuario del agente","La zona horaria del cliente","Instrucciones del tema","Instrucciones de la acción","El color de la acción en el constructor"],"correct":[2,3],"explanation":"Las instrucciones del tema y de las acciones guían la selección.","i18n":{"en":{"stem":"Which two elements influence which action the engine picks within a topic? (Choose 2)","options":["The agent user's creation order","The customer's time zone","Topic instructions","Action instructions","The action's color in the builder"],"explanation":"Topic and action instructions guide selection."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre si una acción necesaria no está asignada al tema elegido?","options":["Se crea automáticamente","El agente la busca en otros temas y la ejecuta igualmente","El agente se desactiva","El agente no puede usarla en ese tema"],"correct":[3],"explanation":"El motor solo usa acciones del tema activo (además de las globales disponibles).","i18n":{"en":{"stem":"What happens if a needed action isn't assigned to the chosen topic?","options":["It's created automatically","The agent finds it in other topics and runs it anyway","The agent is deactivated","The agent can't use it in that topic"],"explanation":"The engine only uses the active topic's actions (plus available global ones)."}}},{"domain":"D1","source":"bank","stem":"¿Qué patrón se recomienda para una acción que consulta datos sensibles del cliente?","options":["Aceptar el número de cliente que escriba el usuario sin comprobar","Guardar los datos en las instrucciones","Recibir el identificador verificado desde una variable, no del texto libre","Devolver todos los clientes y dejar que el modelo filtre"],"correct":[2],"explanation":"Evita que un usuario pida datos ajenos escribiendo otro identificador.","i18n":{"en":{"stem":"Which pattern is recommended for an action querying sensitive customer data?","options":["Accept whatever customer number the user types, without any check","Store the data in instructions","Take the verified ID from a variable, not free text","Return all customers and let the model filter"],"explanation":"It prevents a user requesting others' data by typing another ID."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de respuesta da un agente cuando la Trust Layer detecta contenido tóxico?","options":["Se borra la conversación entera","Se envía igualmente sin registro alguno","Se marca y puede bloquearse o registrarse en auditoría","Se cambia de idioma"],"correct":[2],"explanation":"La detección de toxicidad puntúa y registra contenido.","i18n":{"en":{"stem":"What happens when the Trust Layer detects toxic content?","options":["The whole chat is deleted","It's sent anyway with no logging","It's flagged and may be blocked or logged for audit","The language changes"],"explanation":"Toxicity detection scores and logs content."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace el enmascaramiento de datos de la Trust Layer?","options":["Cifra la base de datos de Salesforce","Borra la PII tras 30 días","Oculta campos en los diseños de página","Sustituye datos sensibles antes de enviarlos al LLM"],"correct":[3],"explanation":"El masking reemplaza PII por marcadores y la restaura en la respuesta.","i18n":{"en":{"stem":"What does Trust Layer data masking do?","options":["Encrypts the Salesforce database","Deletes PII after 30 days","Hides fields on page layouts","Replaces sensitive data before sending to the LLM"],"explanation":"Masking swaps PII for placeholders and restores it in the response."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos opciones de despliegue tiene un agente para clientes? (Elige 2)","options":["Plantillas de correo Classic","Informes programados","Chat embebido en la web corporativa","Canales de mensajería como WhatsApp o SMS","El Setup de la organización"],"correct":[2,3],"explanation":"Messaging for In-App and Web y otros canales de mensajería.","i18n":{"en":{"stem":"Which two deployment options does a customer agent have? (Choose 2)","options":["Classic email templates","Scheduled reports","Embedded chat on the corporate website","Messaging channels like WhatsApp or SMS","The org Setup"],"explanation":"Messaging for In-App and Web and other messaging channels."}}},{"domain":"D1","source":"bank","stem":"¿Qué consideración hay al usar un agente en un sitio de Experience Cloud con usuarios autenticados?","options":["No se pueden usar agentes en Experience Cloud","Los datos accesibles dependen del usuario del agente y del contexto","El agente ve todo lo que ve el administrador del sitio","El agente usa el perfil invitado siempre"],"correct":[1],"explanation":"Hay que diseñar acciones que filtren por el usuario autenticado.","i18n":{"en":{"stem":"What's a consideration using an agent on an Experience Cloud site with authenticated users?","options":["Agents can't be used in Experience Cloud","Accessible data depends on the agent user and context","The agent sees everything the site admin sees","The agent always uses the guest profile"],"explanation":"Design actions that filter by the authenticated user."}}},{"domain":"D1","source":"bank","stem":"Un agente tarda en responder porque una acción llama a un sistema lento. ¿Qué mejora?","options":["Cambiar la descripción del agente","Añadir más instrucciones a la acción","Duplicar la acción en otro tema","Optimizar o cachear la integración"],"correct":[3],"explanation":"El rendimiento de las acciones afecta directamente a la latencia.","i18n":{"en":{"stem":"An agent is slow because an action calls a slow system. What helps?","options":["Change the agent description","Add more instructions to the action","Duplicate the action in another topic","Optimize or cache the integration"],"explanation":"Action performance directly affects latency."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica la versión de un agente?","options":["El tipo de licencia","Un número que cuenta cuántos clientes lo han usado","El idioma del agente","Una configuración guardada de temas y acciones que se puede activar"],"correct":[3],"explanation":"Las versiones permiten iterar sin romper la activa.","i18n":{"en":{"stem":"What does an agent version represent?","options":["The license type","A count of how many customers used it","The agent's language","A saved configuration of topics and actions that can be activated"],"explanation":"Versions let you iterate without breaking the active one."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre si se intenta editar un agente activo?","options":["Hay que desactivarlo o crear una nueva versión","Se borra la versión activa","Se duplica automáticamente en otra organización","Se edita en caliente sin efectos en las conversaciones"],"correct":[0],"explanation":"Los agentes activos no se modifican directamente.","i18n":{"en":{"stem":"What happens when trying to edit an active agent?","options":["You must deactivate it or create a new version","The active version is deleted","It's auto-duplicated to another org","It's hot-edited with no effect on conversations"],"explanation":"Active agents aren't edited directly."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos indicadores muestra Agentforce Command Center o las analíticas para supervisar agentes? (Elige 2)","options":["Número de campos personalizados creados","Volumen de conversaciones","Número de reglas de validación","Tasa de resolución y escalado","Tamaño de la papelera"],"correct":[1,3],"explanation":"Se supervisan volumen, resolución, escalados, satisfacción y errores.","i18n":{"en":{"stem":"Which two indicators do Agentforce Command Center or analytics show to monitor agents? (Choose 2)","options":["Number of custom fields created","Conversation volume","Number of validation rules","Resolution and escalation rates","Recycle bin size"],"explanation":"Monitor volume, resolution, escalations, satisfaction and errors."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce para la primera implantación de un agente?","options":["Empezar con un caso de uso acotado y ampliarlo","No medir resultados","Evitar a los usuarios finales en las pruebas","Cubrir todos los procesos de la empresa desde el primer día"],"correct":[0],"explanation":"Empezar pequeño, medir y ampliar.","i18n":{"en":{"stem":"What does Salesforce recommend for a first agent rollout?","options":["Start with a narrow use case and expand","Don't measure results","Keep end users out of testing","Cover every company process from day one"],"explanation":"Start small, measure and expand."}}},{"domain":"D1","source":"bank","stem":"¿Qué patrón se usa para que un agente cree un caso cuando no puede resolver la consulta?","options":["Cerrar la conversación sin más","Pedir al cliente que escriba un correo a soporte","Una acción de flujo que crea el caso con el resumen","Crear un lead"],"correct":[2],"explanation":"Crear caso con contexto mejora el traspaso.","i18n":{"en":{"stem":"Which pattern lets an agent create a case when it can't resolve the query?","options":["Ending the chat","Asking the customer to email support","A flow action creating the case with a summary","Creating a lead"],"explanation":"Creating a case with context improves handoff."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de variable se usa para recordar en la sesión que el cliente ya fue verificado?","options":["Constante de flujo","Variable personalizada del agente","Valor de lista de selección global","Campo personalizado del objeto usuario del agente"],"correct":[1],"explanation":"Las custom variables almacenan estado de la conversación.","i18n":{"en":{"stem":"Which variable type remembers in the session that the customer was verified?","options":["Flow constant","Custom agent variable","Global picklist value","Custom field on the agent user object"],"explanation":"Custom variables store conversation state."}}},{"domain":"D1","source":"bank","stem":"¿Qué limita a qué acciones puede acceder el motor en cada momento de forma determinista?","options":["El número de versiones","El idioma del cliente","Filtros de temas y acciones","La longitud de las instrucciones del tema"],"correct":[2],"explanation":"Los filtros basados en variables restringen temas o acciones disponibles.","i18n":{"en":{"stem":"What deterministically limits which actions the engine can access at a time?","options":["Number of versions","Customer language","Topic and action filters","The length of topic instructions"],"explanation":"Variable-based filters restrict available topics or actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de acción estándar permite al asistente de empleados redactar correos?","options":["Crear campañas","Enviar correos masivos","Redactar o revisar correo (Draft or Revise Email)","Actualizar plantillas de correo"],"correct":[2],"explanation":"La acción genera borradores usando datos del registro.","i18n":{"en":{"stem":"Which standard action lets the employee assistant draft emails?","options":["Create campaigns","Send mass emails to contacts","Draft or Revise Email","Update email templates"],"explanation":"The action drafts using record data."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja tiene usar acciones estándar en lugar de crear acciones nuevas?","options":["No necesitan descripción ni instrucciones","Permiten saltarse los permisos del usuario final","Están probadas y mantenidas por Salesforce","Son más rápidas que cualquier flujo siempre"],"correct":[2],"explanation":"Las acciones estándar reducen trabajo y riesgo.","i18n":{"en":{"stem":"What's the benefit of standard actions over building new ones?","options":["They need no description or instructions","They bypass user permissions","They're tested and maintained by Salesforce","They're always faster than any flow"],"explanation":"Standard actions reduce effort and risk."}}},{"domain":"D1","source":"bank","stem":"Un usuario escribe \"cancélalo\" sin indicar qué pedido. ¿Qué comportamiento es deseable?","options":["Pedir aclaración antes de actuar","Escalar siempre","Cancelar el pedido más reciente del sistema de cualquier cliente","Cancelar todos los pedidos del cliente"],"correct":[0],"explanation":"Ante ambigüedad en acciones con efectos, el agente debe aclarar.","i18n":{"en":{"stem":"A user types \"cancel it\" without saying which order. What behavior is desirable?","options":["Ask for clarification before acting","Always escalate","Cancel the system's most recent order from any customer","Cancel all the customer's orders"],"explanation":"For ambiguous side-effect actions, the agent should clarify."}}},{"domain":"D1","source":"bank","stem":"¿Qué capacidad permite a un agente usar datos unificados del cliente de varias fuentes?","options":["Integración con Data Cloud","Una lista de selección global compartida","Un diseño de página compacto","El historial de inicios de sesión"],"correct":[0],"explanation":"Data Cloud aporta perfiles unificados y retrievers.","i18n":{"en":{"stem":"Which capability lets an agent use unified customer data from many sources?","options":["Data Cloud integration","A global picklist","A compact page layout","Login history"],"explanation":"Data Cloud provides unified profiles and retrievers."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos componen el prompt que el motor envía al modelo? (Elige 2)","options":["Los logs de depuración de Apex","Historial y contexto de la conversación","La contraseña del usuario del agente y su token","Las reglas de colaboración completas de la org","Instrucciones del agente y del tema"],"correct":[1,4],"explanation":"El motor construye el prompt con instrucciones, contexto, acciones disponibles y resultados.","i18n":{"en":{"stem":"Which two elements make up the prompt the engine sends to the model? (Choose 2)","options":["Apex debug logs","Conversation history and context","The agent user's password and token","The org's full sharing rules","Agent and topic instructions"],"explanation":"The engine builds the prompt from instructions, context, available actions and results."}}},{"domain":"D1","source":"bank","stem":"¿Qué consideración hay al mostrar enlaces o datos de registros en la respuesta del agente a clientes externos?","options":["Mostrar siempre el ID de Salesforce para que el cliente lo copie","No exponer IDs internos ni datos no autorizados","Mostrar los datos del propietario interno del caso","No hay ninguna"],"correct":[1],"explanation":"Las respuestas deben limitarse a lo que el cliente puede ver.","i18n":{"en":{"stem":"What's a consideration when showing links or record data in agent replies to external customers?","options":["Always show the Salesforce ID for the customer to copy","Don't expose internal IDs or unauthorized data","Show the internal case owner's data","None"],"explanation":"Replies should be limited to what the customer may see."}}},{"domain":"D1","source":"bank","stem":"¿Qué es el bucle de razonamiento del motor de Agentforce?","options":["Planificar, ejecutar acciones, evaluar resultados y repetir si hace falta","Recorrer todos los temas en orden","Ejecutar siempre una única acción y terminar","Preguntar al humano tras cada paso"],"correct":[0],"explanation":"El motor itera hasta poder responder.","i18n":{"en":{"stem":"What is the Agentforce engine's reasoning loop?","options":["Plan, run actions, evaluate results and repeat if needed","Walk through all topics in order","Always run a single action and stop","Ask the human after each step"],"explanation":"The engine iterates until it can respond."}}},{"domain":"D1","source":"bank","stem":"¿Qué conviene hacer si el agente debe usar datos de una tabla de precios que cambia cada día?","options":["Pedir al modelo que los recuerde","Consultarla con una acción en tiempo real","Crear un tema por precio","Copiar los precios en las instrucciones cada mañana"],"correct":[1],"explanation":"Los datos dinámicos se obtienen con acciones, no se incrustan en instrucciones.","i18n":{"en":{"stem":"What should be done if the agent must use a price table that changes daily?","options":["Ask the model to remember them","Query it with a real-time action","Create a topic per price","Paste prices into instructions every morning"],"explanation":"Dynamic data comes from actions, not embedded instructions."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente se usa para tareas de comercio, como buscar productos en una tienda online?","options":["El agente Sales Coach","El agente SDR","Un agente de servicio sin acciones","Un agente de comercio (Commerce)"],"correct":[3],"explanation":"Agentforce incluye agentes para comercio (shopper/merchant).","i18n":{"en":{"stem":"Which agent type handles commerce tasks like finding products in an online store?","options":["The Sales Coach agent","The SDR agent","A service agent with no actions","A Commerce agent"],"explanation":"Agentforce includes commerce agents (shopper/merchant)."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos acciones mejoran la transferencia de un agente a un humano? (Elige 2)","options":["Pasar un resumen de la conversación","Pedir al cliente que repita todo desde el principio","Cerrar la sesión de mensajería","Enrutar a la cola con las habilidades adecuadas","Borrar el historial"],"correct":[0,3],"explanation":"Contexto y enrutamiento correctos mejoran la experiencia.","i18n":{"en":{"stem":"Which two actions improve an agent-to-human handoff? (Choose 2)","options":["Passing a conversation summary","Asking the customer to repeat everything","Ending the messaging session","Routing to the queue with the right skills","Deleting history"],"explanation":"Context and correct routing improve the experience."}}},{"domain":"D1","source":"bank","stem":"¿Qué herramienta crea agentes, temas y acciones en una sola interfaz con vista previa?","options":["Flow Builder, que genera los temas a partir de cada elemento del flujo","Prompt Builder, que convierte cada plantilla en un tema del agente","Agentforce Builder","Lightning App Builder, desde la página de inicio de la app de servicio"],"correct":[2],"explanation":"Agentforce Builder es el entorno para construir y probar agentes.","i18n":{"en":{"stem":"Which tool builds agents, topics and actions in one interface with preview?","options":["Flow Builder, which generates topics from each flow element","Prompt Builder, which turns each template into an agent topic","Agentforce Builder","Lightning App Builder, from the service app's home page"],"explanation":"Agentforce Builder is the environment to build and test agents."}}},{"domain":"D1","source":"bank","stem":"¿Dónde se ve la lista de agentes de la organización y su estado activo o inactivo?","options":["En la papelera de reciclaje, filtrando por tipo de componente","En el historial de inicios de sesión de cada usuario del agente","En el Object Manager, dentro del objeto Usuario y sus registros relacionados","En la página Agentes de Setup"],"correct":[3],"explanation":"Setup > Agents lista los agentes, versiones y su estado.","i18n":{"en":{"stem":"Where do you see the org's agents and their active/inactive status?","options":["In the recycle bin, filtered by component type","In each agent user's login history","In Object Manager, within the User object and its related records","On the Agents page in Setup"],"explanation":"Setup > Agents lists agents, versions and status."}}},{"domain":"D1","source":"bank","stem":"¿Qué dato se pide al crear un agente de servicio y no uno de empleados?","options":["La carpeta de informes donde se guardarán las conversaciones","El usuario del agente","El idioma de la interfaz de Setup que usa el administrador al configurarlo","El tipo de registro predeterminado del administrador del sistema"],"correct":[1],"explanation":"Los agentes de servicio requieren asignar un agent user.","i18n":{"en":{"stem":"Which item is required when creating a service agent but not an employee agent?","options":["The report folder where conversations will be saved","The agent user","The Setup UI language the admin uses while configuring it","The system admin's default record type"],"explanation":"Service agents require assigning an agent user."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de licencia o usuario se usa normalmente como usuario de un agente de servicio?","options":["El usuario invitado del sitio con permiso Modify All Data","Un usuario de agente dedicado","El usuario del administrador principal, para evitar errores de permisos","Un usuario de Chatter Free con permisos ampliados de objetos CRM"],"correct":[1],"explanation":"Se crea un usuario específico (p. ej. licencia Einstein Agent) con permisos mínimos.","i18n":{"en":{"stem":"Which user is normally used as a service agent's user?","options":["The site guest user with Modify All Data","A dedicated agent user","The main admin's user, to avoid permission errors","A Chatter Free user with expanded CRM object permissions"],"explanation":"A specific user (e.g. Einstein Agent license) with least privilege is created."}}},{"domain":"D1","source":"bank","stem":"Un agente responde correctamente en la vista previa del administrador, pero en el canal no encuentra los artículos. ¿Causa probable?","options":["Que los artículos están escritos en un idioma no soportado por el modelo","Que el canal de mensajería no admite respuestas con texto largo","El usuario del agente no ve los artículos","Que la vista previa usa un modelo de lenguaje distinto del de producción"],"correct":[2],"explanation":"Visibilidad de Knowledge (canales, categorías, permisos) para el agent user.","i18n":{"en":{"stem":"An agent answers correctly in admin preview but can't find articles in the channel. Likely cause?","options":["The articles are in a language the model doesn't support","The messaging channel doesn't support long text replies","The agent user can't see the articles","Preview uses a different language model than production"],"explanation":"Knowledge visibility (channels, categories, permissions) for the agent user."}}},{"domain":"D1","source":"bank","stem":"¿Qué tres elementos componen una acción en Agentforce Builder? (Elige 2)","options":["Un diseño de página que muestra la acción en el registro del cliente","Una carpeta de informes que almacena los resultados de la acción","Una regla de colaboración que da acceso a los datos de la acción","Instrucciones de entradas y salidas","Referencia al recurso (flujo, Apex o prompt)"],"correct":[3,4],"explanation":"La acción referencia un recurso y describe entradas y salidas.","i18n":{"en":{"stem":"Which items make up an action in Agentforce Builder? (Choose 2)","options":["A page layout showing the action on the customer record","A report folder storing the action's results","A sharing rule granting access to the action's data","Input and output instructions","Reference to the resource (flow, Apex or prompt)"],"explanation":"The action references a resource and describes inputs and outputs."}}},{"domain":"D1","source":"bank","stem":"¿Qué conviene hacer con una acción que devuelve muchos campos que el agente no necesita?","options":["Duplicar la acción para cada campo y dejar que el agente las combine","Devolver solo lo necesario","Convertir los campos en un único texto largo sin estructura ni etiquetas","Devolver todos los campos del objeto para que el modelo elija libremente"],"correct":[1],"explanation":"Menos datos reducen ruido, latencia y riesgo de exposición.","i18n":{"en":{"stem":"What should be done with an action returning many fields the agent doesn't need?","options":["Duplicate the action per field and let the agent combine them","Return only what's needed","Merge the fields into one long unlabeled text","Return every object field so the model picks freely"],"explanation":"Less data reduces noise, latency and exposure risk."}}},{"domain":"D1","source":"bank","stem":"¿Qué mensaje da el agente si ninguna acción ni tema encaja con la petición?","options":["El último artículo de Knowledge publicado en la base de conocimiento","Un error técnico con el nombre del flujo y la clase Apex que fallaron","Ninguno: el agente cierra la conversación sin avisar al usuario","El del tema fuera de ámbito"],"correct":[3],"explanation":"El tema Off Topic define cómo responder a peticiones no soportadas.","i18n":{"en":{"stem":"What does the agent reply if no action or topic fits the request?","options":["The latest Knowledge article published in the base","A technical error naming the failing flow and Apex class","None: the agent ends the chat without telling the user","The off-topic topic's reply"],"explanation":"The Off Topic topic defines how to reply to unsupported requests."}}},{"domain":"D1","source":"bank","stem":"¿Qué valor tiene la descripción del agente (Agent description)?","options":["Orienta el comportamiento general del agente","Fija el número máximo de mensajes que puede enviar el cliente","Define los permisos de objeto del usuario del agente en producción","Solo aparece en la lista de Setup y no afecta a ninguna respuesta del agente"],"correct":[0],"explanation":"La descripción y el rol forman parte del contexto del motor.","i18n":{"en":{"stem":"What's the value of the agent description?","options":["It steers the agent's overall behavior","It caps how many messages the customer can send","It sets the agent user's object permissions in production","It only shows in Setup and affects no agent reply"],"explanation":"The description and role are part of the engine's context."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre si dos temas tienen descripciones de clasificación casi iguales?","options":["El agente puede elegir el tema equivocado","El motor fusiona automáticamente ambos temas en uno solo al activarse","El agente ejecuta las acciones de los dos temas en paralelo","El constructor impide guardar el agente hasta que se cambie el nombre"],"correct":[0],"explanation":"Descripciones solapadas confunden la clasificación.","i18n":{"en":{"stem":"What happens if two topics have nearly identical classification descriptions?","options":["The agent may pick the wrong topic","The engine automatically merges both topics on activation","The agent runs both topics' actions in parallel","The builder blocks saving until one is renamed"],"explanation":"Overlapping descriptions confuse classification."}}},{"domain":"D1","source":"bank","stem":"Un cliente escribe en francés y el agente solo está configurado en español. ¿Qué se revisa?","options":["El idioma predeterminado de la organización en la información de la empresa","La zona horaria del usuario del agente y su configuración regional","Los idiomas configurados del agente","El idioma de los artículos de Knowledge del sitio público"],"correct":[2],"explanation":"Los idiomas admitidos se configuran en el agente.","i18n":{"en":{"stem":"A customer writes in French and the agent is only set up in Spanish. What's checked?","options":["The org's default language in Company Information","The agent user's time zone and locale","The agent's configured languages","The language of the public site's Knowledge articles"],"explanation":"Supported languages are configured on the agent."}}},{"domain":"D1","source":"bank","stem":"¿Qué permite el tono del agente (por ejemplo formal o informal)?","options":["Cambiar las acciones disponibles según el tipo de cliente que escribe","Limitar la longitud máxima de cada mensaje a un número fijo de palabras","Definir qué temas se activan en horario comercial y cuáles fuera","Ajustar el estilo de las respuestas"],"correct":[3],"explanation":"El tono es un ajuste de estilo de conversación.","i18n":{"en":{"stem":"What does the agent's tone setting (e.g. formal or casual) allow?","options":["Changing available actions by customer type","Capping each message at a fixed word count","Defining which topics run in and out of business hours","Adjusting the reply style"],"explanation":"Tone is a conversation style setting."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja tiene una acción de flujo frente a pedir al modelo que calcule un descuento?","options":["El flujo evita que la conversación quede registrada en auditoría","El flujo no necesita permisos del usuario del agente para ejecutarse","El modelo calcula siempre mejor que un flujo porque entiende el contexto","Resultado exacto y repetible"],"correct":[3],"explanation":"Cálculos y reglas de negocio deben ser deterministas.","i18n":{"en":{"stem":"What's the benefit of a flow action over asking the model to calculate a discount?","options":["The flow keeps the conversation out of audit logs","The flow needs no agent user permissions to run","The model always calculates better since it understands context","Exact, repeatable result"],"explanation":"Calculations and business rules should be deterministic."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos casos de uso encajan bien con un agente de servicio? (Elige 2)","options":["Aprobar contratos de alto importe sin revisión humana ni controles","Modificar la configuración de seguridad de la organización","Cambiar los precios de toda la lista de precios estándar","Responder preguntas frecuentes con Knowledge","Consultar el estado de un pedido"],"correct":[3,4],"explanation":"Tareas repetitivas y de información son buenos candidatos.","i18n":{"en":{"stem":"Which two use cases fit a service agent well? (Choose 2)","options":["Approving high-value contracts with no human review or controls","Changing the org's security configuration","Changing prices across the whole standard price book","Answering FAQs with Knowledge","Checking order status"],"explanation":"Repetitive, informational tasks are good candidates."}}},{"domain":"D1","source":"bank","stem":"¿Qué limita que un agente de empleados actúe en Slack?","options":["Que Slack no admite agentes de Salesforce de ningún tipo","Que en Slack el agente usa permisos de administrador del espacio de trabajo","Configurar el despliegue del agente en Slack","Que hay que copiar los temas a mano en cada canal de Slack"],"correct":[2],"explanation":"Los agentes de empleados pueden desplegarse en Slack conectando la organización.","i18n":{"en":{"stem":"What's needed for an employee agent to act in Slack?","options":["Nothing: Slack supports no Salesforce agents of any kind","In Slack the agent uses workspace admin permissions","Configuring the agent's Slack deployment","Topics must be copied by hand into each Slack channel"],"explanation":"Employee agents can be deployed to Slack by connecting the org."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce para las salidas de acciones con datos personales?","options":["Enviarlos por correo además de mostrarlos para tener copia","Mostrar siempre todos los datos personales para que el cliente los verifique","Mostrar solo lo necesario","Guardarlos en las instrucciones del tema para reutilizarlos en otras sesiones"],"correct":[2],"explanation":"Minimización de datos y uso de la Trust Layer.","i18n":{"en":{"stem":"What does Salesforce recommend for action outputs with personal data?","options":["Email it as well as showing it, to keep a copy","Always show all personal data so the customer can verify it","Show only what's needed","Store it in topic instructions to reuse in other sessions"],"explanation":"Data minimization and Trust Layer use."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre con la conversación cuando un agente escala a un humano por Omni-Channel?","options":["El agente sigue respondiendo en paralelo con el humano","El humano recibe la sesión con su historial","La conversación empieza de cero y el cliente debe repetir todo lo dicho","El caso se cierra y se crea uno nuevo sin relación con el anterior"],"correct":[1],"explanation":"La sesión de mensajería se transfiere con su transcripción.","i18n":{"en":{"stem":"What happens to the conversation when an agent escalates to a human via Omni-Channel?","options":["The agent keeps replying in parallel with the human","The human gets the session with its history","The chat restarts and the customer repeats everything","The case closes and an unrelated new one is created"],"explanation":"The messaging session transfers with its transcript."}}},{"domain":"D1","source":"bank","stem":"¿Qué se configura para que el escalado funcione fuera del horario de atención humana?","options":["Una regla de validación que impida escribir al cliente fuera del horario","Un informe programado que avise al cliente al día siguiente","Un comportamiento alternativo, como crear un caso","Un segundo agente idéntico que sustituya a los humanos por la noche"],"correct":[2],"explanation":"El flujo de enrutamiento puede comprobar disponibilidad y ofrecer alternativas.","i18n":{"en":{"stem":"What's configured so escalation works outside human support hours?","options":["A validation rule blocking customers from writing after hours","A scheduled report notifying the customer next day","A fallback behavior, such as creating a case","A second identical agent replacing humans at night"],"explanation":"The routing flow can check availability and offer alternatives."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de acción estándar permite a un agente buscar información en la web o en fuentes externas?","options":["Consultar registros, que busca en internet si no encuentra datos internos","Identificar registro por nombre, que busca en directorios externos","No es estándar: se añade como acción personalizada","Resumir registro, que también consulta páginas web públicas de la empresa"],"correct":[2],"explanation":"Las fuentes externas se integran con acciones (API, MuleSoft) o RAG.","i18n":{"en":{"stem":"Which standard action lets an agent search the web or external sources?","options":["Query Records, which searches the internet if no internal data is found","Identify Record by Name, which searches external directories","It isn't standard: add it as a custom action","Summarize Record, which also queries public company web pages"],"explanation":"External sources are integrated via actions (API, MuleSoft) or RAG."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica el campo de instrucciones de una entrada de acción (input instructions)?","options":["El tipo de dato de Salesforce en el que se almacenará el valor en la base","Qué valor debe proporcionar el agente","Los perfiles que pueden ver el valor de la entrada","El valor por defecto que se usa siempre, ignorando lo que diga el cliente"],"correct":[1],"explanation":"Explica al motor cómo obtener o formatear el valor.","i18n":{"en":{"stem":"What do an action input's instructions specify?","options":["The Salesforce data type for storing the value","What value the agent must provide","The profiles that can see the input value","The default always used, ignoring what the customer says"],"explanation":"They explain to the engine how to get or format the value."}}},{"domain":"D1","source":"bank","stem":"Un agente pasa la fecha en formato incorrecto a un flujo. ¿Qué se ajusta?","options":["Las instrucciones de esa entrada","El idioma predeterminado de la organización y su configuración regional","La descripción de clasificación del tema que contiene la acción","El tipo de licencia del usuario del agente de servicio"],"correct":[0],"explanation":"Indicar formato esperado (p. ej. AAAA-MM-DD) en la entrada.","i18n":{"en":{"stem":"An agent passes a date in the wrong format to a flow. What's adjusted?","options":["That input's instructions","The org default language and locale","The classification description of the topic","The service agent user's license type"],"explanation":"State the expected format (e.g. YYYY-MM-DD) in the input."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre si una acción falla durante la conversación?","options":["El cliente ve siempre el detalle técnico completo del error","El agente reintenta la acción de forma indefinida hasta que funcione","El agente recibe el error y debe gestionarlo","La conversación se cierra automáticamente y se borra el historial"],"correct":[2],"explanation":"Conviene diseñar acciones con mensajes de error útiles y rutas de fallo.","i18n":{"en":{"stem":"What happens if an action fails during the conversation?","options":["The customer always sees the full technical error","The agent retries indefinitely until it works","The agent receives the error and must handle it","The chat auto-closes and history is deleted"],"explanation":"Design actions with useful error messages and fault paths."}}},{"domain":"D1","source":"bank","stem":"¿Qué conviene devolver desde un flujo de acción cuando no encuentra el pedido?","options":["Una lista con todos los pedidos de otros clientes por si alguno coincide","Un error genérico de sistema sin explicación para que el agente improvise","Nada: dejar las variables de salida vacías sin indicar el motivo","Un mensaje claro de no encontrado"],"correct":[3],"explanation":"Salidas explícitas ayudan al agente a responder bien.","i18n":{"en":{"stem":"What should an action flow return when it can't find the order?","options":["A list of every other customer's orders in case one matches","A generic system error so the agent improvises","Nothing: leave outputs empty with no reason","A clear not-found message"],"explanation":"Explicit outputs help the agent reply well."}}},{"domain":"D1","source":"bank","stem":"¿Qué medida reduce riesgos en acciones que cambian dinero, como reembolsos?","options":["Límites y aprobación humana","Quitar la confirmación para que la experiencia sea más rápida","Dar al usuario del agente permisos de administrador del sistema","Dejar que el modelo decida el importe del reembolso según la conversación"],"correct":[0],"explanation":"Umbrales y human-in-the-loop para acciones de alto impacto.","i18n":{"en":{"stem":"Which measure reduces risk in money-moving actions like refunds?","options":["Limits and human approval","Removing confirmation to speed up the experience","Giving the agent user system admin permissions","Letting the model choose the refund amount from the chat"],"explanation":"Thresholds and human-in-the-loop for high-impact actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué significa human-in-the-loop en Agentforce?","options":["El agente pregunta a un humano antes de responder cada mensaje","Un humano revisa o aprueba ciertos pasos","El administrador lee todas las conversaciones antes de enviarlas","Solo humanos pueden escribir en el canal donde está el agente"],"correct":[1],"explanation":"Se aplica en puntos críticos, no en cada mensaje.","i18n":{"en":{"stem":"What does human-in-the-loop mean in Agentforce?","options":["The agent asks a human before every message","A human reviews or approves certain steps","The admin reads every chat before it's sent","Only humans may write in the agent's channel"],"explanation":"It applies at critical points, not every message."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente usa Agentforce para atender a compradores en tiendas B2C?","options":["El agente Sales Coach configurado para hablar con clientes finales","El agente SDR con acceso a la lista de precios estándar","Agente de comercio para compradores","El asistente de empleados con permisos de usuario interno de ventas"],"correct":[2],"explanation":"Agentforce Commerce incluye agentes para compradores y comerciantes.","i18n":{"en":{"stem":"Which agent type serves shoppers in B2C stores?","options":["Sales Coach configured to talk to end customers","The SDR agent with standard price book access","Commerce shopper agent","The employee assistant with internal sales user permissions"],"explanation":"Agentforce Commerce includes shopper and merchant agents."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos fuentes alimentan las variables de contexto en un agente de empleados? (Elige 2)","options":["Las reglas de validación activas de la organización","El historial de compras de todos los clientes de la empresa","Las contraseñas almacenadas en el navegador del usuario","El usuario que conversa","El registro abierto en la página"],"correct":[3,4],"explanation":"El contexto incluye registro actual, usuario y página.","i18n":{"en":{"stem":"Which two sources feed context variables in an employee agent? (Choose 2)","options":["The org's active validation rules","Every customer's purchase history","Passwords stored in the user's browser","The user chatting","The record open on the page"],"explanation":"Context includes current record, user and page."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce sobre las respuestas de agentes en temas regulados (salud, finanzas)?","options":["Barreras estrictas y revisión humana","Desactivar la auditoría para proteger la privacidad del cliente","Usar la temperatura más alta disponible en los modelos","Dejar que el modelo responda libremente para mejorar la experiencia"],"correct":[0],"explanation":"Guardrails, anclaje y escalado reducen riesgo regulatorio.","i18n":{"en":{"stem":"What does Salesforce recommend for agent replies in regulated topics (health, finance)?","options":["Strict guardrails and human review","Disable audit to protect customer privacy","Use the highest available model temperature","Let the model answer freely to improve experience"],"explanation":"Guardrails, grounding and escalation reduce regulatory risk."}}},{"domain":"D1","source":"bank","stem":"¿Qué es Agentforce Voice?","options":["Un servicio que lee en voz alta los informes de la organización","Un canal para hablar con agentes por voz","Una herramienta para grabar notas de voz en Chatter","Un traductor de llamadas entre agentes humanos"],"correct":[1],"explanation":"Permite interacciones de voz con agentes (p. ej. en telefonía).","i18n":{"en":{"stem":"What is Agentforce Voice?","options":["A service reading org reports aloud","A channel for talking to agents by voice","A tool for recording voice notes in Chatter","A call translator between human agents"],"explanation":"It enables voice interactions with agents (e.g. telephony)."}}},{"domain":"D1","source":"bank","stem":"¿Qué dato se debe proteger en las transcripciones de conversaciones de agentes?","options":["La hora exacta de inicio de la sesión de mensajería","La versión del agente que estaba activa en ese momento","El nombre del tema que se usó durante la conversación con el cliente","La información personal del cliente"],"correct":[3],"explanation":"Las transcripciones contienen PII; hay que aplicar retención y acceso adecuados.","i18n":{"en":{"stem":"Which data must be protected in agent conversation transcripts?","options":["The messaging session's exact start time","The agent version active at the time","The topic name used during the conversation","The customer's personal information"],"explanation":"Transcripts hold PII; apply proper retention and access."}}},{"domain":"D1","source":"bank","stem":"Un agente de servicio debe ofrecer horarios disponibles para una cita. ¿Cómo se implementa?","options":["Pedir al cliente que proponga horas y aceptarlas todas sin comprobar","Crear un tema por cada día de la semana con sus horas","Una acción que consulta la disponibilidad","Escribir todos los horarios del año en las instrucciones del tema"],"correct":[2],"explanation":"La disponibilidad es dinámica y debe consultarse (p. ej. Scheduler).","i18n":{"en":{"stem":"A service agent must offer available appointment slots. How is it implemented?","options":["Asking the customer to propose times and accepting all unchecked","Creating a topic per weekday with its hours","An action that checks availability","Writing all the year's slots into topic instructions"],"explanation":"Availability is dynamic and must be queried (e.g. Scheduler)."}}},{"domain":"D1","source":"bank","stem":"¿Qué limitación tienen las instrucciones como mecanismo de seguridad?","options":["No garantizan el cumplimiento","Bloquean cualquier intento de inyección de prompt automáticamente","Se aplican antes que los permisos de objeto y los sustituyen","Garantizan al cien por cien que el modelo nunca se desviará de ellas"],"correct":[0],"explanation":"Los LLM pueden desviarse; los controles reales son permisos y lógica.","i18n":{"en":{"stem":"What's the limitation of instructions as a security mechanism?","options":["They don't guarantee compliance","They automatically block any prompt injection attempt","They apply before object permissions and replace them","They guarantee 100% the model never strays"],"explanation":"LLMs can stray; real controls are permissions and logic."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos acciones mejoran un tema que tiene baja tasa de resolución? (Elige 2)","options":["Aumentar la temperatura para respuestas más variadas","Borrar el tema y dejar que el agente use el tema fuera de ámbito","Añadir conocimiento o acciones que faltan","Desactivar las analíticas para no ver los datos","Revisar las conversaciones fallidas"],"correct":[2,4],"explanation":"Analizar fallos y cubrir huecos.","i18n":{"en":{"stem":"Which two actions improve a topic with low resolution rate? (Choose 2)","options":["Raise temperature for more varied replies","Delete the topic and let the agent use off-topic","Add missing knowledge or actions","Disable analytics so the data isn't seen","Review failed conversations"],"explanation":"Analyze failures and fill gaps."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica una respuesta del agente marcada con pulgar abajo por el usuario?","options":["Que el agente debe desactivarse inmediatamente en producción","Una señal para revisar esa interacción","Que el tema se borra automáticamente","Que el usuario debe ser bloqueado del canal de mensajería"],"correct":[1],"explanation":"El feedback alimenta la mejora continua.","i18n":{"en":{"stem":"What does a thumbs-down on an agent reply indicate?","options":["The agent must be deactivated immediately","A signal to review that interaction","The topic is auto-deleted","The user should be blocked from the channel"],"explanation":"Feedback feeds continuous improvement."}}},{"domain":"D1","source":"bank","stem":"¿Qué recurso de Salesforce permite comprar o instalar agentes y acciones de partners?","options":["La biblioteca de archivos de la organización","El objeto Activo del cliente","AgentExchange","El Setup Audit Trail con la lista de paquetes recomendados"],"correct":[2],"explanation":"AgentExchange es el mercado de agentes, temas, acciones y plantillas.","i18n":{"en":{"stem":"Which Salesforce resource lets you get partner agents and actions?","options":["The org file library","The customer Asset object","AgentExchange","Setup Audit Trail with the recommended package list"],"explanation":"AgentExchange is the marketplace for agents, topics, actions and templates."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja tiene que el agente muestre las fuentes usadas en la respuesta?","options":["Que evita tener que configurar la Trust Layer","Transparencia y verificación","Que permite al cliente editar los artículos","Que reduce el consumo de créditos a la mitad en cada respuesta"],"correct":[1],"explanation":"Las citas ayudan a confiar y comprobar la respuesta.","i18n":{"en":{"stem":"What's the benefit of the agent showing the sources used?","options":["It avoids configuring the Trust Layer","Transparency and verification","It lets the customer edit articles","It halves credit consumption per reply"],"explanation":"Citations build trust and allow checking."}}},{"domain":"D1","source":"bank","stem":"¿Qué elemento del agente determina qué hacer si el cliente insulta o usa lenguaje inapropiado?","options":["Instrucciones y detección de toxicidad","El tipo de registro de la cuenta del cliente","El horario comercial asignado a la cola de escalado","El diseño de página del objeto Caso para el perfil del cliente"],"correct":[0],"explanation":"Las barreras de contenido y la Trust Layer gestionan contenido inapropiado.","i18n":{"en":{"stem":"Which agent element decides what to do if the customer is abusive?","options":["Instructions and toxicity detection","The customer account's record type","The business hours on the escalation queue","The Case page layout for the customer profile"],"explanation":"Content guardrails and the Trust Layer handle inappropriate content."}}},{"domain":"D1","source":"bank","stem":"Un agente de empleados debe resumir los casos abiertos de una cuenta. ¿Qué acción es la más directa?","options":["Crear un informe nuevo cada vez que el usuario pregunte","Escalar a un supervisor para que haga el resumen","Resumir registro o una plantilla de prompt","Exportar los casos a CSV y pedir al usuario que los lea"],"correct":[2],"explanation":"Summarize Record o un prompt con datos relacionados.","i18n":{"en":{"stem":"An employee agent must summarize an account's open cases. Which action is most direct?","options":["Create a new report every time the user asks","Escalate to a supervisor to summarize","Summarize Record or a prompt template","Export cases to CSV and have the user read them"],"explanation":"Summarize Record or a prompt with related data."}}},{"domain":"D1","source":"bank","stem":"¿Qué permiso controla qué usuarios internos pueden usar el asistente de empleados?","options":["El rol del usuario dentro de la jerarquía de ventas de la organización","Un conjunto de permisos de Agentforce","La licencia de Chatter Free asignada a todos los empleados","El idioma configurado en el perfil del usuario"],"correct":[1],"explanation":"El acceso se asigna con permission sets específicos.","i18n":{"en":{"stem":"Which permission controls which internal users can use the employee assistant?","options":["The user's role within the org's sales hierarchy","An Agentforce permission set","A Chatter Free license assigned to all employees","The language set on the user's profile"],"explanation":"Access is granted via specific permission sets."}}},{"domain":"D1","source":"bank","stem":"¿Qué fase del ciclo de vida de un agente se centra en medir resultados y ajustar?","options":["Supervisión y mejora","Diseño inicial de temas en una pizarra antes de abrir el constructor","Elección del nombre del agente y de su avatar","Compra de licencias"],"correct":[0],"explanation":"Tras desplegar se supervisa con analíticas y se itera.","i18n":{"en":{"stem":"Which agent lifecycle phase focuses on measuring results and tuning?","options":["Monitoring and improvement","Initial topic design on a whiteboard before opening the builder","Choosing the agent's name and avatar","Buying licenses"],"explanation":"After deployment, monitor with analytics and iterate."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de acción estándar permite al agente dar respuestas basadas en documentos indexados en Data Cloud?","options":["Una regla de asignación de casos con el documento como criterio","Una plantilla de correo con los documentos adjuntos","Una actualización de registro sobre el objeto de documento","Una respuesta con recuperador (retriever)"],"correct":[3],"explanation":"Los retrievers consultan índices de búsqueda para RAG.","i18n":{"en":{"stem":"Which action type lets the agent answer from documents indexed in Data Cloud?","options":["A case assignment rule using the document as criteria","An email template with documents attached","A record update on the document object","An answer using a retriever"],"explanation":"Retrievers query search indexes for RAG."}}},{"domain":"D1","source":"bank","stem":"Un tema de agente necesita conocer si el cliente es VIP para ofrecer un trato distinto. ¿Cómo se hace?","options":["Escribir la lista de clientes VIP en las instrucciones del tema","Crear un agente distinto para cada cliente VIP","Pedir al cliente que diga si es VIP y creerle siempre","Una acción o variable con ese dato"],"correct":[3],"explanation":"Los datos del cliente se obtienen por acciones o contexto, no del texto libre.","i18n":{"en":{"stem":"An agent topic needs to know if the customer is VIP to treat them differently. How?","options":["Write the VIP list in the topic instructions","Create a separate agent per VIP customer","Ask the customer if they're VIP and always believe them","An action or variable with that data"],"explanation":"Customer data comes from actions or context, not free text."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos características distinguen la versión nueva de Agentforce Builder? (Elige 2)","options":["Combinación de razonamiento y lógica determinista","Edición con Agent Script","Imposibilidad de probar el agente antes de activarlo","Eliminación completa de los temas y las acciones","Uso obligatorio de Apex en todas las acciones"],"correct":[0,1],"explanation":"El nuevo builder introduce Agent Script y razonamiento híbrido.","i18n":{"en":{"stem":"Which two features distinguish the new Agentforce Builder? (Choose 2)","options":["Combining reasoning with deterministic logic","Editing with Agent Script","No way to test the agent before activation","Removing topics and actions entirely","Mandatory Apex for all actions"],"explanation":"The new builder brings Agent Script and hybrid reasoning."}}},{"domain":"D1","source":"bank","stem":"¿Qué indica que un agente necesita una acción nueva en lugar de mejores instrucciones?","options":["Responde con un tono demasiado formal para el público objetivo","Saluda dos veces al principio de la conversación","Usa frases largas","Le falta la capacidad de obtener o cambiar datos"],"correct":[3],"explanation":"Las instrucciones no sustituyen capacidades que requieren datos o acciones.","i18n":{"en":{"stem":"What indicates an agent needs a new action rather than better instructions?","options":["It replies too formally for the audience","It greets twice at the start of the chat","It uses long sentences","It lacks the ability to get or change data"],"explanation":"Instructions can't replace capabilities requiring data or actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué debe hacer un agente si el usuario pide algo permitido pero la acción requiere datos que faltan?","options":["Ejecutar la acción con campos vacíos y ver si funciona","Pedir los datos que faltan","Cerrar la conversación","Inventar valores razonables para completar la acción"],"correct":[1],"explanation":"El motor solicita entradas obligatorias que no tiene.","i18n":{"en":{"stem":"What should an agent do if the user asks for something allowed but the action lacks data?","options":["Run the action with empty fields and see if it works","Ask for the missing data","End the conversation","Invent reasonable values to complete the action"],"explanation":"The engine asks for missing required inputs."}}},{"domain":"D1","source":"bank","stem":"¿Qué se recomienda para nombrar temas y acciones?","options":["Códigos internos cortos sin significado para que nadie los entienda","Nombres claros que describan la tarea","El mismo nombre para todos los temas con un número al final","Nombres en varios idiomas mezclados"],"correct":[1],"explanation":"Los nombres claros ayudan al mantenimiento y al razonamiento.","i18n":{"en":{"stem":"What's recommended for naming topics and actions?","options":["Short meaningless internal codes nobody understands","Clear names describing the task","The same name for every topic with a number suffix","Mixed-language names"],"explanation":"Clear names help maintenance and reasoning."}}},{"domain":"D1","source":"bank","stem":"¿Qué ocurre con las conversaciones en curso al activar una nueva versión del agente?","options":["Todas las sesiones abiertas se cortan y se reinician con la versión nueva","Las nuevas sesiones usan la nueva versión","Las conversaciones antiguas se borran del historial","Nada: la versión antigua sigue activa para siempre"],"correct":[1],"explanation":"Solo una versión está activa; aplica a nuevas sesiones.","i18n":{"en":{"stem":"What happens to ongoing conversations when a new agent version is activated?","options":["All open sessions are cut and restarted on the new version","New sessions use the new version","Old conversations are deleted","Nothing: the old version stays active forever"],"explanation":"Only one version is active; it applies to new sessions."}}},{"domain":"D1","source":"bank","stem":"¿Qué indicador de negocio suele justificar un agente de servicio?","options":["Más informes creados por los supervisores cada mes","Más inicios de sesión diarios de los administradores","Aumento del número de campos personalizados del objeto Caso","Reducción del coste por contacto"],"correct":[3],"explanation":"Contención, coste por caso y satisfacción son métricas típicas.","i18n":{"en":{"stem":"Which business metric usually justifies a service agent?","options":["More reports created by supervisors monthly","More daily admin logins","More custom fields on the Case object","Lower cost per contact"],"explanation":"Containment, cost per case and satisfaction are typical metrics."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos hay que revisar si el agente no ejecuta nunca una acción concreta? (Elige 2)","options":["Que el usuario del agente tenga un rol en la jerarquía","Que su descripción indique cuándo usarla","Que la acción esté en el tema","Que la acción tenga un nombre corto de menos de diez letras","Que la organización tenga año fiscal personalizado activado"],"correct":[1,2],"explanation":"Asignación al tema y descripción clara.","i18n":{"en":{"stem":"Which two things are checked if the agent never runs a certain action? (Choose 2)","options":["That the agent user has a hierarchy role","That its description says when to use it","That the action is in the topic","That the action name is under ten letters","That the org has custom fiscal years enabled"],"explanation":"Topic assignment and a clear description."}}},{"domain":"D1","source":"bank","stem":"¿Qué aporta Agentforce para Sales en el registro de oportunidad?","options":["Resúmenes y siguientes pasos sugeridos","Cierre automático de oportunidades sin revisión del comercial","Cambio del propietario según el rendimiento del comercial","Creación de territorios nuevos"],"correct":[0],"explanation":"Ayuda a comerciales con resúmenes, correos y recomendaciones.","i18n":{"en":{"stem":"What does Agentforce for Sales add on the opportunity record?","options":["Summaries and suggested next steps","Auto-closing opportunities without rep review","Changing owner based on rep performance","Creating new territories"],"explanation":"It helps reps with summaries, emails and recommendations."}}},{"domain":"D1","source":"bank","stem":"¿Qué se recomienda antes de dar a un agente acceso a un nuevo objeto con datos sensibles?","options":["Dar acceso total para probar y recortarlo más adelante si hay quejas","Copiar los datos sensibles a un objeto público para que el agente los lea","Revisar permisos y necesidad real","Desactivar el enmascaramiento de la Trust Layer"],"correct":[2],"explanation":"Mínimo privilegio y revisión de necesidad.","i18n":{"en":{"stem":"What's recommended before giving an agent access to a new sensitive object?","options":["Grant full access to test and trim later if complaints","Copy sensitive data to a public object for the agent","Review permissions and real need","Disable Trust Layer masking"],"explanation":"Least privilege and need review."}}},{"domain":"D1","source":"bank","stem":"¿Qué limita el uso de un agente autónomo que se ejecuta por cada registro nuevo?","options":["Coste y límites de ejecución","Que no puede leer el registro que lo disparó en ningún caso","Que solo puede ejecutarse una vez al año por organización","Que requiere un humano para cada ejecución"],"correct":[0],"explanation":"Volumen alto implica consumo y límites a considerar.","i18n":{"en":{"stem":"What constrains an autonomous agent running for each new record?","options":["Cost and execution limits","It can never read the triggering record","It can run only once a year per org","It needs a human for each run"],"explanation":"High volume means consumption and limits to consider."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos herramientas permiten invocar un agente sin interfaz de chat? (Elige 2)","options":["Flow","Agent API","Reglas de validación de los objetos estándar","Diseños de página compactos","Plantillas de correo Classic"],"correct":[0,1],"explanation":"Flow, Apex y la Agent API permiten invocación programática.","i18n":{"en":{"stem":"Which two tools invoke an agent without a chat UI? (Choose 2)","options":["Flow","Agent API","Standard object validation rules","Compact page layouts","Classic email templates"],"explanation":"Flow, Apex and the Agent API allow programmatic invocation."}}},{"domain":"D1","source":"bank","stem":"¿Qué consideración hay al combinar un agente con procesos existentes de Omni-Channel?","options":["Ajustar colas y capacidad para los escalados","Desactivar Omni-Channel porque el agente lo sustituye por completo","Asignar al agente la misma capacidad que a todos los humanos juntos","No hay relación entre ambos"],"correct":[0],"explanation":"El agente comparte la infraestructura de enrutamiento con los humanos.","i18n":{"en":{"stem":"What's a consideration when combining an agent with existing Omni-Channel processes?","options":["Tune queues and capacity for escalations","Disable Omni-Channel since the agent fully replaces it","Give the agent the same capacity as all humans combined","They're unrelated"],"explanation":"The agent shares routing infrastructure with humans."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace la acción estándar Consultar registros (Query Records)?","options":["Borra los registros que coinciden con la consulta del usuario","Busca registros según la petición","Crea informes nuevos en la carpeta del usuario","Exporta todos los registros del objeto a un fichero"],"correct":[1],"explanation":"Traduce la petición en una consulta respetando permisos.","i18n":{"en":{"stem":"What does the standard Query Records action do?","options":["Deletes records matching the user's query","Finds records matching the request","Creates new reports in the user's folder","Exports every object record to a file"],"explanation":"It turns the request into a query honoring permissions."}}},{"domain":"D1","source":"bank","stem":"¿Qué recomienda Salesforce para gestionar el cambio con los empleados al introducir agentes?","options":["Sustituir a los equipos sin explicar el cambio","Activar el agente sin avisar para medir la reacción espontánea","Formación y comunicación del alcance","Prohibir el feedback de los usuarios"],"correct":[2],"explanation":"La adopción requiere formación y expectativas claras.","i18n":{"en":{"stem":"What does Salesforce recommend for change management when introducing agents?","options":["Replacing teams without explaining the change","Activating without notice to measure spontaneous reaction","Training and communicating scope","Banning user feedback"],"explanation":"Adoption needs training and clear expectations."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente atiende preguntas de empleados sobre RR. HH. o TI internamente?","options":["El agente SDR de ventas configurado para empleados","Un agente de empleados","Un agente de servicio público con usuario invitado","El agente de comercio para compradores"],"correct":[1],"explanation":"Los employee agents cubren casos internos como RR. HH. o TI.","i18n":{"en":{"stem":"Which agent type handles employee HR or IT questions internally?","options":["The sales SDR agent set up for employees","An employee agent","A public service agent with a guest user","The commerce shopper agent"],"explanation":"Employee agents cover internal cases like HR or IT."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de dato conviene usar en las variables de salida de acciones para listas de registros?","options":["Un número que indique cuántos registros hay sin detalles","Un archivo PDF generado","Un único campo de texto con valores separados por comas","Colecciones de registros"],"correct":[3],"explanation":"Las colecciones tipadas son más fiables para el agente.","i18n":{"en":{"stem":"Which data type should action outputs use for record lists?","options":["A number counting records with no details","A generated PDF","A single comma-separated text field","Record collections"],"explanation":"Typed collections are more reliable for the agent."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos elementos de seguridad de Agentforce actúan en tiempo de ejecución? (Elige 2)","options":["El diseño gráfico de la ventana de chat del sitio","Controles de la Trust Layer","Permisos del usuario que ejecuta","El orden alfabético de los temas","El nombre de la API del agente"],"correct":[1,2],"explanation":"Permisos y Trust Layer protegen cada interacción.","i18n":{"en":{"stem":"Which two Agentforce security elements act at runtime? (Choose 2)","options":["The site chat window's visual design","Trust Layer controls","Permissions of the running user","Alphabetical order of topics","The agent's API name"],"explanation":"Permissions and the Trust Layer protect each interaction."}}},{"domain":"D1","source":"bank","stem":"¿Qué hace el motor cuando la respuesta requiere encadenar varias acciones?","options":["Pide al administrador que las ejecute a mano","Las ejecuta en secuencia usando resultados previos","Ejecuta solo la primera y responde que no puede continuar","Las ejecuta todas en paralelo sin usar resultados"],"correct":[1],"explanation":"El razonamiento puede encadenar acciones.","i18n":{"en":{"stem":"What does the engine do when the answer requires chaining several actions?","options":["Asks the admin to run them by hand","Runs them in sequence using prior results","Runs only the first and says it can't continue","Runs them all in parallel ignoring results"],"explanation":"Reasoning can chain actions."}}},{"domain":"D1","source":"bank","stem":"¿Qué riesgo tiene dar a un agente demasiadas acciones disponibles a la vez?","options":["Elecciones erróneas y más latencia","Ninguno: más acciones siempre mejoran la precisión","Que el usuario del agente se desactiva automáticamente","Que la organización supera el límite de almacenamiento de archivos"],"correct":[0],"explanation":"Demasiadas opciones confunden al motor.","i18n":{"en":{"stem":"What's the risk of giving an agent too many actions at once?","options":["Wrong choices and more latency","None: more actions always improve accuracy","The agent user is auto-deactivated","The org exceeds file storage limits"],"explanation":"Too many options confuse the engine."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de agente coordina a otros agentes especializados para completar una tarea?","options":["Un tema estándar de escalado a humanos","Un flujo programado nocturno","Una plantilla de prompt de resumen de registros","Un agente orquestador"],"correct":[3],"explanation":"Los patrones multiagente usan un agente que delega en otros.","i18n":{"en":{"stem":"Which agent type coordinates other specialized agents to complete a task?","options":["A standard human escalation topic","A nightly scheduled flow","A record-summary prompt template","An orchestrator agent"],"explanation":"Multi-agent patterns use an agent that delegates to others."}}},{"domain":"D1","source":"bank","stem":"¿Qué aporta Data Cloud a la auditoría y el feedback de los agentes?","options":["Almacena los datos de auditoría y feedback","Reemplaza los permisos del usuario del agente","Sustituye a la Trust Layer en el enmascaramiento de datos personales","Genera automáticamente nuevos temas"],"correct":[0],"explanation":"Los registros de auditoría y feedback de IA se guardan en Data Cloud.","i18n":{"en":{"stem":"What does Data Cloud provide for agent audit and feedback?","options":["It stores audit and feedback data","It replaces the agent user's permissions","It replaces the Trust Layer for PII masking","It auto-generates new topics"],"explanation":"AI audit and feedback records are stored in Data Cloud."}}},{"domain":"D1","source":"bank","stem":"¿Qué limitación hay que comunicar a los usuarios sobre las respuestas del agente?","options":["Que las revisa un humano antes de enviarlas","Que son siempre correctas porque usan datos de la empresa","Pueden contener errores","Que no usan datos de Salesforce"],"correct":[2],"explanation":"La IA generativa puede equivocarse; la transparencia es clave.","i18n":{"en":{"stem":"Which limitation should users be told about agent replies?","options":["A human reviews them before sending","They're always correct since they use company data","They may contain errors","They use no Salesforce data"],"explanation":"Generative AI can err; transparency matters."}}},{"domain":"D1","source":"bank","stem":"Un agente responde con información correcta pero demasiado larga. ¿Qué se ajusta primero?","options":["El número de versiones guardadas del agente","Los permisos del usuario del agente sobre el objeto Caso","Las instrucciones de estilo y longitud","El canal de mensajería por uno de voz"],"correct":[2],"explanation":"Instrucciones de formato controlan la longitud.","i18n":{"en":{"stem":"An agent replies correctly but too long. What's adjusted first?","options":["The number of saved agent versions","The agent user's Case object permissions","Style and length instructions","Switching the messaging channel to voice"],"explanation":"Format instructions control length."}}},{"domain":"D1","source":"bank","stem":"¿Qué dos datos ayuda a definir un buen plan de pruebas de un agente? (Elige 2)","options":["Frases de entrada esperadas","La fecha de alta del usuario del agente","El nombre del desarrollador que creó cada flujo","Tema y acción esperados para cada frase","El color del icono del agente en la ventana de chat"],"correct":[0,3],"explanation":"Los casos de prueba definen entrada y resultados esperados.","i18n":{"en":{"stem":"Which two items does a good agent test plan define? (Choose 2)","options":["Expected input utterances","The agent user's creation date","The developer who built each flow","Expected topic and action per utterance","The agent icon color in the chat window"],"explanation":"Test cases define inputs and expected outcomes."}}},{"domain":"D1","source":"bank","stem":"¿Qué se recomienda hacer con las frases de prueba que fallaron una vez corregido el agente?","options":["Enviarlas a todos los clientes para comprobar que ya funcionan","Borrarlas para que no vuelvan a aparecer en los informes de calidad","Repetirlas como pruebas de regresión","Copiarlas en las instrucciones del tema como ejemplos literales obligatorios"],"correct":[2],"explanation":"Las pruebas de regresión evitan que errores corregidos reaparezcan.","i18n":{"en":{"stem":"What should be done with failed test utterances once the agent is fixed?","options":["Send them to all customers to check they now work","Delete them so they don't appear in quality reports","Rerun them as regression tests","Paste them into topic instructions as mandatory literal examples"],"explanation":"Regression tests stop fixed errors from returning."}}},{"domain":"D1","source":"bank","stem":"¿Qué tipo de información debe incluir un agente al escalar a un humano?","options":["Las instrucciones internas completas del tema y la lista de acciones","El razonamiento técnico detallado con todos los pasos del motor","Los datos de otros clientes con consultas parecidas","Motivo y resumen del caso"],"correct":[3],"explanation":"El humano necesita contexto útil, no detalles internos.","i18n":{"en":{"stem":"What info should an agent include when escalating to a human?","options":["The topic's full internal instructions and action list","Detailed technical reasoning with every engine step","Data of other customers with similar queries","Reason and case summary"],"explanation":"The human needs useful context, not internals."}}},{"domain":"D1","source":"bank","stem":"¿Qué ventaja ofrece un agente frente a un formulario web tradicional para clientes?","options":["Entiende peticiones en lenguaje natural","No necesita permisos ni configuración de seguridad","Garantiza que el cliente rellene todos los campos en el orden exacto","Evita cualquier coste de consumo o de licencias en la organización"],"correct":[0],"explanation":"La conversación en lenguaje natural es la ventaja clave.","i18n":{"en":{"stem":"What advantage does an agent offer over a traditional web form?","options":["It understands natural-language requests","It needs no permissions or security setup","It ensures customers fill every field in exact order","It avoids any consumption or license cost"],"explanation":"Natural-language conversation is the key advantage."}}},{"domain":"D1","source":"bank","stem":"¿Qué hacer si un tema necesita datos de un sistema sin API disponible?","options":["Crear una integración o sincronizar los datos","Pedir al modelo que adivine los datos a partir del historial","Escribir los datos a mano en las instrucciones cada semana","Pedir al cliente que los busque y los pegue en el chat"],"correct":[0],"explanation":"El agente solo puede usar datos accesibles mediante acciones o Data Cloud.","i18n":{"en":{"stem":"What if a topic needs data from a system with no API?","options":["Build an integration or sync the data","Ask the model to guess the data from history","Type the data into instructions weekly","Ask the customer to look it up and paste it"],"explanation":"The agent can only use data reachable via actions or Data Cloud."}}},{"domain":"D2","source":"bank","stem":"¿Qué herramienta se usa para crear y probar plantillas de prompt en Salesforce?","options":["El editor de plantillas de correo electrónico Classic","Prompt Builder","Lightning App Builder con un componente de texto enriquecido","Agentforce Builder, desde la sección de variables de cada tema"],"correct":[1],"explanation":"Prompt Builder crea, ancla, previsualiza y activa plantillas.","i18n":{"en":{"stem":"Which tool creates and tests prompt templates in Salesforce?","options":["The Classic email template editor","Prompt Builder","Lightning App Builder with a rich text component","Agentforce Builder, from each topic's variables section"],"explanation":"Prompt Builder creates, grounds, previews and activates templates."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla de prompt genera el valor de un campo en un registro?","options":["Record Summary, que guarda el resumen en cualquier campo","Field Generation","Flex, que solo se puede usar desde Apex","Sales Email, que también rellena campos del registro abierto"],"correct":[1],"explanation":"Field Generation se asocia a un campo y se usa desde Dynamic Forms.","i18n":{"en":{"stem":"Which prompt template type generates a field value on a record?","options":["Record Summary, which saves the summary into any field","Field Generation","Flex, which can only be used from Apex","Sales Email, which also fills fields on the open record"],"explanation":"Field Generation ties to a field and is used from Dynamic Forms."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla de prompt ayuda a los comerciales a redactar correos personalizados?","options":["Record Summary del objeto oportunidad","Field Generation asociada al campo de descripción del contacto","Plantilla de correo Lightning con campos de combinación","Sales Email"],"correct":[3],"explanation":"Sales Email genera borradores de correo a partir del registro.","i18n":{"en":{"stem":"Which prompt template type helps reps draft personalized emails?","options":["Record Summary of the opportunity object","Field Generation tied to the contact description field","A Lightning email template with merge fields","Sales Email"],"explanation":"Sales Email drafts emails from record data."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla permite definir entradas libres (varios objetos) y usarse en flujos, Apex o agentes?","options":["Field Generation, que admite cualquier número de objetos de entrada","Flex","Sales Email, limitada a contactos y leads","Record Summary, que admite entradas personalizadas"],"correct":[1],"explanation":"Las plantillas Flex definen entradas personalizadas.","i18n":{"en":{"stem":"Which template type lets you define free inputs (several objects) and use it in flows, Apex or agents?","options":["Field Generation, which accepts any number of input objects","Flex","Sales Email, limited to contacts and leads","Record Summary, which accepts custom inputs"],"explanation":"Flex templates define custom inputs."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla de prompt usa el asistente para resumir un registro con un prompt personalizado?","options":["Record Summary","Sales Email con destinatario vacío","Field Generation, que crea un campo de resumen nuevo cada vez","Una plantilla Classic de texto plano"],"correct":[0],"explanation":"Record Summary personaliza el resumen de registros del asistente.","i18n":{"en":{"stem":"Which prompt template type does the assistant use to summarize a record with a custom prompt?","options":["Record Summary","Sales Email with an empty recipient","Field Generation, creating a new summary field each time","A Classic plain-text template"],"explanation":"Record Summary customizes the assistant's record summaries."}}},{"domain":"D2","source":"bank","stem":"¿Qué significa anclar (grounding) una plantilla de prompt?","options":["Guardar una copia de la respuesta en un campo del registro","Fijar la temperatura del modelo a cero para respuestas exactas","Bloquear la plantilla para que nadie pueda editarla después de activarla","Añadir datos de la empresa al prompt"],"correct":[3],"explanation":"El grounding aporta contexto con campos, listas relacionadas, flujos, Apex o retrievers.","i18n":{"en":{"stem":"What does grounding a prompt template mean?","options":["Saving a copy of the response to a record field","Setting model temperature to zero for exact answers","Locking the template so no one edits it after activation","Adding company data to the prompt"],"explanation":"Grounding adds context via fields, related lists, flows, Apex or retrievers."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos recursos se pueden insertar en una plantilla de prompt para anclarla? (Elige 2)","options":["Reglas de validación del objeto de entrada","Diseños de página asignados a perfiles","Campos de combinación del registro","Listas relacionadas","Reglas de colaboración basadas en criterios"],"correct":[2,3],"explanation":"También flujos, Apex y retrievers de Data Cloud.","i18n":{"en":{"stem":"Which two resources can be inserted into a prompt template for grounding? (Choose 2)","options":["Input object validation rules","Page layouts assigned to profiles","Record merge fields","Related lists","Criteria-based sharing rules"],"explanation":"Also flows, Apex and Data Cloud retrievers."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de flujo se usa para obtener datos que luego se insertan en una plantilla de prompt?","options":["Flujo desencadenado por plantilla (Template-Triggered Prompt Flow)","Flujo desencadenado por registro before-save","Flujo de pantalla que pregunta al usuario los datos que faltan","Flujo programado que actualiza la plantilla cada noche"],"correct":[0],"explanation":"El Template-Triggered Prompt Flow devuelve texto con Add Prompt Instructions.","i18n":{"en":{"stem":"Which flow type fetches data to insert into a prompt template?","options":["Template-Triggered Prompt Flow","A before-save record-triggered flow","A screen flow asking the user for missing data","A scheduled flow updating the template nightly"],"explanation":"The Template-Triggered Prompt Flow returns text via Add Prompt Instructions."}}},{"domain":"D2","source":"bank","stem":"¿Qué elemento de flujo añade texto al prompt en un flujo desencadenado por plantilla?","options":["Enviar correo con el texto generado al usuario actual","Pantalla con un componente de texto","Añadir instrucciones de prompt (Add Prompt Instructions)","Asignación a una variable de salida sin más"],"correct":[2],"explanation":"Add Prompt Instructions acumula texto para el prompt.","i18n":{"en":{"stem":"Which flow element adds text to the prompt in a template-triggered flow?","options":["Send Email with the generated text to the current user","A screen with a text component","Add Prompt Instructions","A plain Assignment to an output variable"],"explanation":"Add Prompt Instructions accumulates text for the prompt."}}},{"domain":"D2","source":"bank","stem":"¿Qué anotación necesita un método Apex para usarse como recurso de grounding en Prompt Builder?","options":["@future, para que se ejecute de forma asíncrona tras el prompt","@InvocableMethod con la capacidad de plantilla","@TestVisible, que lo expone al constructor de prompts","@ReadOnly, obligatorio para cualquier recurso de prompt"],"correct":[1],"explanation":"Los métodos invocables con capability type de prompt template devuelven el texto.","i18n":{"en":{"stem":"Which annotation does an Apex method need to be a grounding resource in Prompt Builder?","options":["@future, so it runs asynchronously after the prompt","@InvocableMethod with the template capability","@TestVisible, which exposes it to the prompt builder","@ReadOnly, required for any prompt resource"],"explanation":"Invocable methods with the prompt-template capability type return the text."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite la vista previa (Preview) de Prompt Builder?","options":["Publicar la plantilla en producción sin necesidad de activarla","Ver el prompt resuelto y la respuesta con un registro real","Exportar la respuesta a un informe","Cambiar los permisos de los usuarios que la usan"],"correct":[1],"explanation":"Se selecciona un registro de ejemplo para ver el prompt con datos y la respuesta.","i18n":{"en":{"stem":"What does Prompt Builder Preview allow?","options":["Publishing the template to production without activating it","Seeing the resolved prompt and response with a real record","Exporting the response to a report","Changing permissions of its users"],"explanation":"You pick a sample record to see the data-filled prompt and response."}}},{"domain":"D2","source":"bank","stem":"¿Qué hay que hacer para que los usuarios puedan usar una plantilla de prompt?","options":["Activar una versión de la plantilla","Nada: se puede usar en cuanto se guarda el borrador","Guardarla en una carpeta pública de informes compartida con todos","Asignarla a un diseño de página de cada objeto"],"correct":[0],"explanation":"Solo las versiones activadas están disponibles.","i18n":{"en":{"stem":"What must be done so users can use a prompt template?","options":["Activate a template version","Nothing: it's usable as soon as the draft is saved","Save it in a public report folder shared with all","Assign it to each object's page layout"],"explanation":"Only activated versions are available."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos conjuntos de permisos estándar se relacionan con Prompt Builder? (Elige 2)","options":["Prompt Template Manager","Service Cloud User con Omni-Channel","Knowledge User con artículos publicados","Prompt Template User","Marketing User con acceso a campañas"],"correct":[0,3],"explanation":"Manager crea y gestiona; User ejecuta plantillas.","i18n":{"en":{"stem":"Which two standard permission sets relate to Prompt Builder? (Choose 2)","options":["Prompt Template Manager","Service Cloud User with Omni-Channel","Knowledge User with published articles","Prompt Template User","Marketing User with campaign access"],"explanation":"Manager creates and manages; User runs templates."}}},{"domain":"D2","source":"bank","stem":"¿Qué componente de una página de registro muestra el botón para generar un campo con IA?","options":["Dynamic Forms con el campo asociado a la plantilla","La barra de utilidades de la app con un flujo de pantalla","Un diseño de página Classic con botón personalizado","Un componente de informe enriquecido en la cabecera"],"correct":[0],"explanation":"Field Generation aparece en campos de Dynamic Forms con el icono de generación.","i18n":{"en":{"stem":"Which record page component shows the button to generate a field with AI?","options":["Dynamic Forms with the field tied to the template","The app utility bar with a screen flow","A Classic page layout with a custom button","A rich report component in the header"],"explanation":"Field Generation appears on Dynamic Forms fields with the generate icon."}}},{"domain":"D2","source":"bank","stem":"¿Qué modelos de lenguaje puede usar una plantilla de prompt?","options":["Los de Salesforce o uno propio conectado (BYOLLM)","Solo modelos entrenados con los datos de la organización","Únicamente un modelo fijo que no se puede cambiar en ninguna edición","Solo modelos de código abierto instalados en Salesforce"],"correct":[0],"explanation":"Se eligen modelos gestionados por Salesforce o se conecta uno con Einstein Studio.","i18n":{"en":{"stem":"Which language models can a prompt template use?","options":["Salesforce's or a connected one of your own (BYOLLM)","Only models trained on the org's data","Only one fixed model unchangeable in any edition","Only open-source models installed in Salesforce"],"explanation":"Choose Salesforce-managed models or connect one via Einstein Studio."}}},{"domain":"D2","source":"bank","stem":"¿Dónde se configura un modelo propio (BYOLLM) para usarlo en Prompt Builder?","options":["En el App Manager de la aplicación de ventas","En el Object Manager, dentro del objeto plantilla de prompt","En la configuración de la empresa, campo modelo de IA","En Einstein Studio (Model Builder)"],"correct":[3],"explanation":"Model Builder en Einstein Studio registra modelos externos o configurados.","i18n":{"en":{"stem":"Where is a bring-your-own LLM configured for Prompt Builder?","options":["In the sales app's App Manager","In Object Manager, within the prompt template object","In Company Information, AI model field","In Einstein Studio (Model Builder)"],"explanation":"Model Builder in Einstein Studio registers external or configured models."}}},{"domain":"D2","source":"bank","stem":"¿Qué efecto tiene bajar la temperatura de un modelo configurado?","options":["Más idiomas soportados","Menos consumo de almacenamiento de datos en la organización","Respuestas más creativas y variadas entre una ejecución y otra","Respuestas más predecibles"],"correct":[3],"explanation":"Temperatura baja = más determinista; alta = más variedad.","i18n":{"en":{"stem":"What does lowering a configured model's temperature do?","options":["More supported languages","Less data storage use in the org","More creative, varied responses between runs","More predictable responses"],"explanation":"Low temperature = more deterministic; high = more variety."}}},{"domain":"D2","source":"bank","stem":"¿Qué elementos debe incluir un buen prompt? (Elige 2)","options":["Instrucciones contradictorias para que el modelo elija","Palabras clave repetidas sin contexto","Todo el contenido de la base de datos por si acaso","Rol y tarea claros","Formato de salida esperado"],"correct":[3,4],"explanation":"Rol, tarea, contexto, formato y restricciones.","i18n":{"en":{"stem":"Which elements should a good prompt include? (Choose 2)","options":["Contradictory instructions so the model chooses","Repeated keywords without context","The entire database just in case","Clear role and task","Expected output format"],"explanation":"Role, task, context, format and constraints."}}},{"domain":"D2","source":"bank","stem":"¿Qué técnica consiste en incluir ejemplos de entrada y salida en el prompt?","options":["Ajuste fino (fine-tuning) del modelo con los datos de la organización","Recuperación aumentada por generación","Enmascaramiento de datos personales","Few-shot prompting"],"correct":[3],"explanation":"Los ejemplos guían el formato y estilo.","i18n":{"en":{"stem":"Which technique includes input/output examples in the prompt?","options":["Fine-tuning the model on org data","Retrieval-augmented generation","PII masking","Few-shot prompting"],"explanation":"Examples guide format and style."}}},{"domain":"D2","source":"bank","stem":"¿Qué reduce las alucinaciones en una plantilla de prompt?","options":["Pedir respuestas más largas","Subir la temperatura al máximo para explorar más respuestas","Anclar en datos y pedir que no invente","Quitar todos los datos del registro del prompt"],"correct":[2],"explanation":"Grounding y restricciones explícitas reducen invenciones.","i18n":{"en":{"stem":"What reduces hallucinations in a prompt template?","options":["Asking for longer answers","Raising temperature to max to explore more answers","Grounding in data and asking it not to invent","Removing all record data from the prompt"],"explanation":"Grounding and explicit constraints reduce fabrication."}}},{"domain":"D2","source":"bank","stem":"¿Qué pasa con los datos personales del prompt según la configuración de la Trust Layer?","options":["Se borran del registro original de Salesforce","Se traducen","Se envían siempre sin cambios al proveedor del modelo","Pueden enmascararse antes de ir al modelo"],"correct":[3],"explanation":"El data masking sustituye PII y la restaura en la respuesta.","i18n":{"en":{"stem":"What happens to personal data in the prompt per Trust Layer settings?","options":["It's deleted from the original Salesforce record","It's translated","It's always sent unchanged to the model provider","It can be masked before reaching the model"],"explanation":"Data masking swaps PII and restores it in the response."}}},{"domain":"D2","source":"bank","stem":"¿Qué limita qué registros puede usar un usuario al ejecutar una plantilla de prompt?","options":["Los permisos del administrador que creó la plantilla","El idioma de la plantilla","Sus permisos y acceso a datos","Ninguno: las plantillas ignoran la colaboración"],"correct":[2],"explanation":"El grounding respeta el acceso del usuario que ejecuta.","i18n":{"en":{"stem":"What limits which records a user can use when running a prompt template?","options":["The permissions of the admin who built it","The template's language","Their permissions and data access","Nothing: templates ignore sharing"],"explanation":"Grounding honors the running user's access."}}},{"domain":"D2","source":"bank","stem":"¿Qué recurso permite usar contenido no estructurado (PDF, artículos) en una plantilla de prompt?","options":["Una lista de selección con los títulos de los documentos","Un campo de fórmula que lee el PDF adjunto del registro","Un retriever de Data Cloud","Un informe con los documentos"],"correct":[2],"explanation":"Los retrievers consultan índices de búsqueda para RAG.","i18n":{"en":{"stem":"Which resource lets a prompt template use unstructured content (PDFs, articles)?","options":["A picklist with document titles","A formula field reading the record's attached PDF","A Data Cloud retriever","A report of the documents"],"explanation":"Retrievers query search indexes for RAG."}}},{"domain":"D2","source":"bank","stem":"¿Cómo se invoca una plantilla Flex desde Flow?","options":["No se puede invocar desde Flow","Con una acción de plantilla de prompt","Con un elemento Get Records sobre el objeto plantilla","Con una regla de validación que la ejecuta al guardar"],"correct":[1],"explanation":"Las plantillas activas aparecen como acciones en Flow.","i18n":{"en":{"stem":"How is a Flex template invoked from Flow?","options":["It can't be invoked from Flow","With a prompt template action","With Get Records on the template object","With a validation rule running it on save"],"explanation":"Active templates show as actions in Flow."}}},{"domain":"D2","source":"bank","stem":"¿Qué API de Apex permite ejecutar una plantilla de prompt?","options":["Schema.describeSObjects sobre la plantilla","Messaging.sendEmail","ConnectApi (servicio de generación de Einstein LLM)","Database.executeBatch con la plantilla como parámetro"],"correct":[2],"explanation":"ConnectApi.EinsteinLLM permite generar respuestas desde plantillas.","i18n":{"en":{"stem":"Which Apex API runs a prompt template?","options":["Schema.describeSObjects on the template","Messaging.sendEmail","ConnectApi (Einstein LLM generation service)","Database.executeBatch with the template as a parameter"],"explanation":"ConnectApi.EinsteinLLM can generate responses from templates."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene versionar las plantillas de prompt?","options":["Que se pueden usar varias versiones activas a la vez en el mismo campo","Que el modelo aprende de cada versión anterior","Ninguna","Probar cambios sin afectar a la activa"],"correct":[3],"explanation":"Solo una versión está activa; se puede volver a una anterior.","i18n":{"en":{"stem":"What's the benefit of versioning prompt templates?","options":["Several versions can be active at once on the same field","The model learns from each prior version","None","Testing changes without affecting the active one"],"explanation":"Only one version is active; you can roll back."}}},{"domain":"D2","source":"bank","stem":"Una plantilla genera correos con un tono demasiado informal. ¿Qué se cambia?","options":["El tipo de plantilla de Sales Email a Field Generation","Las instrucciones de tono del prompt","Los permisos del usuario que ejecuta la plantilla","El objeto de entrada"],"correct":[1],"explanation":"El tono se especifica en las instrucciones.","i18n":{"en":{"stem":"A template drafts emails in too casual a tone. What's changed?","options":["The template type from Sales Email to Field Generation","The prompt's tone instructions","The running user's permissions","The input object"],"explanation":"Tone is set in the instructions."}}},{"domain":"D2","source":"bank","stem":"¿Qué conviene especificar si la salida de un prompt la va a procesar un flujo?","options":["Que la respuesta sea lo más creativa posible","Nada en especial","Un formato estructurado, como JSON","Que use emojis para separar campos"],"correct":[2],"explanation":"Formato estructurado facilita el procesado posterior.","i18n":{"en":{"stem":"What should be specified if a flow will process a prompt's output?","options":["That the answer be as creative as possible","Nothing special","A structured format, such as JSON","Use emojis to separate fields"],"explanation":"Structured format eases downstream processing."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos riesgos mitiga la detección de toxicidad de la Trust Layer? (Elige 2)","options":["Contenido dañino en la generación","Errores de cálculo en las fórmulas de los campos","Respuestas ofensivas","Registros duplicados en el objeto contacto","Fallos de permisos en las reglas de colaboración"],"correct":[0,2],"explanation":"La detección puntúa y registra contenido tóxico.","i18n":{"en":{"stem":"Which two risks does Trust Layer toxicity detection mitigate? (Choose 2)","options":["Harmful generated content","Calculation errors in field formulas","Offensive responses","Duplicate contact records","Sharing rule permission failures"],"explanation":"Detection scores and logs toxic content."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica un prompt bien delimitado con restricciones como \"máximo 100 palabras\"?","options":["Que la plantilla no puede usar datos del registro","Controla longitud y formato de la respuesta","Que se cobra menos","Que el modelo solo leerá las primeras cien palabras del prompt"],"correct":[1],"explanation":"Las restricciones explícitas mejoran la consistencia.","i18n":{"en":{"stem":"What does a prompt constraint like \"max 100 words\" do?","options":["The template can't use record data","Controls response length and format","It costs less","The model only reads the first hundred words of the prompt"],"explanation":"Explicit constraints improve consistency."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla de prompt se puede usar como acción de agente?","options":["Solo Field Generation asociada a un campo de texto","Solo Sales Email con un destinatario fijo","Flex","Ninguna"],"correct":[2],"explanation":"Las plantillas Flex se pueden añadir como acciones de agente.","i18n":{"en":{"stem":"Which prompt template type can be used as an agent action?","options":["Only Field Generation tied to a text field","Only Sales Email with a fixed recipient","Flex","None"],"explanation":"Flex templates can be added as agent actions."}}},{"domain":"D2","source":"bank","stem":"¿Qué se recomienda para probar una plantilla antes de activarla?","options":["Activarla para todos y revisar las quejas","Probar con un único registro de ejemplo y activarla si funciona una vez","Probar solo con registros vacíos","Previsualizar con varios registros distintos"],"correct":[3],"explanation":"Varios registros revelan casos límite.","i18n":{"en":{"stem":"What's recommended to test a template before activation?","options":["Activate for all and review complaints","Test one sample record and activate if it works once","Test only with empty records","Preview with several different records"],"explanation":"Several records reveal edge cases."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica la sección de prompt resuelto (resolved prompt) en la vista previa?","options":["La respuesta que el modelo ha generado traducida al inglés","Los permisos que faltan al usuario","El coste de la ejecución","El prompt final con los datos insertados"],"correct":[3],"explanation":"Permite comprobar qué recibe el modelo.","i18n":{"en":{"stem":"What does the resolved prompt section in preview show?","options":["The model's response translated to English","Permissions the user lacks","The run's cost","The final prompt with inserted data"],"explanation":"It lets you verify what the model receives."}}},{"domain":"D2","source":"bank","stem":"Una plantilla Field Generation produce valores que superan el tamaño del campo. ¿Qué se hace?","options":["Limitar la longitud en las instrucciones","Aumentar la temperatura","Cambiar el campo a tipo número para que acepte más caracteres","Desactivar la Trust Layer"],"correct":[0],"explanation":"Se debe indicar el límite de longitud del campo destino.","i18n":{"en":{"stem":"A Field Generation template produces values longer than the field allows. What's done?","options":["Limit length in the instructions","Raise temperature","Change the field to number type to accept more characters","Disable the Trust Layer"],"explanation":"State the target field's length limit."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos fuentes de grounding conviene usar para un resumen de cuenta completo? (Elige 2)","options":["Los registros de depuración de Apex del día","Campos de la cuenta","El historial de inicios de sesión","La configuración de colaboración de la organización","Listas relacionadas como oportunidades o casos"],"correct":[1,4],"explanation":"Campos y datos relacionados dan contexto completo.","i18n":{"en":{"stem":"Which two grounding sources suit a full account summary? (Choose 2)","options":["Today's Apex debug logs","Account fields","Login history","The org's sharing settings","Related lists such as opportunities or cases"],"explanation":"Fields and related data give full context."}}},{"domain":"D2","source":"bank","stem":"¿Qué recomienda Salesforce sobre incluir datos sensibles innecesarios en un prompt?","options":["Incluirlos solo en mayúsculas","Evitarlo","Incluirlos siempre para mejorar la precisión de la respuesta","Es indiferente"],"correct":[1],"explanation":"Minimización de datos y enmascaramiento.","i18n":{"en":{"stem":"What does Salesforce recommend about including unnecessary sensitive data in a prompt?","options":["Include it only in capitals","Avoid it","Always include it to improve accuracy","It doesn't matter"],"explanation":"Data minimization and masking."}}},{"domain":"D2","source":"bank","stem":"¿Qué pasa al editar una plantilla de prompt activa?","options":["Se modifica la versión activa al instante para todos los usuarios","Se desactiva la organización","Se crea una nueva versión","Se borran las respuestas anteriores"],"correct":[2],"explanation":"Las ediciones generan versiones que deben activarse.","i18n":{"en":{"stem":"What happens when editing an active prompt template?","options":["The active version changes instantly for all users","The org is deactivated","A new version is created","Prior responses are deleted"],"explanation":"Edits create versions that must be activated."}}},{"domain":"D2","source":"bank","stem":"¿Qué es la ingeniería de prompts?","options":["Programar en Apex","Configurar la red de la organización","Entrenar un modelo nuevo desde cero con datos de Salesforce","Diseñar instrucciones para obtener mejores respuestas"],"correct":[3],"explanation":"Consiste en redactar y refinar prompts.","i18n":{"en":{"stem":"What is prompt engineering?","options":["Coding in Apex","Configuring the org network","Training a new model from scratch on Salesforce data","Designing instructions to get better responses"],"explanation":"It's writing and refining prompts."}}},{"domain":"D2","source":"bank","stem":"Una plantilla Sales Email debe usar datos del contacto y de la oportunidad. ¿Cómo se definen las entradas?","options":["Con una regla de colaboración","Copiando los datos en las instrucciones","Destinatario y objeto relacionado de la plantilla","Creando un campo de fórmula en el contacto con todos los datos"],"correct":[2],"explanation":"Sales Email toma destinatario (contacto/lead) y un registro relacionado.","i18n":{"en":{"stem":"A Sales Email template must use contact and opportunity data. How are inputs defined?","options":["With a sharing rule","Copying data into instructions","The template's recipient and related object","Creating a formula field on contact with all the data"],"explanation":"Sales Email takes a recipient (contact/lead) and a related record."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene usar un flujo como recurso de grounding frente a campos de combinación?","options":["Es siempre más rápido que leer campos directamente","Evita los permisos del usuario","Evita activar la plantilla","Permite lógica y consultas complejas"],"correct":[3],"explanation":"Los flujos filtran, agregan y formatean datos.","i18n":{"en":{"stem":"What's the benefit of a flow as grounding versus merge fields?","options":["It's always faster than reading fields directly","It bypasses user permissions","It avoids activating the template","It allows complex logic and queries"],"explanation":"Flows filter, aggregate and format data."}}},{"domain":"D2","source":"bank","stem":"¿Qué técnica pide al modelo que razone paso a paso antes de responder?","options":["Zero data retention","Cadena de pensamiento (chain of thought)","Enmascaramiento dinámico de datos sensibles","Grounding con listas relacionadas"],"correct":[1],"explanation":"Pedir pasos intermedios mejora tareas complejas.","i18n":{"en":{"stem":"Which technique asks the model to reason step by step before answering?","options":["Zero data retention","Chain of thought","Dynamic sensitive data masking","Grounding with related lists"],"explanation":"Asking for intermediate steps helps complex tasks."}}},{"domain":"D2","source":"bank","stem":"¿Qué ocurre si un campo de combinación del prompt está vacío en el registro?","options":["El modelo inventa el valor de forma segura","El prompt se envía sin ese dato","Se borra el registro","La plantilla falla siempre y no genera respuesta"],"correct":[1],"explanation":"Conviene instruir qué hacer si falta información.","i18n":{"en":{"stem":"What happens if a prompt merge field is blank on the record?","options":["The model safely invents the value","The prompt is sent without that data","The record is deleted","The template always fails with no response"],"explanation":"Instruct what to do when data is missing."}}},{"domain":"D2","source":"bank","stem":"¿Qué instrucción reduce respuestas inventadas cuando faltan datos?","options":["\"Si no tienes el dato, dilo\"","\"Responde siempre con seguridad aunque no sepas\"","\"Sé creativo\"","\"Completa cualquier hueco con tu mejor suposición\""],"correct":[0],"explanation":"Permitir decir \"no lo sé\" reduce alucinaciones.","i18n":{"en":{"stem":"Which instruction reduces invented answers when data is missing?","options":["\"If you don't have the data, say so\"","\"Always answer confidently even if unsure\"","\"Be creative\"","\"Fill any gap with your best guess\""],"explanation":"Allowing \"I don't know\" reduces hallucinations."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite el registro de auditoría de prompts?","options":["Recuperar plantillas borradas hace más de un año","Cambiar el modelo por defecto","Revisar prompts y respuestas generados","Ver contraseñas"],"correct":[2],"explanation":"La auditoría se almacena en Data Cloud.","i18n":{"en":{"stem":"What does prompt audit logging allow?","options":["Recovering templates deleted over a year ago","Changing the default model","Reviewing generated prompts and responses","Seeing passwords"],"explanation":"Audit is stored in Data Cloud."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos fases forman el ciclo de una plantilla de prompt? (Elige 2)","options":["Diseñar y anclar","Exportar a Excel y borrar","Probar y activar","Convertir en informe y suscribir","Compartir por Chatter y archivar"],"correct":[0,2],"explanation":"Crear, anclar, previsualizar, activar y mejorar.","i18n":{"en":{"stem":"Which two phases make up a prompt template lifecycle? (Choose 2)","options":["Design and ground","Export to Excel and delete","Test and activate","Turn into a report and subscribe","Share via Chatter and archive"],"explanation":"Create, ground, preview, activate and improve."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de respuesta da una plantilla Field Generation cuando el usuario pulsa el botón?","options":["Un borrador que el usuario revisa antes de guardar","Un correo electrónico al administrador","Un valor guardado directamente sin posibilidad de revisión","Un caso nuevo"],"correct":[0],"explanation":"El usuario puede aceptar, editar o descartar.","i18n":{"en":{"stem":"What does a Field Generation template produce when the user clicks the button?","options":["A draft the user reviews before saving","An email to the admin","A value saved directly with no review","A new case"],"explanation":"The user can accept, edit or discard."}}},{"domain":"D2","source":"bank","stem":"¿Qué consideración de consumo tienen las plantillas de prompt?","options":["Cada ejecución consume créditos o llamadas","Solo consumen al activarlas","Consumen almacenamiento de archivos","Son gratuitas e ilimitadas sin ninguna medición"],"correct":[0],"explanation":"El uso de LLM se mide (créditos/solicitudes).","i18n":{"en":{"stem":"What consumption consideration do prompt templates have?","options":["Each run consumes credits or calls","They only consume on activation","They consume file storage","They're free and unlimited with no metering"],"explanation":"LLM usage is metered (credits/requests)."}}},{"domain":"D2","source":"bank","stem":"¿Qué recomienda la guía sobre el orden de las partes del prompt?","options":["Poner las restricciones solo al final en letra pequeña","Mezclar instrucciones y datos sin separación para ahorrar espacio","No hay recomendación","Contexto e instrucciones claras antes de la tarea"],"correct":[3],"explanation":"Estructurar el prompt con secciones claras mejora resultados.","i18n":{"en":{"stem":"What does guidance say about ordering prompt parts?","options":["Put constraints only at the end in small print","Mix instructions and data with no separation to save space","No guidance","Context and clear instructions before the task"],"explanation":"Structured prompts with clear sections improve results."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica usar delimitadores (por ejemplo, etiquetas o comillas) alrededor de los datos en un prompt?","options":["Que se cifrarán esos datos","Que el modelo ignorará lo que está entre comillas","Separar datos de instrucciones","Nada"],"correct":[2],"explanation":"Delimitar ayuda a evitar confusión e inyecciones.","i18n":{"en":{"stem":"What does using delimiters (tags or quotes) around data in a prompt do?","options":["That data will be encrypted","The model will ignore quoted content","Separates data from instructions","Nothing"],"explanation":"Delimiting helps avoid confusion and injections."}}},{"domain":"D2","source":"bank","stem":"¿Qué riesgo tiene insertar texto libre de clientes directamente en un prompt?","options":["Ninguno","Que el prompt deja de poder usar campos del registro","Que se borra el texto del cliente","Inyección de instrucciones"],"correct":[3],"explanation":"El texto del usuario puede contener instrucciones maliciosas.","i18n":{"en":{"stem":"What's the risk of inserting customer free text directly into a prompt?","options":["None","The prompt can no longer use record fields","The customer's text is deleted","Instruction injection"],"explanation":"User text may contain malicious instructions."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene una plantilla de prompt frente a escribir el prompt cada vez?","options":["Que no necesita permisos","Que no consume créditos","Que se ejecuta sin modelo","Consistencia y gobierno centralizado"],"correct":[3],"explanation":"Las plantillas estandarizan y se gestionan con versiones y permisos.","i18n":{"en":{"stem":"What's the benefit of a prompt template over writing the prompt each time?","options":["It needs no permissions","It consumes no credits","It runs without a model","Consistency and central governance"],"explanation":"Templates standardize and are managed with versions and permissions."}}},{"domain":"D2","source":"bank","stem":"Un comercial recibe un borrador de correo con datos de otra cuenta. ¿Qué se revisa?","options":["El idioma del usuario","La temperatura del modelo","El origen de los datos de grounding","El tipo de licencia del comercial"],"correct":[2],"explanation":"Un recurso mal filtrado (flujo, Apex o relación) puede traer datos equivocados.","i18n":{"en":{"stem":"A rep gets an email draft with another account's data. What's checked?","options":["User language","Model temperature","Where the grounding data comes from","The rep's license type"],"explanation":"A badly filtered resource (flow, Apex or relation) can bring wrong data."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica la instrucción de rol en un prompt, como \"Eres un asistente de soporte\"?","options":["El objeto de Salesforce del que se leen los datos","El perfil de Salesforce que se asigna al usuario que ejecuta la plantilla","La cola a la que se escala","La perspectiva con la que responder"],"correct":[3],"explanation":"El rol orienta estilo y enfoque.","i18n":{"en":{"stem":"What does a role instruction like \"You are a support assistant\" do?","options":["Sets which object data is read from","Assigns a Salesforce profile to the running user","Sets the escalation queue","Sets the perspective to answer from"],"explanation":"The role steers style and approach."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos ajustes del modelo pueden configurarse al crear un modelo en Einstein Studio? (Elige 2)","options":["Perfiles con acceso a la organización","Diseños de página del modelo","Reglas de colaboración del objeto plantilla","Temperatura","Penalizaciones o límites de generación"],"correct":[3,4],"explanation":"Se configuran hiperparámetros como temperatura, top-p o penalizaciones.","i18n":{"en":{"stem":"Which two model settings can be set when creating a model in Einstein Studio? (Choose 2)","options":["Profiles with org access","Model page layouts","Sharing rules for the template object","Temperature","Generation penalties or limits"],"explanation":"Hyperparameters like temperature, top-p or penalties are set."}}},{"domain":"D2","source":"bank","stem":"¿Qué ocurre si un usuario sin permiso Prompt Template User intenta generar un campo?","options":["No ve o no puede usar la generación","Se usa el modelo por defecto","La genera igualmente con permisos del creador de la plantilla","Se crea un caso para el administrador"],"correct":[0],"explanation":"Se necesitan permisos para ejecutar plantillas.","i18n":{"en":{"stem":"What happens if a user without Prompt Template User tries to generate a field?","options":["They can't see or use generation","The default model is used","It generates anyway with the template creator's permissions","A case is created for the admin"],"explanation":"Permissions are needed to run templates."}}},{"domain":"D2","source":"bank","stem":"¿Qué estrategia ayuda a obtener respuestas consistentes en clasificaciones (por ejemplo, sentimiento)?","options":["No dar ninguna instrucción","Pedir al modelo que invente la categoría más original posible","Subir la temperatura para más variedad","Lista cerrada de valores permitidos"],"correct":[3],"explanation":"Restringir la salida a valores definidos.","i18n":{"en":{"stem":"Which strategy gives consistent classification answers (e.g. sentiment)?","options":["Give no instructions","Ask the model to invent the most original category","Raise temperature for variety","A closed list of allowed values"],"explanation":"Restrict output to defined values."}}},{"domain":"D2","source":"bank","stem":"¿Qué recurso se usa en un prompt para incluir el nombre del usuario que lo ejecuta?","options":["Una constante","Una lista relacionada de usuarios activos","Un campo de combinación del usuario actual","Un retriever de Data Cloud sobre usuarios"],"correct":[2],"explanation":"Se pueden usar datos del usuario en ejecución.","i18n":{"en":{"stem":"Which resource includes the running user's name in a prompt?","options":["A constant","A related list of active users","A current-user merge field","A Data Cloud retriever on users"],"explanation":"Running-user data can be merged."}}},{"domain":"D2","source":"bank","stem":"¿Qué es la generación aumentada por recuperación (RAG)?","options":["Entrenar de nuevo el modelo con cada documento de la empresa","Traducir prompts","Recuperar contenido relevante e incluirlo en el prompt","Guardar las respuestas del modelo en un índice"],"correct":[2],"explanation":"RAG ancla con fragmentos recuperados en tiempo de ejecución.","i18n":{"en":{"stem":"What is retrieval-augmented generation (RAG)?","options":["Retraining the model on every company document","Translating prompts","Retrieving relevant content and adding it to the prompt","Storing model responses in an index"],"explanation":"RAG grounds with fragments retrieved at runtime."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene RAG frente al ajuste fino del modelo para conocimiento cambiante?","options":["Usa contenido actualizado sin reentrenar","Que no consume créditos","Que el modelo memoriza permanentemente todos los documentos","Que no necesita índices de búsqueda"],"correct":[0],"explanation":"RAG consulta datos actuales en cada petición.","i18n":{"en":{"stem":"What's RAG's advantage over fine-tuning for changing knowledge?","options":["Uses up-to-date content without retraining","It consumes no credits","The model permanently memorizes all documents","It needs no search indexes"],"explanation":"RAG queries current data each request."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de recurso se inserta en Prompt Builder para usar un índice de búsqueda de Data Cloud?","options":["Un flujo de pantalla","Un campo fórmula","Un retriever","Una lista relacionada del objeto documento"],"correct":[2],"explanation":"Los retrievers (por defecto o personalizados) consultan el índice.","i18n":{"en":{"stem":"Which resource is inserted in Prompt Builder to use a Data Cloud search index?","options":["A screen flow","A formula field","A retriever","A related list of the document object"],"explanation":"Retrievers (default or custom) query the index."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite un retriever personalizado (custom retriever) en Einstein Studio?","options":["Filtrar y elegir qué campos devolver","Cambiar la temperatura del modelo","Entrenar un modelo nuevo con los documentos","Borrar documentos"],"correct":[0],"explanation":"Se configuran filtros, número de resultados y campos.","i18n":{"en":{"stem":"What does a custom retriever in Einstein Studio allow?","options":["Filtering and choosing returned fields","Changing model temperature","Training a new model on the documents","Deleting documents"],"explanation":"You set filters, result count and fields."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos prácticas mejoran la calidad de un prompt anclado con RAG? (Elige 2)","options":["Usar la temperatura máxima","Recuperar todos los documentos de la empresa en cada prompt","Filtrar el retriever por datos relevantes","Pedir que responda solo con el contexto recuperado","Quitar las instrucciones para dejar más espacio"],"correct":[2,3],"explanation":"Contexto relevante y restricciones claras.","i18n":{"en":{"stem":"Which two practices improve a RAG-grounded prompt? (Choose 2)","options":["Use max temperature","Retrieve every company document each prompt","Filter the retriever to relevant data","Ask it to answer only from retrieved context","Remove instructions to leave more room"],"explanation":"Relevant context and clear constraints."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el límite de tokens de un modelo?","options":["El número máximo de usuarios que pueden usar el modelo a la vez","El número de plantillas activas","El coste mensual fijo","Cuánto texto cabe en prompt y respuesta"],"correct":[3],"explanation":"La ventana de contexto limita entrada y salida.","i18n":{"en":{"stem":"What does a model's token limit indicate?","options":["Max users using the model at once","Number of active templates","Fixed monthly cost","How much text fits in prompt and response"],"explanation":"The context window limits input and output."}}},{"domain":"D2","source":"bank","stem":"Un prompt con muchas listas relacionadas falla por tamaño. ¿Qué se hace?","options":["Reducir y filtrar los datos incluidos","Cambiar el idioma del prompt","Desactivar la auditoría","Añadir más listas relacionadas para compensar"],"correct":[0],"explanation":"Limitar registros y campos al contexto necesario.","i18n":{"en":{"stem":"A prompt with many related lists fails on size. What's done?","options":["Reduce and filter the included data","Change the prompt language","Disable audit","Add more related lists to compensate"],"explanation":"Limit records and fields to needed context."}}},{"domain":"D2","source":"bank","stem":"¿Qué técnica pide al modelo que adopte un formato fijo, como viñetas de tres puntos?","options":["Usar un retriever de Data Cloud","Especificar el formato de salida","Enmascarar los datos personales","Subir la temperatura"],"correct":[1],"explanation":"Formato explícito da salidas consistentes.","i18n":{"en":{"stem":"Which technique makes the model use a fixed format, like three bullets?","options":["Using a Data Cloud retriever","Specifying the output format","Masking personal data","Raising temperature"],"explanation":"Explicit format gives consistent outputs."}}},{"domain":"D2","source":"bank","stem":"¿Qué consideración hay con los idiomas en Prompt Builder?","options":["No admite otros idiomas","El modelo responde siempre en inglés y no se puede cambiar","El idioma depende del tipo de registro","Indicar el idioma de respuesta deseado"],"correct":[3],"explanation":"Conviene pedir explícitamente el idioma o usar el del usuario.","i18n":{"en":{"stem":"What's a language consideration in Prompt Builder?","options":["No other languages are supported","The model always answers in English, unchangeable","Language depends on record type","State the desired response language"],"explanation":"Explicitly ask for a language or use the user's."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite el panel de respuesta de la vista previa?","options":["Guardar la respuesta como versión de la plantilla","Publicar la respuesta en Chatter para todos los usuarios","Ver la respuesta generada y ajustar el prompt","Ver costes"],"correct":[2],"explanation":"Se itera sobre el prompt comparando respuestas.","i18n":{"en":{"stem":"What does the preview's response panel allow?","options":["Saving the response as a template version","Posting the response to Chatter for all users","Seeing the generated response and tuning the prompt","Viewing costs"],"explanation":"You iterate on the prompt comparing responses."}}},{"domain":"D2","source":"bank","stem":"¿Qué método de grounding conviene para datos calculados como el total de compras del último año?","options":["Un flujo o Apex que calcule el valor","Escribir el total a mano en la plantilla","Pedir al modelo que sume las compras a partir de la lista completa","Un informe"],"correct":[0],"explanation":"Los cálculos se hacen antes de enviar al modelo.","i18n":{"en":{"stem":"Which grounding method suits computed data like last year's total purchases?","options":["A flow or Apex computing the value","Typing the total into the template","Asking the model to sum from the full list","A report"],"explanation":"Calculations are done before sending to the model."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite el ajuste de modelo de una plantilla en Prompt Builder?","options":["Nada","Elegir qué modelo ejecuta la plantilla","Definir los usuarios que ven la respuesta","Cambiar el objeto de entrada después de activar"],"correct":[1],"explanation":"Cada plantilla puede usar un modelo estándar o configurado.","i18n":{"en":{"stem":"What does a template's model setting in Prompt Builder allow?","options":["Nothing","Choosing which model runs the template","Defining who sees the response","Changing the input object after activation"],"explanation":"Each template can use a standard or configured model."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos acciones son buenas prácticas de seguridad en prompts? (Elige 2)","options":["Pegar contraseñas para que el modelo pueda conectarse","No incluir secretos ni credenciales","Incluir todos los datos personales disponibles","Pedir al modelo que ignore la Trust Layer","Separar datos de usuario de las instrucciones"],"correct":[1,4],"explanation":"Sin secretos y con delimitación clara.","i18n":{"en":{"stem":"Which two are prompt security best practices? (Choose 2)","options":["Paste passwords so the model can connect","Don't include secrets or credentials","Include all available personal data","Ask the model to ignore the Trust Layer","Separate user data from instructions"],"explanation":"No secrets and clear delimitation."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene pedir al modelo que cite la fuente usada en respuestas con RAG?","options":["Desactiva la auditoría","Reduce el número de tokens a la mitad","Evita activar la plantilla","Permite verificar la respuesta"],"correct":[3],"explanation":"Las citas facilitan la comprobación.","i18n":{"en":{"stem":"What's the benefit of asking the model to cite sources in RAG answers?","options":["It disables audit","It halves token usage","It avoids activating the template","It allows verifying the answer"],"explanation":"Citations make checking easier."}}},{"domain":"D2","source":"bank","stem":"¿Qué hace una plantilla de prompt de tipo Flex con entradas definidas como objetos?","options":["Se ejecuta sin datos","Crea los registros de entrada","Lee automáticamente todos los registros del objeto","Recibe registros concretos al invocarse"],"correct":[3],"explanation":"Las entradas Flex se pasan al invocar (flujo, Apex o agente).","i18n":{"en":{"stem":"What does a Flex template with object-typed inputs do?","options":["Runs with no data","Creates the input records","Automatically reads every object record","Receives specific records when invoked"],"explanation":"Flex inputs are passed on invocation (flow, Apex or agent)."}}},{"domain":"D2","source":"bank","stem":"¿Qué aporta el feedback de usuarios sobre respuestas generadas?","options":["Datos para mejorar las plantillas","Reentrenamiento automático inmediato del modelo","Cambio automático de permisos","Nada"],"correct":[0],"explanation":"El feedback se guarda para análisis.","i18n":{"en":{"stem":"What does user feedback on generated responses provide?","options":["Data to improve templates","Immediate automatic model retraining","Automatic permission changes","Nothing"],"explanation":"Feedback is stored for analysis."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de plantilla elegirías para generar un resumen de un caso dentro de un flujo de cierre?","options":["Flex con el caso como entrada","Ninguna","Sales Email con el contacto como destinatario","Field Generation sobre un campo de otra cuenta"],"correct":[0],"explanation":"Flex se invoca desde Flow con entradas personalizadas.","i18n":{"en":{"stem":"Which template type would you pick to summarize a case inside a closing flow?","options":["Flex with the case as input","None","Sales Email with the contact as recipient","Field Generation on another account's field"],"explanation":"Flex is invoked from Flow with custom inputs."}}},{"domain":"D2","source":"bank","stem":"¿Qué ocurre con la respuesta de una acción de prompt en Flow?","options":["Se borra al terminar el elemento","Se guarda en una variable para usarla después","Se envía automáticamente por correo al cliente","Se publica en Chatter"],"correct":[1],"explanation":"La salida se puede asignar a campos o usar en otros elementos.","i18n":{"en":{"stem":"What happens to a prompt action's response in Flow?","options":["It's deleted when the element ends","It's stored in a variable for later use","It's auto-emailed to the customer","It's posted to Chatter"],"explanation":"Output can be assigned to fields or used in other elements."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica una buena práctica de redacción de instrucciones negativas?","options":["Usar solo frases negativas para limitar todo lo posible","Repetirlas cinco veces","Escribirlas en mayúsculas","Preferir lo que sí debe hacer"],"correct":[3],"explanation":"Las instrucciones positivas suelen ser más eficaces.","i18n":{"en":{"stem":"What's good practice for negative instructions?","options":["Use only negative phrasing to limit everything","Repeat them five times","Write them in capitals","Prefer stating what it should do"],"explanation":"Positive instructions are usually more effective."}}},{"domain":"D2","source":"bank","stem":"¿Qué capacidad de Einstein Studio permite probar varios modelos con el mismo prompt?","options":["Comparar en el playground de modelos","Crear un retriever","Exportar los modelos a una sandbox","Activar la Trust Layer"],"correct":[0],"explanation":"El playground permite probar modelos y parámetros.","i18n":{"en":{"stem":"Which Einstein Studio capability tests several models with the same prompt?","options":["Comparing in the model playground","Creating a retriever","Exporting models to a sandbox","Enabling the Trust Layer"],"explanation":"The playground tests models and parameters."}}},{"domain":"D2","source":"bank","stem":"Un administrador quiere que un campo de resumen se rellene automáticamente al crear un caso. ¿Qué combina?","options":["Flujo desencadenado por registro y plantilla Flex","Un informe programado","Sales Email con destinatario del caso","Field Generation con un usuario que pulse el botón"],"correct":[0],"explanation":"El flujo invoca la plantilla y guarda el resultado.","i18n":{"en":{"stem":"An admin wants a summary field auto-filled when a case is created. What's combined?","options":["Record-triggered flow and a Flex template","A scheduled report","Sales Email to the case recipient","Field Generation with a user clicking the button"],"explanation":"The flow invokes the template and saves the result."}}},{"domain":"D2","source":"bank","stem":"¿Qué consideración hay al invocar prompts en flujos desencadenados por registro con mucho volumen?","options":["Que no se pueden invocar prompts desde flujos","Consumo y latencia de cada llamada","Que bloquean la organización","Que no consumen nada"],"correct":[1],"explanation":"Volumen alto multiplica consumo; se suelen usar rutas asíncronas.","i18n":{"en":{"stem":"What's a consideration when invoking prompts in high-volume record-triggered flows?","options":["Prompts can't be invoked from flows","Consumption and latency per call","They lock the org","They consume nothing"],"explanation":"High volume multiplies consumption; async paths are common."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos elementos ayudan a evaluar la calidad de una plantilla? (Elige 2)","options":["Color del botón de generación","Número de campos del objeto de entrada","Precisión frente a los datos","Adecuación del tono y formato","Número de perfiles"],"correct":[2,3],"explanation":"Se evalúa exactitud, relevancia, tono y formato.","i18n":{"en":{"stem":"Which two elements help evaluate a template's quality? (Choose 2)","options":["Generate button color","Number of input object fields","Accuracy against the data","Fit of tone and format","Number of profiles"],"explanation":"Evaluate accuracy, relevance, tone and format."}}},{"domain":"D2","source":"bank","stem":"¿Qué es la respuesta zero-shot?","options":["Una respuesta vacía","Una respuesta sin ejemplos en el prompt","Una respuesta que no consume créditos","Una respuesta sin datos del registro"],"correct":[1],"explanation":"Zero-shot = sin ejemplos; few-shot = con ejemplos.","i18n":{"en":{"stem":"What is a zero-shot response?","options":["An empty response","A response with no examples in the prompt","A response consuming no credits","A response with no record data"],"explanation":"Zero-shot = no examples; few-shot = with examples."}}},{"domain":"D2","source":"bank","stem":"¿Qué recurso de Prompt Builder permite incluir datos del perfil unificado de Data Cloud?","options":["Campos de Data Cloud o un data graph","Una lista relacionada de contactos duplicados","Un campo fórmula de la cuenta","Un informe"],"correct":[0],"explanation":"Los prompts pueden usar datos de Data Cloud (DMOs, data graphs).","i18n":{"en":{"stem":"Which Prompt Builder resource includes unified Data Cloud profile data?","options":["Data Cloud fields or a data graph","A related list of duplicate contacts","An account formula field","A report"],"explanation":"Prompts can use Data Cloud data (DMOs, data graphs)."}}},{"domain":"D2","source":"bank","stem":"¿Qué conviene hacer si dos plantillas generan textos muy distintos para casos iguales?","options":["Borrar una sin revisar","Unificar instrucciones y bajar la temperatura","Subir la temperatura de ambas","Nada"],"correct":[1],"explanation":"Consistencia con instrucciones comunes y menos aleatoriedad.","i18n":{"en":{"stem":"What to do if two templates produce very different text for identical cases?","options":["Delete one without review","Align instructions and lower temperature","Raise both temperatures","Nothing"],"explanation":"Consistency via shared instructions and less randomness."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el campo de descripción de una plantilla de prompt usada como acción de agente?","options":["La versión activa","Los permisos necesarios","El nombre del modelo de lenguaje","Cuándo debe usarla el agente"],"correct":[3],"explanation":"El agente usa la descripción para elegir la acción.","i18n":{"en":{"stem":"What does a prompt template's description indicate when used as an agent action?","options":["The active version","The required permissions","The language model name","When the agent should use it"],"explanation":"The agent uses the description to choose the action."}}},{"domain":"D2","source":"bank","stem":"Un prompt debe redactar respuestas a reseñas de clientes. ¿Qué instrucción mejora la seguridad de marca?","options":["\"Responde lo que quieras\"","Directrices de tono y temas prohibidos","\"Promete reembolsos\"","\"Usa siempre humor\""],"correct":[1],"explanation":"Las directrices de marca limitan riesgos.","i18n":{"en":{"stem":"A prompt drafts replies to customer reviews. Which instruction improves brand safety?","options":["\"Reply however you like\"","Tone guidelines and forbidden topics","\"Promise refunds\"","\"Always use humor\""],"explanation":"Brand guidelines limit risk."}}},{"domain":"D2","source":"bank","stem":"¿Qué pasa con la respuesta del modelo antes de mostrarla al usuario en la Trust Layer?","options":["Se evalúa toxicidad y se restauran datos enmascarados","Se traduce siempre al inglés","Se borra","Se envía a un humano para aprobar cada respuesta"],"correct":[0],"explanation":"La respuesta pasa por detección de toxicidad y desenmascaramiento.","i18n":{"en":{"stem":"What happens to the model response in the Trust Layer before showing it?","options":["Toxicity is scored and masked data restored","It's always translated to English","It's deleted","A human approves every response"],"explanation":"The response goes through toxicity detection and demasking."}}},{"domain":"D2","source":"bank","stem":"¿Qué técnica ayuda a dividir una tarea compleja en varios prompts más simples?","options":["Enmascaramiento","Encadenamiento de prompts","Zero data retention","Subir el límite de tokens"],"correct":[1],"explanation":"Prompt chaining reparte la tarea en pasos.","i18n":{"en":{"stem":"Which technique splits a complex task into several simpler prompts?","options":["Masking","Prompt chaining","Zero data retention","Raising the token limit"],"explanation":"Prompt chaining spreads the task across steps."}}},{"domain":"D2","source":"bank","stem":"¿Qué consideración hay al cambiar el modelo de una plantilla ya en uso?","options":["Hay que recrear los permisos","Ninguna: todos los modelos responden igual","Volver a probar porque las respuestas cambian","Se borran las versiones anteriores"],"correct":[2],"explanation":"Modelos distintos producen resultados distintos.","i18n":{"en":{"stem":"What's a consideration when changing the model of a template in use?","options":["Permissions must be recreated","None: all models answer alike","Retest since responses change","Prior versions are deleted"],"explanation":"Different models produce different results."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de grounding usar para incluir los tres últimos casos de un contacto?","options":["El campo descripción del contacto","Una constante","Un retriever de toda la base de casos","Lista relacionada con filtro u orden"],"correct":[3],"explanation":"Las listas relacionadas pueden limitarse en número y orden.","i18n":{"en":{"stem":"Which grounding includes a contact's last three cases?","options":["The contact description field","A constant","A retriever over the whole case base","A related list with filter or order"],"explanation":"Related lists can be limited by count and order."}}},{"domain":"D2","source":"bank","stem":"¿Qué ventaja tiene probar prompts en sandbox?","options":["No afecta a datos ni usuarios de producción","Que en sandbox los modelos son más precisos","Que no hacen falta permisos","Que no se registra nada"],"correct":[0],"explanation":"Se prueba sin riesgos y luego se despliega.","i18n":{"en":{"stem":"What's the benefit of testing prompts in a sandbox?","options":["It doesn't affect production data or users","Models are more accurate in sandboxes","No permissions needed","Nothing is logged"],"explanation":"Test risk-free then deploy."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos fuentes externas pueden alimentar un prompt mediante Apex o flujos? (Elige 2)","options":["Contraseñas del usuario","Datos de MuleSoft","Llamadas a APIs externas","Notas personales del administrador","Registros de otra organización sin integración"],"correct":[1,2],"explanation":"Apex/Flow pueden obtener datos externos e inyectarlos.","i18n":{"en":{"stem":"Which two external sources can feed a prompt via Apex or flows? (Choose 2)","options":["User passwords","MuleSoft data","External API calls","The admin's personal notes","Another org's records without integration"],"explanation":"Apex/Flow can fetch external data and inject it."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica una respuesta del modelo que se sale del formato pedido?","options":["Que falta un permiso","Que hay que borrar la plantilla","Hay que reforzar el formato con ejemplos","Que el modelo está estropeado"],"correct":[2],"explanation":"Ejemplos y especificación clara mejoran el cumplimiento.","i18n":{"en":{"stem":"What does a model response breaking the requested format indicate?","options":["A permission is missing","The template must be deleted","Reinforce the format with examples","The model is broken"],"explanation":"Examples and clear spec improve compliance."}}},{"domain":"D2","source":"bank","stem":"¿Qué permite la acción estándar de agente para ejecutar una plantilla de prompt?","options":["Generar texto anclado en la conversación","Exportar respuestas","Cambiar el modelo","Activar plantillas automáticamente"],"correct":[0],"explanation":"Las plantillas se exponen como acciones del agente.","i18n":{"en":{"stem":"What does the agent action that runs a prompt template allow?","options":["Generating grounded text in the conversation","Exporting responses","Changing the model","Auto-activating templates"],"explanation":"Templates are exposed as agent actions."}}},{"domain":"D2","source":"bank","stem":"¿Qué limitación de Field Generation hay que considerar?","options":["No necesita Dynamic Forms","Se ejecuta sin usuario","Solo para campos de texto compatibles","Funciona con cualquier tipo de campo, incluidos búsqueda y número"],"correct":[2],"explanation":"Se asocia a campos de texto (o compatibles) en Dynamic Forms.","i18n":{"en":{"stem":"Which Field Generation limitation should be considered?","options":["It doesn't need Dynamic Forms","It runs without a user","Only for compatible text fields","It works on any field type, including lookups and numbers"],"explanation":"It ties to text (or compatible) fields in Dynamic Forms."}}},{"domain":"D2","source":"bank","stem":"¿Qué elemento evita que un prompt de resumen incluya datos de campos ocultos al usuario?","options":["La seguridad de campo del usuario","La temperatura","El idioma","La descripción de la plantilla"],"correct":[0],"explanation":"El grounding respeta FLS y colaboración.","i18n":{"en":{"stem":"What keeps a summary prompt from including fields hidden from the user?","options":["The user's field-level security","Temperature","Language","The template description"],"explanation":"Grounding honors FLS and sharing."}}},{"domain":"D2","source":"bank","stem":"¿Qué estrategia es mejor para respuestas largas con secciones fijas?","options":["Pedir \"escribe algo largo\"","Plantilla de salida con encabezados definidos","Dejar que el modelo elija estructura","Usar temperatura máxima"],"correct":[1],"explanation":"Una estructura definida guía la salida.","i18n":{"en":{"stem":"Which strategy is best for long responses with fixed sections?","options":["Ask \"write something long\"","An output template with defined headings","Let the model choose structure","Use max temperature"],"explanation":"A defined structure guides output."}}},{"domain":"D2","source":"bank","stem":"¿Qué se recomienda documentar de cada plantilla de prompt?","options":["Nada","Las contraseñas usadas","Propósito, entradas y responsable","Solo la fecha de creación"],"correct":[2],"explanation":"Documentar facilita gobierno y mantenimiento.","i18n":{"en":{"stem":"What should be documented for each prompt template?","options":["Nothing","Passwords used","Purpose, inputs and owner","Only the creation date"],"explanation":"Documenting eases governance and maintenance."}}},{"domain":"D2","source":"bank","stem":"¿Qué indica el término alucinación en IA generativa?","options":["Un tiempo de espera agotado","Información inventada presentada como cierta","Un dato enmascarado","Un error de permisos"],"correct":[1],"explanation":"El modelo genera contenido plausible pero falso.","i18n":{"en":{"stem":"What does hallucination mean in generative AI?","options":["A timeout","Invented information presented as true","A masked value","A permission error"],"explanation":"The model generates plausible but false content."}}},{"domain":"D2","source":"bank","stem":"¿Qué tipo de prompts se benefician más de una temperatura alta?","options":["Extracción de datos exactos","Clasificaciones con valores fijos","Ideas creativas o lluvia de ideas","Cálculos"],"correct":[2],"explanation":"La creatividad tolera variabilidad; la extracción no.","i18n":{"en":{"stem":"Which prompts benefit most from high temperature?","options":["Exact data extraction","Fixed-value classification","Creative ideas or brainstorming","Calculations"],"explanation":"Creativity tolerates variability; extraction doesn't."}}},{"domain":"D2","source":"bank","stem":"¿Qué dos objetos o datos registran el uso de IA generativa para auditoría? (Elige 2)","options":["Reglas de validación","Tipos de registro","Registros de auditoría de la Trust Layer","Diseños de página","Feedback de usuarios"],"correct":[2,4],"explanation":"Audit trail y feedback se almacenan en Data Cloud.","i18n":{"en":{"stem":"Which two records log generative AI use for audit? (Choose 2)","options":["Validation rules","Record types","Trust Layer audit records","Page layouts","User feedback"],"explanation":"Audit trail and feedback are stored in Data Cloud."}}},{"domain":"D3","source":"bank","stem":"¿Qué papel tiene Data Cloud en Agentforce?","options":["Aporta datos unificados y RAG a los agentes","Aloja el modelo de lenguaje entrenado con los datos del cliente","Sustituye a la base de datos de Salesforce y elimina los objetos estándar","Gestiona los permisos de los usuarios internos de la organización"],"correct":[0],"explanation":"Data Cloud unifica datos, indexa contenido no estructurado y guarda auditoría.","i18n":{"en":{"stem":"What role does Data Cloud play in Agentforce?","options":["Provides unified data and RAG to agents","Hosts the LLM trained on customer data","Replaces the Salesforce database and removes standard objects","Manages internal users' permissions"],"explanation":"Data Cloud unifies data, indexes unstructured content and stores audit."}}},{"domain":"D3","source":"bank","stem":"¿Qué crea automáticamente una Agentforce Data Library al subir archivos?","options":["Un tema nuevo con acciones para cada archivo subido","Un informe de uso","Un objeto personalizado por archivo con sus campos","Ingesta, índice de búsqueda y retriever"],"correct":[3],"explanation":"ADL configura los componentes de Data Cloud necesarios para RAG.","i18n":{"en":{"stem":"What does an Agentforce Data Library automatically create when files are uploaded?","options":["A new topic with actions per uploaded file","A usage report","A custom object per file with its fields","Ingestion, search index and retriever"],"explanation":"ADL sets up the Data Cloud components needed for RAG."}}},{"domain":"D3","source":"bank","stem":"¿Qué fuentes admite una Agentforce Data Library? (Elige 2)","options":["Reglas de colaboración de la organización","Artículos de Knowledge","Contraseñas de usuarios","Diseños de página","Archivos subidos (por ejemplo PDF)"],"correct":[1,4],"explanation":"ADL usa Knowledge o archivos (y otras fuentes según versión).","i18n":{"en":{"stem":"Which sources does an Agentforce Data Library support? (Choose 2)","options":["Org sharing rules","Knowledge articles","User passwords","Page layouts","Uploaded files (e.g. PDF)"],"explanation":"ADL uses Knowledge or files (and other sources by release)."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un índice de búsqueda (search index) en Data Cloud?","options":["Una estructura para buscar contenido por similitud o palabras","Un objeto de auditoría","Un informe ordenado por fecha","Una lista de selección con los campos más usados"],"correct":[0],"explanation":"Los índices vectoriales o híbridos permiten recuperación semántica.","i18n":{"en":{"stem":"What is a search index in Data Cloud?","options":["A structure to search content by similarity or keywords","An audit object","A date-sorted report","A picklist of most-used fields"],"explanation":"Vector or hybrid indexes enable semantic retrieval."}}},{"domain":"D3","source":"bank","stem":"¿Qué diferencia hay entre búsqueda vectorial e híbrida?","options":["No hay diferencia","La vectorial solo busca palabras exactas y la híbrida solo semántica","La híbrida no usa índices","La híbrida combina semántica y palabras clave"],"correct":[3],"explanation":"Hybrid combina similitud vectorial con coincidencia léxica.","i18n":{"en":{"stem":"What's the difference between vector and hybrid search?","options":["No difference","Vector only matches exact words and hybrid only semantics","Hybrid uses no index","Hybrid combines semantics and keywords"],"explanation":"Hybrid combines vector similarity with lexical matching."}}},{"domain":"D3","source":"bank","stem":"¿Qué es el troceado (chunking) al indexar documentos?","options":["Borrar las partes repetidas de los documentos antes de subirlos","Dividir el contenido en fragmentos para indexarlo","Comprimir los archivos para ahorrar almacenamiento","Cifrar el texto"],"correct":[1],"explanation":"Los fragmentos se convierten en vectores y se recuperan por relevancia.","i18n":{"en":{"stem":"What is chunking when indexing documents?","options":["Deleting repeated parts before upload","Splitting content into fragments for indexing","Compressing files to save storage","Encrypting the text"],"explanation":"Chunks become vectors and are retrieved by relevance."}}},{"domain":"D3","source":"bank","stem":"¿Qué son los embeddings?","options":["Campos de fórmula","Componentes Lightning embebidos","Representaciones numéricas del significado del texto","Archivos adjuntos incrustados en los registros"],"correct":[2],"explanation":"Los vectores permiten comparar similitud semántica.","i18n":{"en":{"stem":"What are embeddings?","options":["Formula fields","Embedded Lightning components","Numeric representations of text meaning","Files embedded in records"],"explanation":"Vectors allow semantic similarity comparison."}}},{"domain":"D3","source":"bank","stem":"¿Qué hace un retriever?","options":["Recupera contraseñas","Recupera versiones antiguas de plantillas","Recupera registros borrados de la papelera","Recupera los fragmentos más relevantes de un índice"],"correct":[3],"explanation":"El retriever consulta el índice y devuelve resultados para el prompt.","i18n":{"en":{"stem":"What does a retriever do?","options":["Recovers passwords","Restores old template versions","Restores deleted records from the bin","Fetches the most relevant chunks from an index"],"explanation":"The retriever queries the index and returns results for the prompt."}}},{"domain":"D3","source":"bank","stem":"¿Dónde se crean y configuran retrievers personalizados?","options":["En Agentforce Builder, dentro de cada tema","En Einstein Studio","En Lightning App Builder","En el Object Manager del objeto Knowledge"],"correct":[1],"explanation":"Einstein Studio permite crear retrievers con filtros y campos.","i18n":{"en":{"stem":"Where are custom retrievers created and configured?","options":["In Agentforce Builder, within each topic","In Einstein Studio","In Lightning App Builder","In the Knowledge object's Object Manager"],"explanation":"Einstein Studio lets you create retrievers with filters and fields."}}},{"domain":"D3","source":"bank","stem":"¿Para qué sirven los filtros de un retriever?","options":["Limitar los resultados a contenido relevante","Ocultar el retriever a ciertos usuarios","Cambiar el modelo de embeddings","Programar la ingesta"],"correct":[0],"explanation":"Filtrar por idioma, producto o categoría mejora la precisión.","i18n":{"en":{"stem":"What are retriever filters for?","options":["Limiting results to relevant content","Hiding the retriever from some users","Changing the embedding model","Scheduling ingestion"],"explanation":"Filtering by language, product or category improves precision."}}},{"domain":"D3","source":"bank","stem":"¿Qué objeto de Data Cloud almacena los datos tal como se ingieren?","options":["Data Lake Object (DLO)","Data Model Object (DMO), que guarda los datos en bruto","Segmento","Calculated Insight Object"],"correct":[0],"explanation":"DLO = datos ingeridos; DMO = modelo armonizado.","i18n":{"en":{"stem":"Which Data Cloud object stores data as ingested?","options":["Data Lake Object (DLO)","Data Model Object (DMO), which holds raw data","Segment","Calculated Insight Object"],"explanation":"DLO = ingested data; DMO = harmonized model."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un Data Model Object (DMO)?","options":["Una tabla temporal de la vista previa","Un objeto estándar de CRM","Un objeto del modelo canónico al que se mapean los datos","Un archivo de configuración del modelo de lenguaje"],"correct":[2],"explanation":"Los DMOs armonizan datos de distintas fuentes.","i18n":{"en":{"stem":"What is a Data Model Object (DMO)?","options":["A temporary preview table","A standard CRM object","A canonical model object data is mapped to","An LLM configuration file"],"explanation":"DMOs harmonize data from different sources."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un flujo de datos (data stream) en Data Cloud?","options":["Un tema de agente","Un flujo de pantalla que muestra datos al usuario","Un informe de datos en tiempo real","La conexión que ingiere datos de una fuente"],"correct":[3],"explanation":"Data streams definen fuente, programación y DLO.","i18n":{"en":{"stem":"What is a data stream in Data Cloud?","options":["An agent topic","A screen flow showing data to the user","A real-time data report","The connection ingesting data from a source"],"explanation":"Data streams define source, schedule and DLO."}}},{"domain":"D3","source":"bank","stem":"¿Qué proceso unifica registros del mismo cliente de distintas fuentes?","options":["Reglas de duplicados del objeto contacto","Asignación de territorios","Fusión manual de cuentas en CRM","Resolución de identidades"],"correct":[3],"explanation":"Identity resolution usa reglas de coincidencia y reconciliación.","i18n":{"en":{"stem":"Which process unifies the same customer's records from different sources?","options":["Contact duplicate rules","Territory assignment","Manual account merge in CRM","Identity resolution"],"explanation":"Identity resolution uses match and reconciliation rules."}}},{"domain":"D3","source":"bank","stem":"¿Qué produce la resolución de identidades?","options":["Segmentos de marketing listos para enviar","Índices vectoriales","Plantillas de prompt","Perfiles unificados"],"correct":[3],"explanation":"Genera Unified Individual (y enlaces) para una vista 360.","i18n":{"en":{"stem":"What does identity resolution produce?","options":["Marketing segments ready to send","Vector indexes","Prompt templates","Unified profiles"],"explanation":"It produces Unified Individuals (and links) for a 360 view."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos tipos de reglas componen un conjunto de reglas de identidad? (Elige 2)","options":["Reglas de validación","Reglas de reconciliación","Reglas de escalado","Reglas de asignación","Reglas de coincidencia"],"correct":[1,4],"explanation":"Match rules deciden quién es quién; reconciliation rules qué valor prevalece.","i18n":{"en":{"stem":"Which two rule types make up an identity ruleset? (Choose 2)","options":["Validation rules","Reconciliation rules","Escalation rules","Assignment rules","Match rules"],"explanation":"Match rules decide who's who; reconciliation rules which value wins."}}},{"domain":"D3","source":"bank","stem":"¿Qué son los Calculated Insights?","options":["Temas de agente","Métricas calculadas sobre los datos de Data Cloud","Informes de CRM con fórmulas de resumen","Plantillas de prompt de resumen"],"correct":[1],"explanation":"Se definen con SQL (o constructor) y pueden usarse en agentes y segmentos.","i18n":{"en":{"stem":"What are Calculated Insights?","options":["Agent topics","Metrics computed over Data Cloud data","CRM reports with summary formulas","Summary prompt templates"],"explanation":"Defined with SQL (or builder), usable in agents and segments."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un Data Graph en Data Cloud?","options":["Un gráfico de un panel de CRM","Una vista precalculada de datos relacionados de un perfil","Un índice vectorial","Un diagrama de Schema Builder"],"correct":[1],"explanation":"Los data graphs combinan DMOs relacionados para consultas rápidas (p. ej. en prompts).","i18n":{"en":{"stem":"What is a Data Graph in Data Cloud?","options":["A CRM dashboard chart","A precomputed view of a profile's related data","A vector index","A Schema Builder diagram"],"explanation":"Data graphs combine related DMOs for fast queries (e.g. in prompts)."}}},{"domain":"D3","source":"bank","stem":"¿Qué ventaja tiene usar un Data Graph para anclar un prompt?","options":["Que evita configurar permisos de Data Cloud","Acceso rápido a datos relacionados del cliente","Que sustituye a la resolución de identidades","Que no consume créditos"],"correct":[1],"explanation":"Ofrece datos estructurados y relacionados con baja latencia.","i18n":{"en":{"stem":"What's the benefit of using a Data Graph to ground a prompt?","options":["It avoids setting Data Cloud permissions","Fast access to the customer's related data","It replaces identity resolution","It consumes no credits"],"explanation":"It gives low-latency structured related data."}}},{"domain":"D3","source":"bank","stem":"¿Qué permite el enfoque Zero Copy de Data Cloud?","options":["Borrar duplicados","Evitar la resolución de identidades","Usar datos de otros almacenes sin copiarlos","Copiar todos los datos de CRM a un almacén externo cada hora"],"correct":[2],"explanation":"Zero Copy federa datos con Snowflake, Databricks, BigQuery, etc.","i18n":{"en":{"stem":"What does Data Cloud's Zero Copy approach allow?","options":["Deleting duplicates","Skipping identity resolution","Using data in other stores without copying it","Copying all CRM data to an external store hourly"],"explanation":"Zero Copy federates with Snowflake, Databricks, BigQuery, etc."}}},{"domain":"D3","source":"bank","stem":"¿Qué conector ingiere datos de los objetos de Salesforce CRM en Data Cloud?","options":["Data Loader","El conector de Amazon S3","El Import Wizard","El conector de Salesforce CRM"],"correct":[3],"explanation":"El CRM connector trae objetos estándar y personalizados.","i18n":{"en":{"stem":"Which connector ingests Salesforce CRM object data into Data Cloud?","options":["Data Loader","The Amazon S3 connector","The Import Wizard","The Salesforce CRM connector"],"explanation":"The CRM connector brings standard and custom objects."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo de datos se indexan para RAG en Data Cloud?","options":["Solo metadatos de configuración","Datos no estructurados como documentos o transcripciones","Solo informes","Solo campos numéricos de los objetos"],"correct":[1],"explanation":"Contenido no estructurado (UDMO) o campos de texto largo.","i18n":{"en":{"stem":"Which data is indexed for RAG in Data Cloud?","options":["Only configuration metadata","Unstructured data like documents or transcripts","Only reports","Only numeric object fields"],"explanation":"Unstructured content (UDMO) or long text fields."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un Unstructured Data Model Object (UDMO)?","options":["Un objeto de auditoría de prompts","Un segmento","Un DMO sin campos ni relaciones","Un DMO para contenido no estructurado"],"correct":[3],"explanation":"Los UDMO representan archivos o texto no estructurado para indexar.","i18n":{"en":{"stem":"What is an Unstructured Data Model Object (UDMO)?","options":["A prompt audit object","A segment","A DMO with no fields or relationships","A DMO for unstructured content"],"explanation":"UDMOs represent files or unstructured text for indexing."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos fuentes de contenido no estructurado puede indexar Data Cloud? (Elige 2)","options":["Reglas de validación","Campos de texto largo de objetos","Tipos de registro","Archivos en almacenamiento externo (p. ej. S3)","Perfiles de usuario"],"correct":[1,3],"explanation":"Archivos externos y campos de texto pueden indexarse.","i18n":{"en":{"stem":"Which two unstructured content sources can Data Cloud index? (Choose 2)","options":["Validation rules","Long text fields on objects","Record types","Files in external storage (e.g. S3)","User profiles"],"explanation":"External files and text fields can be indexed."}}},{"domain":"D3","source":"bank","stem":"¿Qué recurso necesita un administrador para gestionar Data Cloud?","options":["Una licencia de Chatter Free","El rol de director general","El perfil de usuario estándar sin permisos adicionales","Un conjunto de permisos de administración de Data Cloud"],"correct":[3],"explanation":"Hay permission sets como Data Cloud Admin.","i18n":{"en":{"stem":"What does an admin need to manage Data Cloud?","options":["A Chatter Free license","The CEO role","The standard user profile with no extras","A Data Cloud admin permission set"],"explanation":"There are permission sets like Data Cloud Admin."}}},{"domain":"D3","source":"bank","stem":"¿Qué son los espacios de datos (data spaces)?","options":["Carpetas de informes compartidas","Bibliotecas de archivos","Particiones lógicas de datos en Data Cloud","Sandboxes"],"correct":[2],"explanation":"Permiten separar datos por marca, región o unidad de negocio.","i18n":{"en":{"stem":"What are data spaces?","options":["Shared report folders","File libraries","Logical data partitions in Data Cloud","Sandboxes"],"explanation":"They separate data by brand, region or business unit."}}},{"domain":"D3","source":"bank","stem":"¿Qué consideración tiene un retriever respecto a los data spaces?","options":["No usa espacios de datos","Busca en el espacio de datos al que pertenece","Busca en todos los espacios sin restricción","Borra los otros espacios"],"correct":[1],"explanation":"El índice y el retriever están asociados a un data space.","i18n":{"en":{"stem":"What consideration does a retriever have regarding data spaces?","options":["It doesn't use data spaces","It searches the data space it belongs to","It searches all spaces without restriction","It deletes other spaces"],"explanation":"The index and retriever belong to a data space."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo de flujo se dispara con cambios en datos de Data Cloud?","options":["Flujo de pantalla","Flujo before-save de CRM","Flujo desencadenado por Data Cloud","Flujo de orquestación manual"],"correct":[2],"explanation":"Data Cloud-triggered flows reaccionan a cambios en DMOs o insights.","i18n":{"en":{"stem":"Which flow type fires on Data Cloud data changes?","options":["Screen flow","CRM before-save flow","Data Cloud-triggered flow","Manual orchestration flow"],"explanation":"Data Cloud-triggered flows react to DMO or insight changes."}}},{"domain":"D3","source":"bank","stem":"Un agente responde con información desactualizada de un manual. ¿Qué se revisa?","options":["El tono del agente","La actualización de la ingesta del índice","Los permisos de Chatter","La temperatura de la plantilla de prompt"],"correct":[1],"explanation":"El índice debe reflejar el contenido vigente.","i18n":{"en":{"stem":"An agent answers with outdated manual info. What's checked?","options":["The agent's tone","The index ingestion refresh","Chatter permissions","The prompt template temperature"],"explanation":"The index must reflect current content."}}},{"domain":"D3","source":"bank","stem":"¿Qué mejora la relevancia de los fragmentos recuperados?","options":["Quitar metadatos","Indexar documentos duplicados varias veces","Configurar bien el troceado y los filtros","Subir la temperatura del modelo"],"correct":[2],"explanation":"Tamaño de chunk, solapamiento y filtros afectan a la calidad.","i18n":{"en":{"stem":"What improves the relevance of retrieved chunks?","options":["Removing metadata","Indexing duplicate documents several times","Proper chunking and filters","Raising model temperature"],"explanation":"Chunk size, overlap and filters affect quality."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos metadatos útiles conviene conservar en los fragmentos indexados? (Elige 2)","options":["Título o fuente del documento","Contraseñas del autor","Perfil del administrador","Categoría o producto","Coste de almacenamiento"],"correct":[0,3],"explanation":"Metadatos permiten filtrar y citar fuentes.","i18n":{"en":{"stem":"Which two useful metadata should indexed chunks keep? (Choose 2)","options":["Document title or source","Author passwords","Admin profile","Category or product","Storage cost"],"explanation":"Metadata allow filtering and citing sources."}}},{"domain":"D3","source":"bank","stem":"¿Qué recomienda Salesforce sobre el contenido antes de indexarlo?","options":["Duplicarlo para mejorar la recuperación","Subir todo sin revisar para tener más datos","Limpiarlo y mantenerlo actualizado","Traducirlo a mano a todos los idiomas"],"correct":[2],"explanation":"La calidad del contenido determina la calidad de las respuestas.","i18n":{"en":{"stem":"What does Salesforce recommend about content before indexing?","options":["Duplicate it to improve retrieval","Upload everything unreviewed for more data","Clean it and keep it current","Hand-translate into every language"],"explanation":"Content quality drives answer quality."}}},{"domain":"D3","source":"bank","stem":"¿Cómo usa un agente los perfiles unificados de Data Cloud?","options":["Mediante reglas de colaboración","No puede usarlos","Mediante acciones o grounding con datos del perfil","Leyendo directamente el modelo de lenguaje"],"correct":[2],"explanation":"Acciones, data graphs y prompts acceden a los perfiles.","i18n":{"en":{"stem":"How does an agent use Data Cloud unified profiles?","options":["Via sharing rules","It can't","Via actions or grounding with profile data","By reading the language model directly"],"explanation":"Actions, data graphs and prompts access profiles."}}},{"domain":"D3","source":"bank","stem":"¿Qué indica el mapeo de datos en Data Cloud?","options":["Dónde están físicamente los servidores","Qué usuarios ven el agente","Cómo se relacionan los campos de un DLO con un DMO","El orden de los temas"],"correct":[2],"explanation":"Mapping vincula datos ingeridos con el modelo canónico.","i18n":{"en":{"stem":"What does data mapping in Data Cloud define?","options":["Where servers physically are","Which users see the agent","How DLO fields relate to a DMO","Topic order"],"explanation":"Mapping links ingested data to the canonical model."}}},{"domain":"D3","source":"bank","stem":"¿Qué consideración de seguridad hay al indexar documentos internos para un agente de clientes?","options":["Ninguna","Desactivar la Trust Layer","Indexar todo y confiar en las instrucciones del agente","No indexar contenido que el cliente no deba ver"],"correct":[3],"explanation":"El contenido recuperable debe ser apto para la audiencia.","i18n":{"en":{"stem":"What's a security consideration when indexing internal documents for a customer agent?","options":["None","Disable the Trust Layer","Index everything and trust agent instructions","Don't index content customers shouldn't see"],"explanation":"Retrievable content must suit the audience."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo de retriever crea Data Cloud por defecto al crear un índice?","options":["Ninguno: siempre hay que crearlo a mano","Un retriever para cada usuario","Un retriever de CRM","Un retriever por defecto del índice"],"correct":[3],"explanation":"Se genera un default retriever que puede personalizarse.","i18n":{"en":{"stem":"Which retriever does Data Cloud create by default with an index?","options":["None: it must always be built by hand","One retriever per user","A CRM retriever","A default retriever for the index"],"explanation":"A default retriever is generated and can be customized."}}},{"domain":"D3","source":"bank","stem":"¿Qué limita el número de resultados que un retriever devuelve al prompt?","options":["El año fiscal","El idioma del usuario","El número de licencias de Data Cloud","Su configuración de número de resultados"],"correct":[3],"explanation":"Se configura cuántos fragmentos devolver.","i18n":{"en":{"stem":"What limits how many results a retriever returns to the prompt?","options":["Fiscal year","User language","Number of Data Cloud licenses","Its result count setting"],"explanation":"You set how many chunks to return."}}},{"domain":"D3","source":"bank","stem":"¿Qué ventaja tiene la resolución de identidades para un agente de servicio?","options":["Reconoce al mismo cliente en distintos canales","Reduce el número de temas","Evita indexar documentos","Permite al agente saltarse los permisos"],"correct":[0],"explanation":"Una vista unificada personaliza el servicio.","i18n":{"en":{"stem":"What's identity resolution's benefit for a service agent?","options":["It recognizes the same customer across channels","It reduces topics","It avoids indexing documents","It lets the agent bypass permissions"],"explanation":"A unified view personalizes service."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos elementos componen el flujo RAG en Agentforce? (Elige 2)","options":["Borrado del índice tras cada respuesta","Generación con esos fragmentos en el prompt","Entrenamiento del modelo con cada consulta","Recuperación de fragmentos relevantes","Asignación de un perfil nuevo"],"correct":[1,3],"explanation":"Retrieve + augment + generate.","i18n":{"en":{"stem":"Which two elements make up the RAG flow in Agentforce? (Choose 2)","options":["Deleting the index after each answer","Generating with those chunks in the prompt","Training the model on each query","Retrieving relevant chunks","Assigning a new profile"],"explanation":"Retrieve + augment + generate."}}},{"domain":"D3","source":"bank","stem":"¿Qué es un segmento en Data Cloud?","options":["Una versión de plantilla","Un tema de agente","Un fragmento de documento indexado","Un grupo de perfiles que cumple criterios"],"correct":[3],"explanation":"Los segmentos se usan para activación y personalización.","i18n":{"en":{"stem":"What is a segment in Data Cloud?","options":["A template version","An agent topic","An indexed document chunk","A group of profiles meeting criteria"],"explanation":"Segments are used for activation and personalization."}}},{"domain":"D3","source":"bank","stem":"¿Qué indica una frecuencia de actualización de un data stream?","options":["Cada cuánto se ingieren datos nuevos","Cada cuánto se reentrena el modelo","Cada cuánto cambia el agente","Cada cuánto se borran los datos"],"correct":[0],"explanation":"Las programaciones pueden ser por lotes o streaming.","i18n":{"en":{"stem":"What does a data stream refresh frequency indicate?","options":["How often new data is ingested","How often the model retrains","How often the agent changes","How often data is deleted"],"explanation":"Schedules can be batch or streaming."}}},{"domain":"D3","source":"bank","stem":"¿Qué tipo de ingesta permite datos casi en tiempo real en Data Cloud?","options":["Carga manual de CSV mensual","Data Loader","Streaming (por ejemplo Ingestion API o Web SDK)","Exportación semanal de datos de CRM"],"correct":[2],"explanation":"Las APIs y SDK de streaming ingieren eventos rápidamente.","i18n":{"en":{"stem":"Which ingestion type allows near real-time data in Data Cloud?","options":["Monthly manual CSV upload","Data Loader","Streaming (e.g. Ingestion API or Web SDK)","Weekly CRM data export"],"explanation":"Streaming APIs and SDKs ingest events quickly."}}},{"domain":"D3","source":"bank","stem":"¿Qué recurso de Prompt Builder permite consultar un Calculated Insight?","options":["Una lista relacionada del objeto cuenta","Una regla de validación","Un informe de CRM","Campos de Data Cloud o un flujo que lo lea"],"correct":[3],"explanation":"Los insights se exponen como datos de Data Cloud.","i18n":{"en":{"stem":"Which Prompt Builder resource can query a Calculated Insight?","options":["An account related list","A validation rule","A CRM report","Data Cloud fields or a flow reading it"],"explanation":"Insights are exposed as Data Cloud data."}}},{"domain":"D3","source":"bank","stem":"¿Qué consideración de coste tiene Data Cloud?","options":["Es gratuito para cualquier volumen de datos","Consume créditos por ingesta, procesamiento y consultas","No tiene consumo","Solo cuesta al crear el primer índice"],"correct":[1],"explanation":"El modelo de consumo depende de las operaciones.","i18n":{"en":{"stem":"What cost consideration does Data Cloud have?","options":["It's free for any data volume","It consumes credits for ingestion, processing and queries","No consumption","It only costs when creating the first index"],"explanation":"Consumption depends on operations."}}},{"domain":"D3","source":"bank","stem":"¿Qué recomienda Salesforce sobre la granularidad de documentos para RAG?","options":["No importa","Fragmentos de una sola palabra","Indexar cada documento como un único bloque enorme","Fragmentos coherentes y de tamaño adecuado"],"correct":[3],"explanation":"Fragmentos demasiado grandes o pequeños reducen la calidad.","i18n":{"en":{"stem":"What does Salesforce recommend on document granularity for RAG?","options":["It doesn't matter","One-word chunks","Index each document as one huge block","Coherent, appropriately sized chunks"],"explanation":"Too large or small chunks reduce quality."}}},{"domain":"D3","source":"bank","stem":"¿Qué permite el Query Editor o SQL en Data Cloud?","options":["Programar agentes","Consultar y explorar los datos","Cambiar las reglas de colaboración","Editar el código del modelo de lenguaje"],"correct":[1],"explanation":"Sirve para validar datos y crear insights.","i18n":{"en":{"stem":"What does the Data Cloud Query Editor/SQL allow?","options":["Scheduling agents","Querying and exploring data","Changing sharing rules","Editing the language model's code"],"explanation":"It validates data and builds insights."}}},{"domain":"D3","source":"bank","stem":"Un retriever devuelve fragmentos de productos de otra región. ¿Qué se ajusta?","options":["El tono del agente","Los diseños de página","La temperatura del modelo","Filtros por región en el retriever"],"correct":[3],"explanation":"Los filtros limitan el contexto relevante.","i18n":{"en":{"stem":"A retriever returns chunks for another region's products. What's adjusted?","options":["Agent tone","Page layouts","Model temperature","Region filters on the retriever"],"explanation":"Filters limit relevant context."}}},{"domain":"D3","source":"bank","stem":"¿Qué dos acciones permiten que un agente use datos de Data Cloud en tiempo real? (Elige 2)","options":["Plantillas de prompt ancladas en Data Cloud","Reglas de validación de CRM","Plantillas de correo Classic","Diseños de página compactos","Acciones de flujo que consultan Data Cloud"],"correct":[0,4],"explanation":"Flujos y prompts pueden leer DMOs, insights y data graphs.","i18n":{"en":{"stem":"Which 